import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import { Order } from './order.entity';

@Injectable()
export class UsersService {
  constructor(
    @InjectRepository(User) private readonly userRepository: Repository<User>,
    @InjectRepository(Order) private readonly orderRepository: Repository<Order>,
  ) {}

  async findById(id: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { id } });
    if (!user) {
      // Expected domain case, but reported as a plain Error — not a typed
      // NotFoundException — so its "not found" nature disappears the moment
      // a catch block intercepts it.
      throw new Error('User not found');
    }
    return user;
  }

  async findOrdersByUserId(id: string): Promise<Order[]> {
    const user = await this.findById(id);
    // repository.find can also surface a raw driver/ORM error (bad connection,
    // malformed query) whose .message may carry table/column/query details.
    return this.orderRepository.find({ where: { userId: user.id } });
  }
}

// users.controller.ts
import { Controller, Get, Param } from '@nestjs/common';
import { UsersService } from './users.service';

@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Get(':id')
  async getUser(@Param('id') id: string) {
    try {
      const user = await this.usersService.findById(id);
      return user;
    } catch (err) {
      // Local try/catch: bypasses AllExceptionsFilter entirely.
      // Raw err.message goes straight to the client (hide-by-default violation).
      // No logger.error(...) call — an unexpected failure here leaves no trace.
      return { error: err.message };
    }
  }

  @Get(':id/orders')
  async getUserOrders(@Param('id') id: string) {
    try {
      const orders = await this.usersService.findOrdersByUserId(id);
      return orders;
    } catch (err) {
      // Same pattern repeated: every handler now decides its own error shape
      // instead of the one centralized envelope AllExceptionsFilter defines.
      return { error: err.message };
    }
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from "@nestjs/common";
import { Observable } from "rxjs";
import { tap, catchError } from "rxjs/operators";
import * as fs from "fs";
import chalk from "chalk";

const logFilePath = "./logs/app.log";

// Always-on pretty formatter — no NODE_ENV check, runs on every request
// regardless of whether anyone is watching a terminal.
function colorize(line: string): string {
  const parsed = JSON.parse(line);
  const header = chalk.cyan(`[${parsed.method}] ${parsed.url}`);
  const duration = chalk.yellow(`${parsed.durationMs}ms`);
  const body = chalk.gray(JSON.stringify(parsed.body, null, 2));
  const response = chalk.gray(JSON.stringify(parsed.response, null, 2));
  return `${header} ${duration}\n  body: ${body}\n  response: ${response}\n`;
}

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    const { method, url, body } = request;
    const startTime = Date.now();

    return next.handle().pipe(
      tap((responseBody) => {
        const durationMs = Date.now() - startTime;

        // Full request + response body embedded unconditionally at info level —
        // no level policy, no sampling, no field allow-list.
        const logEntry = {
          level: "info",
          method,
          url,
          durationMs,
          body,
          response: responseBody,
        };

        const line = colorize(JSON.stringify(logEntry));

        // Synchronous file write directly on the request path — blocks the
        // event loop on every single log call.
        fs.appendFileSync(logFilePath, line);
      }),
      catchError((error) => {
        const durationMs = Date.now() - startTime;

        // Error path is just as heavy as the happy path: same full body,
        // same colorize formatter, same sync write.
        const logEntry = {
          level: "error",
          method,
          url,
          durationMs,
          body,
          error: error?.message ?? error,
        };

        const line = colorize(JSON.stringify(logEntry));
        fs.appendFileSync(logFilePath, line);

        throw error;
      }),
    );
  }
}

