import { Injectable, Scope } from '@nestjs/common';

// THE CHANGE THAT REGRESSED PERFORMANCE:
// Declared request-scoped so each request can hold its own userId/tenantId.
@Injectable({ scope: Scope.REQUEST })
export class RequestContextService {
  private userId: string;
  private tenantId: string;

  setContext(userId: string, tenantId: string): void {
    this.userId = userId;
    this.tenantId = tenantId;
  }

  getUserId(): string {
    return this.userId;
  }

  getTenantId(): string {
    return this.tenantId;
  }
}

// request-context.middleware.ts
import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import { RequestContextService } from './request-context.service';

@Injectable()
export class RequestContextMiddleware implements NestMiddleware {
  constructor(private readonly requestContext: RequestContextService) {}

  use(req: Request, res: Response, next: NextFunction): void {
    const userId = req.header('x-user-id') ?? 'anonymous';
    const tenantId = req.header('x-tenant-id') ?? 'default';
    this.requestContext.setContext(userId, tenantId);
    next();
  }
}

// pricing.service.ts
import { Injectable } from '@nestjs/common';
import { RequestContextService } from './request-context.service';

// PricingService injects the now request-scoped RequestContextService,
// so Nest is forced to make PricingService request-scoped too.
@Injectable()
export class PricingService {
  constructor(private readonly requestContext: RequestContextService) {}

  calculatePrice(baseAmount: number): number {
    const tenantId = this.requestContext.getTenantId();
    const discount = this.getTenantDiscount(tenantId);
    return baseAmount * (1 - discount);
  }

  private getTenantDiscount(tenantId: string): number {
    return tenantId === 'enterprise' ? 0.15 : 0;
  }
}

