import { Injectable } from '@nestjs/common';
import { PricingService } from './pricing.service';
import { RequestContextService } from './request-context.service';

// OrderService depends on PricingService, which is now request-scoped,
// so OrderService is transitively dragged into request scope as well.
@Injectable()
export class OrderService {
  constructor(
    private readonly pricingService: PricingService,
    private readonly requestContext: RequestContextService,
  ) {}

  createOrder(baseAmount: number): { userId: string; total: number } {
    const total = this.pricingService.calculatePrice(baseAmount);
    return { userId: this.requestContext.getUserId(), total };
  }
}

