import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { APP_INTERCEPTOR } from '@nestjs/core';
import { Observable } from 'rxjs';
import { map, tap } from 'rxjs/operators';

/**
 * Per-request timing slot. Starts null; ExecutionTimer is supposed to
 * populate it on the way out, and ResponseTransform reads it when it
 * builds the response envelope.
 */
interface RequestMeta {
  executionMs: number | null;
}

/**
 * WRITER: measures how long the handler took and stores it on the
 * request so a later interceptor can read it.
 */
@Injectable()
export class ExecutionTimer implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    request.meta = (request.meta as RequestMeta) ?? { executionMs: null };

    const start = Date.now();

    return next.handle().pipe(
      tap(() => {
        // Outbound leg: write the measured duration.
        (request.meta as RequestMeta).executionMs = Date.now() - start;
      }),
    );
  }
}

/**
 * READER: wraps the handler's return value into the response envelope,
 * reading whatever ExecutionTimer left on the request.
 */
@Injectable()
export class ResponseTransform implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();

    return next.handle().pipe(
      map((data) => ({
        data,
        meta: {
          executionMs: (request.meta as RequestMeta | undefined)?.executionMs ?? null,
        },
      })),
    );
  }
}

/**
 * Global interceptor registration — order matters because interceptors
 * nest onion-style around the handler.
 */
export const GLOBAL_INTERCEPTORS = [
  { provide: APP_INTERCEPTOR, useClass: ExecutionTimer },
  { provide: APP_INTERCEPTOR, useClass: ResponseTransform },
];

import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import { randomUUID } from 'crypto';

// --- Minimal domain stubs, only what the bug needs to be visible ---
export interface CreateOrderDto {
  customerId: string;
  items: string[];
}

export interface Order {
  id: string;
  customerId: string;
}

@Injectable()
export class OrderRepository {
  async save(dto: CreateOrderDto): Promise<Order> {
    // Simulates a real DB round-trip: this is where control is handed
    // back to the event loop before the promise resolves.
    await new Promise((resolve) => setTimeout(resolve, 50));
    return { id: randomUUID(), customerId: dto.customerId };
  }
}

/**
 * Holds the "current request's" correlation id so any service can log
 * without prop-drilling requestId through every method signature.
 *
 * No explicit scope is declared here, so Nest instantiates this class
 * ONCE for the entire application (Scope.DEFAULT = singleton).
 */
@Injectable()
export class RequestContextService {
  private requestId: string;

  setRequestId(id: string): void {
    this.requestId = id;
  }

  getRequestId(): string {
    return this.requestId;
  }
}

/**
 * Runs at the very start of every incoming HTTP request and stamps
 * a fresh correlation id onto the shared context before the request
 * is allowed to proceed.
 */
@Injectable()
export class RequestContextMiddleware implements NestMiddleware {
  constructor(private readonly requestContextService: RequestContextService) {}

  use(req: Request, res: Response, next: NextFunction): void {
    const requestId = randomUUID();
    this.requestContextService.setRequestId(requestId);
    next();
  }
}

/**
 * Central log formatter used by every service in the app. It attaches
 * whatever requestId is currently sitting on RequestContextService to
 * each log line, so all log call sites stay correlation-aware for free.
 */
@Injectable()
export class AppLogger {
  constructor(private readonly requestContextService: RequestContextService) {}

  log(message: string): void {
    const requestId = this.requestContextService.getRequestId();
    // eslint-disable-next-line no-console
    console.log(`[requestId=${requestId}] ${message}`);
  }
}

/**
 * A typical domain service: does real async work (an actual `await`
 * suspend point) and logs before and after it.
 */
@Injectable()
export class OrderService {
  constructor(
    private readonly orderRepository: OrderRepository,
    private readonly logger: AppLogger,
  ) {}

  async create(dto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for customer ${dto.customerId}`);

    // Suspend point: while this await is pending, the event loop is
    // free to handle other incoming requests' middleware and handlers.
    const order = await this.orderRepository.save(dto);

    this.logger.log(`Order ${order.id} created successfully`);
    return order;
  }
}

