import { Injectable } from '@nestjs/common';

@Injectable()
export class CacheService {
  private readonly store = new Map<string, { value: unknown; expiresAt: number }>();

  set(key: string, value: unknown): void {
    const ttl = Number(process.env.CACHE_TTL ?? '60');
    this.store.set(key, { value, expiresAt: Date.now() + ttl * 1000 });
  }

  get(key: string): unknown {
    const entry = this.store.get(key);
    if (!entry || entry.expiresAt < Date.now()) {
      return undefined;
    }
    return entry.value;
  }
}

// ---------- src/session/session.service.ts ----------
import { Injectable } from '@nestjs/common';

@Injectable()
export class SessionService {
  private readonly sessions = new Map<string, { data: unknown; expiresAt: number }>();

  createSession(sessionId: string, data: unknown): void {
    // Same CACHE_TTL key as CacheService, but this reader trusts a different fallback.
    const ttl = Number(process.env.CACHE_TTL ?? '300');
    this.sessions.set(sessionId, { data, expiresAt: Date.now() + ttl * 1000 });
  }

  isValid(sessionId: string): boolean {
    const entry = this.sessions.get(sessionId);
    return !!entry && entry.expiresAt > Date.now();
  }
}

