import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Product } from './entities/product.entity';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
import { CatalogListingDto } from './dto/catalog-listing.dto';

@Injectable()
export class ProductsService {
  constructor(
    @InjectRepository(Product)
    private readonly productRepository: Repository<Product>,
  ) {}

  // HOT PATH: thousands of identical calls per minute. Every single
  // call re-runs this join + aggregate against Postgres — there is no
  // cache manager injected anywhere in this service, no memoization,
  // nothing short-circuits the SQL round-trip.
  async getCatalogListing(): Promise<CatalogListingDto[]> {
    const rows = await this.productRepository
      .createQueryBuilder('product')
      .innerJoin('product.category', 'category')
      .select('category.id', 'categoryId')
      .addSelect('category.name', 'categoryName')
      .addSelect('COUNT(product.id)', 'productCount')
      .addSelect('MIN(product.price)', 'minPrice')
      .addSelect(
        'SUM(CASE WHEN product.stock > 0 THEN 1 ELSE 0 END)',
        'inStockCount',
      )
      .groupBy('category.id')
      .addGroupBy('category.name')
      .orderBy('category.name', 'ASC')
      .getRawMany();

    return rows.map((row) => ({
      categoryId: row.categoryId,
      categoryName: row.categoryName,
      productCount: Number(row.productCount),
      minPrice: Number(row.minPrice),
      inStockCount: Number(row.inStockCount),
    }));
  }

  // Rare write path — a few times per hour, only when an admin edits
  // the catalog. Persists via the repository directly and never
  // touches any cache, so a naive TTL-only cache added on top of the
  // read path above would leave these edits invisible until the TTL
  // expires.
  async createProduct(dto: CreateProductDto): Promise<Product> {
    const product = this.productRepository.create(dto);
    return this.productRepository.save(product);
  }

  async updateProduct(id: string, dto: UpdateProductDto): Promise<Product> {
    await this.productRepository.update(id, dto);
    return this.productRepository.findOneByOrFail({ id });
  }
}

