import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  OneToOne,
  OneToMany,
  ManyToMany,
  JoinColumn,
  JoinTable,
} from 'typeorm';
import { Passport } from './passport.entity';
import { Toy } from './toy.entity';
import { Owner } from './owner.entity';

@Entity()
export class Cat {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  name: string;

  // 1-1: eager loading is declared on the ENTITY, not per query.
  @OneToOne(() => Passport, { eager: true })
  @JoinColumn()
  passport: Passport;

  // 1-N: a collection relation, also entity-level eager.
  @OneToMany(() => Toy, (toy) => toy.cat, { eager: true })
  toys: Toy[];

  // N-N: resolved through a join table, also entity-level eager.
  @ManyToMany(() => Owner, (owner) => owner.cats, { eager: true })
  @JoinTable()
  owners: Owner[];
}

