// cat.entity.ts
import { Entity, PrimaryGeneratedColumn, Column, OneToMany, OneToOne, ManyToMany } from 'typeorm';
import { Toy } from './toy.entity';
import { Passport } from './passport.entity';
import { Owner } from './owner.entity';

@Entity()
export class Cat {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  name: string;

  @Column()
  breed: string;

  // Lazy relation: TypeORM does NOT hydrate this on `find()`.
  // Accessing it later returns a Promise that fires its own query.
  @OneToMany(() => Toy, (toy) => toy.cat, { lazy: true })
  toys: Promise<Toy[]>;

  @OneToOne(() => Passport, (passport) => passport.cat, { lazy: true })
  passport: Promise<Passport>;

  @ManyToMany(() => Owner, (owner) => owner.cats, { lazy: true })
  owners: Promise<Owner[]>;
}

