// customer.schema.ts
import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Schema as MongooseSchema } from 'mongoose';

export type ActivityAction = 'login' | 'view' | 'click';

@Schema({ _id: false })
export class ActivityEntry {
  @Prop({ required: true })
  action: ActivityAction;

  @Prop({ required: true })
  timestamp: Date;
}

export const ActivityEntrySchema = SchemaFactory.createForClass(ActivityEntry);

export type CustomerDocument = Customer & Document;

@Schema({ timestamps: true })
export class Customer {
  // Login identifier - filtered on every login, no index declared.
  @Prop()
  email: string;

  @Prop()
  name: string;

  // Appended to on every login/view/click. Lives inside the parent document,
  // so it grows without bound for the lifetime of the customer.
  @Prop({ type: [ActivityEntrySchema], default: [] })
  activityLog: ActivityEntry[];

  // Free-form bag, accepts any shape - nothing constrains it before persistence.
  @Prop({ type: MongooseSchema.Types.Mixed })
  metadata: Record<string, unknown>;
}

export const CustomerSchema = SchemaFactory.createForClass(Customer);

// customer.service.ts
import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { Customer, CustomerDocument, ActivityAction } from './customer.schema';

@Injectable()
export class CustomerService {
  constructor(
    @InjectModel(Customer.name)
    private readonly customerModel: Model<CustomerDocument>,
  ) {}

  async create(body: Record<string, unknown>): Promise<CustomerDocument> {
    // `metadata` (and everything else in the request body) is written straight
    // through - no DTO, no class-validator, no shape check of any kind.
    const customer = new this.customerModel({
      email: body.email,
      name: body.name,
      metadata: body.metadata,
      activityLog: [],
    });
    return customer.save();
  }

  async findByEmail(email: string): Promise<CustomerDocument | null> {
    // Called on every login. `email` has no index, so this is a full
    // collection scan once the collection is no longer tiny.
    return this.customerModel.findOne({ email }).exec();
  }

  async recordActivity(
    customerId: string,
    action: ActivityAction,
  ): Promise<CustomerDocument | null> {
    // One push per login/view/click - the array has no cap and no TTL.
    return this.customerModel
      .findByIdAndUpdate(
        customerId,
        { $push: { activityLog: { action, timestamp: new Date() } } },
        { new: true },
      )
      .exec();
  }
}

