import { Injectable } from '@nestjs/common';
import { User } from './user.entity';

@Injectable()
export class EmailService {
  buildUnsubscribeLink(user: User): string {
    // Raw, sequential primary key, no signature, no expiry, no scoping to
    // a channel/category — anyone who can guess or increment userId owns this link.
    return `https://app.example.com/unsubscribe?userId=${user.id}`;
  }

  async sendOtp(user: User, code: string): Promise<void> {
    await this.dispatch(user, `Your code is ${code}`);
  }

  async sendOrderConfirmation(user: User, orderId: string): Promise<void> {
    await this.dispatch(user, `Order ${orderId} confirmed. ${this.buildUnsubscribeLink(user)}`);
  }

  async sendMarketingBlast(user: User, promo: string): Promise<void> {
    // Transactional and marketing mail go through the exact same send path,
    // both carrying the same unsubscribe link and gated by the same flag.
    await this.dispatch(user, `${promo} ${this.buildUnsubscribeLink(user)}`);
  }

  private async dispatch(user: User, body: string): Promise<void> {
    if (!user.notificationsEnabled) return;
    // ... actual provider send omitted
  }
}

