import { Injectable } from '@nestjs/common';
import { MailService } from '../mail/mail.service';

export interface Recipient {
  id: string;
  email: string;
}

@Injectable()
export class NotificationService {
  constructor(private readonly mailService: MailService) {}

  async sendAnnouncement(recipients: Recipient[], subject: string, body: string): Promise<void> {
    // BUG (bulk path): sequential awaited sends in one request.
    // No concurrency, no rate limit vs relay quota, no retry, no per-recipient
    // progress checkpoint -> a crash at recipient N loses progress 0..N-1,
    // and a slow relay makes this whole endpoint time out.
    for (const recipient of recipients) {
      await this.mailService.sendMail(recipient.email, subject, body);
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import Redis from 'ioredis';
import { SmsProviderService, SmsSendResult } from './sms-provider.service';

const OTP_TTL_SECONDS = 300;
const RESEND_AFTER_MS = 25_000;

interface StoredOtp {
  code: string;
  expiresAt: number;
}

@Injectable()
export class OtpService {
  private readonly logger = new Logger(OtpService.name);

  constructor(
    private readonly redis: Redis,
    private readonly smsProvider: SmsProviderService,
  ) {}

  /**
   * Generates a fresh OTP, stores it in Redis, and sends it over SMS.
   * Also arms a resend so the user gets the code "in case it didn't arrive".
   */
  async sendCode(phoneNumber: string): Promise<void> {
    const code = this.generateSixDigitCode();
    const expiresAt = Date.now() + OTP_TTL_SECONDS * 1000;

    const stored: StoredOtp = { code, expiresAt };
    await this.redis.set(
      this.otpKey(phoneNumber),
      JSON.stringify(stored),
      'EX',
      OTP_TTL_SECONDS,
    );

    const message = `Your verification code is ${code}. It expires in 5 minutes.`;

    // Fire the paid provider call and treat its synchronous response as the
    // outcome of the send.
    const res: SmsSendResult = await this.smsProvider.send(phoneNumber, message);

    if (res.status === 'queued') {
      // `queued` only means the provider ACCEPTED the request for delivery —
      // it is not proof the SMS reached the handset. The real delivery
      // outcome is never consumed anywhere after this line.
      this.logger.log(`OTP delivered to ${phoneNumber} (sid=${res.sid})`);
    } else {
      this.logger.warn(`OTP send rejected for ${phoneNumber}: status=${res.status}`);
    }

    // Unconditionally re-fire the same send path a fixed delay later, "in
    // case it didn't arrive" — regardless of whether the first message
    // actually delivered. Because the first send almost always does
    // deliver, this second call pays for a second SMS on nearly every
    // sign-in, which is what doubled the bill.
    setTimeout(() => {
      void this.sendCode(phoneNumber);
    }, RESEND_AFTER_MS);
  }

  private generateSixDigitCode(): string {
    return Math.floor(100000 + Math.random() * 900000).toString();
  }

  private otpKey(phoneNumber: string): string {
    return `otp:${phoneNumber}`;
  }
}

interface SmsSendResult {
  sid: string;
  status: 'queued' | 'failed' | 'undelivered';
}

import { Injectable, BadRequestException } from '@nestjs/common';
import Redis from 'ioredis';

/** Max wrong-code guesses allowed before the account is locked out. */
const MAX_ATTEMPTS = 5;

/** How long an OTP (and its attempt counter) stays valid, in seconds. */
const OTP_TTL_SECONDS = 300;

export class TooManyAttemptsException extends BadRequestException {
  constructor(userId: string) {
    super(`Too many OTP attempts for user ${userId}. Please request a new code.`);
  }
}

@Injectable()
export class OtpService {
  constructor(private readonly redis: Redis) {}

  /**
   * Verifies a submitted OTP code against the code stored for this user,
   * enforcing a MAX_ATTEMPTS cap on wrong guesses.
   */
  async verifyOtp(userId: string, submittedCode: string): Promise<boolean> {
    const attemptsKey = `otp:attempts:${userId}`;
    const codeKey = `otp:code:${userId}`;

    // Step 1: read the current attempt count.
    const attempts = Number((await this.redis.get(attemptsKey)) ?? 0);

    // Step 2: gate on the value we just read.
    if (attempts >= MAX_ATTEMPTS) {
      throw new TooManyAttemptsException(userId);
    }

    // Step 3: fetch the stored code (network round-trip; this is the slow part
    // of the request compared to the plain counter read above).
    const storedCode = await this.redis.get(codeKey);

    // Step 4: compare the submitted code against what's stored.
    const isMatch = !!storedCode && storedCode === submittedCode;

    if (!isMatch) {
      // Step 5: only spend an attempt once we know the guess was wrong,
      // and only start the TTL clock the first time this key is created.
      const newAttempts = await this.redis.incr(attemptsKey);
      if (attempts === 0) {
        await this.redis.expire(attemptsKey, OTP_TTL_SECONDS);
      }
      return false;
    }

    // Correct code: clear the counter so future logins start fresh.
    await this.redis.del(attemptsKey);
    await this.redis.del(codeKey);
    return true;
  }
}

