import {
  BadRequestException,
  Controller,
  Post,
  UploadedFile,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import * as fs from 'fs';
import * as path from 'path';
import { UploadRepository } from './upload.repository';

const UPLOAD_DIR = './uploads';
const ALLOWED_TYPES = ['image/png', 'image/jpeg'];

@Controller('files')
export class UploadController {
  constructor(private readonly uploadRepository: UploadRepository) {}

  @Post('upload')
  @UseInterceptors(FileInterceptor('file'))
  async uploadFile(@UploadedFile() file: Express.Multer.File) {
    // Build the on-disk name from a timestamp + whatever the client sent.
    const filename = `${Date.now()}-${file.originalname}`;
    const filePath = path.join(UPLOAD_DIR, filename);

    // Persist to disk first; we only look at content type afterwards.
    fs.writeFileSync(filePath, file.buffer);

    // Only the client-declared Content-Type is checked — nothing looks at
    // the actual bytes on disk.
    if (!ALLOWED_TYPES.includes(file.mimetype)) {
      throw new BadRequestException('Invalid file type');
    }

    const record = await this.uploadRepository.save({
      originalName: file.originalname,
      storedPath: filePath,
      mimeType: file.mimetype,
      size: file.size,
    });

    return {
      id: record.id,
      url: `/uploads/${filename}`,
    };
  }
}

// ── redis.provider.ts ────────────────────────────────────────────────────
import { Provider } from '@nestjs/common';
import Redis from 'ioredis';

export const REDIS_CLIENT = 'REDIS_CLIENT';

/**
 * Redis client provider for the app.
 * NOTE: instantiated with default ioredis options — no request-level
 * retry cap and the offline command queue left enabled.
 */
export const redisProvider: Provider = {
  provide: REDIS_CLIENT,
  useFactory: (): Redis => {
    return new Redis({
      host: process.env.REDIS_HOST ?? 'localhost',
      port: Number(process.env.REDIS_PORT ?? 6379),
      // no maxRetriesPerRequest override -> ioredis retries a command
      // internally many times before ever surfacing a rejection
      // no enableOfflineQueue override -> defaults to true, so commands
      // issued while the connection is down are queued instead of
      // erroring immediately
    });
  },
};

