import {
  Controller,
  Get,
  Inject,
  ServiceUnavailableException,
} from '@nestjs/common';
import Redis from 'ioredis';
import { REDIS_CLIENT } from './redis.provider';

@Controller('health')
export class HealthController {
  constructor(@Inject(REDIS_CLIENT) private readonly redis: Redis) {}

  @Get('ready')
  async ready(): Promise<{ status: string }> {
    try {
      // BUG: unbounded await — on a half-open TCP connection (far end
      // vanished without FIN/RST) this promise never resolves AND never
      // rejects, so control never reaches either branch below. The
      // request just hangs until the kubelet's probe timeoutSeconds
      // kills it.
      await this.redis.ping();
      return { status: 'ok' };
    } catch (err) {
      throw new ServiceUnavailableException({ status: 'unhealthy' });
    }
  }
}

