import { Controller, Get } from '@nestjs/common';
import { trace } from '@opentelemetry/api';

@Controller('orders')
export class OrdersController {
  @Get()
  async getOrders() {
    const tracer = trace.getTracer('app');
    const span = tracer.startSpan('business-work');
    try {
      const orders = await this.loadOrders();
      return orders;
    } finally {
      // Correctly ended — but with no auto-instrumented server
      // span ever created, this manual span has no parent to
      // attach to, so it may not surface as expected either.
      span.end();
    }
  }

  private async loadOrders() {
    return [{ id: 1, name: 'Order #1' }];
  }
}

// redis-health.indicator.ts
import { Injectable } from '@nestjs/common';
import { HealthIndicator, HealthIndicatorResult, HealthCheckError } from '@nestjs/terminus';
import Redis from 'ioredis';

@Injectable()
export class RedisHealthIndicator extends HealthIndicator {
  constructor(private readonly redisClient: Redis) {
    super();
  }

  // Shared Redis instance used by ALL replicas for caching.
  async pingCheck(key: string): Promise<HealthIndicatorResult> {
    try {
      const reply = await this.redisClient.ping();
      const isHealthy = reply === 'PONG';
      const result = this.getStatus(key, isHealthy);
      if (!isHealthy) {
        throw new HealthCheckError('Redis ping failed', result);
      }
      return result;
    } catch (err) {
      throw new HealthCheckError('Redis check failed', this.getStatus(key, false));
    }
  }
}

// health.controller.ts
import { Controller, Get } from '@nestjs/common';
import { HealthCheckService, HealthCheck, TypeOrmHealthIndicator } from '@nestjs/terminus';
import { RedisHealthIndicator } from './redis-health.indicator';

@Controller('health')
export class HealthController {
  constructor(
    private readonly health: HealthCheckService,
    private readonly db: TypeOrmHealthIndicator,
    private readonly redis: RedisHealthIndicator,
  ) {}

  // Wired to the Deployment's livenessProbe: failure ⇒ kubelet KILLS and restarts the pod.
  @Get('live')
  @HealthCheck()
  checkLiveness() {
    return this.health.check([
      // Legitimate: a wedged/corrupted in-process DB connection pool IS fixable by a restart.
      () => this.db.pingCheck('database'),
      // BUG: Redis is a shared downstream, not something a restart of THIS pod can repair.
      // Putting it in the liveness set means one Redis outage fails EVERY replica's
      // liveness check at once, and the resulting restart never revives Redis, so the
      // new pod fails liveness again the moment it comes up — an amplifying restart loop.
      () => this.redis.pingCheck('redis'),
    ]);
  }

  // Wired to the Deployment's readinessProbe: failure ⇒ pod pulled from Service endpoints, NO restart.
  @Get('ready')
  @HealthCheck()
  checkReadiness() {
    return this.health.check([
      () => this.db.pingCheck('database'),
      // Correct here: readiness failure just stops routing traffic to this pod
      // and self-heals the moment Redis comes back — no restart involved.
      () => this.redis.pingCheck('redis'),
    ]);
  }
}

