// src/config/cors.config.ts
import { CorsOptions } from '@nestjs/common/interfaces/external/cors-options.interface';

/**
 * Root domains of partners allowed to call this API with credentials
 * (cookies / Authorization headers) attached.
 */
const PARTNER_ROOT_DOMAINS = ['example.com', 'partner-app.io'];

/**
 * Accepts any host whose Origin string ends with one of our partner
 * root domains, e.g. https://app.example.com, https://staging.partner-app.io
 */
function isPartnerOrigin(origin: string): boolean {
  return PARTNER_ROOT_DOMAINS.some((domain) => origin.endsWith(domain));
}

type CorsCallback = (err: Error | null, allow?: string | boolean) => void;

export const corsConfig: CorsOptions = {
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  origin: (requestOrigin: string | undefined, callback: CorsCallback) => {
    if (!requestOrigin) {
      // Non-browser callers (server-to-server, curl) send no Origin header.
      callback(null, true);
      return;
    }

    if (!isPartnerOrigin(requestOrigin)) {
      // Reject anything outside the partner allow-list.
      callback(new Error(`Origin "${requestOrigin}" is not permitted by CORS policy`));
      return;
    }

    // Echo the caller's own Origin back so the browser accepts the
    // credentialed response, no matter which partner host called us.
    callback(null, requestOrigin);
  },
};

