        // Every worker process reads the same env var, so every worker
        // connects to the exact same physical database. JEST_WORKER_ID
        // is never read here.
        database: process.env.TEST_DB_NAME ?? "app_test",
        entities: [User],
        synchronize: true,
    })
    await dataSource.initialize()
    return dataSource
}

