export async function fetchUserAndOrder(userId: string, orderId: string) {
  const userRes = await http.get(`/users/${userId}`);
  const orderRes = await http.get(`/orders/${orderId}`);

  // The client can't parse every response through one path — it has to know,
  // per-endpoint, whether the payload lives at `.data` or `.result`.
  const user = userRes.data.data;
  const order = orderRes.data.result;

  return { user, order };
}

