@Entity()
export class Article {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  title: string;

  @Column("text")
  content: string;
}

/**
 * Boundary DTO for GET /articles — raw query strings are coerced into
 * bounded integers with sane defaults before the controller ever runs.
 */
export class ListArticlesQueryDto {
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page: number = 1;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  limit: number = 20;
}

@Injectable()
export class ArticlesService {
  constructor(
    @InjectRepository(Article)
    private readonly articleRepository: Repository<Article>,
  ) {}

  /**
   * Returns one page of articles for the given page/limit.
   */
  async findAll(page: number, limit: number): Promise<Article[]> {
    // Fetches the ENTIRE table — no where/skip/take criteria passed to the repository.
    const articles = await this.articleRepository.find();

    const offset = (page - 1) * limit;
    return articles.slice(offset, offset + limit);
  }
}

@Controller("articles")
export class ArticlesController {
  constructor(private readonly articlesService: ArticlesService) {}

  @Get()
  async list(@Query() query: ListArticlesQueryDto): Promise<Article[]> {
    return this.articlesService.findAll(query.page, query.limit);
  }
}

