import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { DocumentChunk } from './document-chunk.entity';

/** Minimum cosine similarity a chunk must reach to be considered relevant context. */
const SIMILARITY_THRESHOLD = 0.75;

/** Default number of chunks to hand back to the LLM as context. */
const DEFAULT_TOP_K = 5;

@Injectable()
export class RetrievalService {
  constructor(
    @InjectRepository(DocumentChunk)
    private readonly chunkRepository: Repository<DocumentChunk>,
  ) {}

  /**
   * Returns the k chunks most semantically similar to the given query embedding.
   */
  async retrieveTopK(
    queryEmbedding: number[],
    k: number = DEFAULT_TOP_K,
  ): Promise<string[]> {
    // Load the entire corpus, embeddings included, into application memory.
    const rows = await this.chunkRepository.find();

    const scored = rows.map((row) => ({
      row,
      score: this.cosineSimilarity(queryEmbedding, row.embedding),
    }));

    scored.sort((a, b) => b.score - a.score);

    const topK = scored.slice(0, k);

    return topK
      .filter((s) => s.score >= SIMILARITY_THRESHOLD)
      .map((s) => s.row.content);
  }

  private cosineSimilarity(a: number[], b: number[]): number {
    let dot = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dot += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    return dot / (Math.sqrt(normA) * Math.sqrt(normB));
  }
}

import { Body, Controller, Post, Res } from '@nestjs/common';
import { Response } from 'express';

interface ChatStreamDto {
  prompt: string;
}

/**
 * Stand-in for the real LLM client — yields tokens one at a time as the
 * model generates them.
 */
class LlmService {
  async *stream(prompt: string): AsyncGenerator<string> {
    const tokens = simulateModelTokens(prompt);
    for (const token of tokens) {
      await new Promise((resolve) => setTimeout(resolve, 40));
      yield token;
    }
  }
}

function simulateModelTokens(prompt: string): string[] {
  return `Here is the answer to: ${prompt}`.split(' ');
}

@Controller('chat')
export class ChatController {
  private readonly llmService = new LlmService();

  @Post('stream')
  async streamChat(@Body() dto: ChatStreamDto, @Res() res: Response): Promise<void> {
    // Header setup: opens an SSE stream, but nothing here tells any
    // intermediary (or the client) not to buffer it, and the headers
    // are never flushed up front.
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Connection', 'keep-alive');

    let accumulated = '';
    let tokenCount = 0;

    // Every token is folded into a local accumulator instead of being
    // written to the response as it arrives.
    for await (const token of this.llmService.stream(dto.prompt)) {
      accumulated += token;
      tokenCount++;
    }

    // Only after generation has fully finished does anything get sent —
    // one single SSE frame carrying the entire answer.
    res.write(`data: ${JSON.stringify({ text: accumulated, tokenCount })}\n\n`);
    res.write('data: [DONE]\n\n');
    res.end();
  }
}

import { Controller, Get, Query, Res } from '@nestjs/common';
import { Response } from 'express';
import { LlmProviderService } from './llm-provider.service';
import { BillingService } from './billing.service';

@Controller('chat')
export class ChatStreamController {
  constructor(
    private readonly llmProvider: LlmProviderService,
    private readonly billing: BillingService,
  ) {}

  @Get('stream')
  async streamChat(
    @Query('prompt') prompt: string,
    @Query('userId') userId: string,
    @Res() res: Response,
  ): Promise<void> {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.flushHeaders();

    // Cancellation primitive for this generation. Created up front so it can
    // be threaded into the provider call below.
    const abortController = new AbortController();
    const signal = abortController.signal;

    // Plumbing into the provider is correct: the signal IS passed through,
    // so the provider is fully capable of stopping mid-generation.
    const stream = await this.llmProvider.streamCompletion({ prompt, signal });

    let tokenCount = 0;
    for await (const token of stream) {
      res.write(`data: ${JSON.stringify({ token })}\n\n`);
      tokenCount++;
    }

    // Terminal frame + billing always run once the loop above finishes,
    // regardless of what happened to the client's connection.
    res.write('data: [DONE]\n\n');
    await this.billing.charge(userId, tokenCount);
    res.end();
  }
}

