}

export interface RetrievalResult {
  grounded: boolean;
  citations: string[];
  answer: string;
}

/**
 * Turns a question into a query vector. Real deployments swap this for a
 * hosted embedding model; today it's a simple non-negative bag-of-words
 * embedding used for local dev and tests.
 */
@Injectable()
export class BagOfWordsEmbedder {
  private readonly vocabulary: string[];

  constructor(vocabulary: string[]) {
    this.vocabulary = vocabulary;
  }

  embed(text: string): number[] {
    const tokens = text.toLowerCase().split(/\W+/).filter(Boolean);
    const counts = new Map<string, number>();
    for (const token of tokens) {
      counts.set(token, (counts.get(token) ?? 0) + 1);
    }
    // Non-negative bag-of-words vector: every component is >= 0.
    return this.vocabulary.map((word) => counts.get(word) ?? 0);
  }
}

@Injectable()
export class RetrievalService {
  private readonly logger = new Logger(RetrievalService.name);

  constructor(
    private readonly pool: Pool,
    private readonly embedder: BagOfWordsEmbedder,
  ) {}

  async retrieve(question: string): Promise<RetrievalResult> {
    const queryVector = this.embedder.embed(question);

    const rows = await this.queryChunks(queryVector);

    // Keep only chunks whose score clears the similarity bar.
    const relevant = rows.filter((r) => r.score >= SIMILARITY_THRESHOLD);

    if (relevant.length === 0) {
      this.logger.debug(`No chunks passed SIMILARITY_THRESHOLD for question: "${question}"`);
      return {
        grounded: false,
        citations: [],
        answer: "I don't know based on the current knowledge base.",
      };
    }

    return {
      grounded: true,
      citations: relevant.map((r) => r.id),
      answer: this.composeAnswer(relevant),
    };
  }

  private async queryChunks(queryVector: number[]): Promise<ChunkRow[]> {
    const vectorLiteral = `[${queryVector.join(',')}]`;

    // embedding <=> $1 is pgvector's cosine-distance operator: 0 means
    // identical direction, 2 means opposite. ORDER BY ascending distance is
    // correct here — the closest (most relevant) chunks come first.
    const sql = `
      SELECT id, content, embedding <=> $1 AS score
      FROM chunks
      ORDER BY embedding <=> $1 ASC
      LIMIT $2
    `;

    const result = await this.pool.query<ChunkRow>(sql, [vectorLiteral, TOP_K]);
    return result.rows;
  }

  private composeAnswer(chunks: ChunkRow[]): string {
    return chunks.map((c) => c.content).join('\n\n');
  }
}

import { Injectable, Logger, HttpException, HttpStatus } from '@nestjs/common';

interface CompletionResult {
  text: string;
  tokensUsed: number;
}

interface CompletionProvider {
  complete(prompt: string): Promise<CompletionResult>;
}

const PRICE_PER_TOKEN = 0.000021; // USD per token, per provider price sheet
const REQUEST_ALLOWANCE = 60; // requests refilled per window
const BUDGET_LIMIT = 50; // USD, hard spend cap for this service

@Injectable()
export class AiCompletionService {
  private readonly logger = new Logger(AiCompletionService.name);

  // Single shared counter, refilled on a timer every window and
  // decremented once per incoming request.
  private remainingRequests = REQUEST_ALLOWANCE;

  // Running total spend for the service, accumulated as a floating-point
  // dollar amount.
  private totalSpent = 0;

  constructor(private readonly provider: CompletionProvider) {}

  async handleCompletion(
    userId: string,
    prompt: string,
  ): Promise<CompletionResult> {
    // 1. Rate limit check.
    if (this.remainingRequests <= 0) {
      throw new HttpException(
        'Too many requests, please try again later',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }
    this.remainingRequests--;

    // 2. Call the provider — this is what actually spends money.
    const result = await this.provider.complete(prompt);

    // 3. Track cost as a float dollar figure.
    const cost = result.tokensUsed * PRICE_PER_TOKEN;
    this.totalSpent += cost;

    // 4. Budget check, done after the call has already been paid for.
    if (this.totalSpent > BUDGET_LIMIT) {
      this.logger.warn(
        `Budget exceeded: spent=${this.totalSpent}, limit=${BUDGET_LIMIT}`,
      );
    }

    // 5. Return the completion regardless of budget state.
    return result;
  }
}

import { Injectable } from '@nestjs/common';
import { GraphQLError, GraphQLSchema, graphql } from 'graphql';

export const PERSISTED_QUERY_NOT_FOUND = 'PersistedQueryNotFound';

@Injectable()
export class PersistedQueryService {
  // Maps a SHA-256 query hash to the raw GraphQL query text it stands for.
  // No max size, no TTL, no eviction -- entries live here forever.
  private readonly store = new Map<string, string>();

  constructor(private readonly schema: GraphQLSchema) {}

  /**
   * Called when a client re-sends the full query text after the server
   * replied PersistedQueryNotFound for its hash, so later requests from
   * any client can go hash-only.
   */
  register(hash: string, query: string): void {
    this.store.set(hash, query);
  }

  /**
   * Called on every request that carries a persisted-query hash. Looks up
   * the query text registered under that hash and executes it; an unknown
   * hash means the client still needs to send the full query once.
   */
  async execute(hash: string, variables: Record<string, unknown>) {
    const query = this.store.get(hash);

    if (!query) {
      throw new GraphQLError(PERSISTED_QUERY_NOT_FOUND, {
        extensions: { code: 'PERSISTED_QUERY_NOT_FOUND' },
      });
    }

    return graphql({
      schema: this.schema,
      source: query,
      variableValues: variables,
    });
  }
}

import DataLoader from 'dataloader';
import { Query, Resolver } from '@nestjs/graphql';
import { Injectable } from '@nestjs/common';

interface UserRecord {
  id: string;
  name: string;
}

interface PostRecord {
  id: string;
  title: string;
  authorId: string;
}

interface UserDataSource {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
}

/**
 * Built fresh per incoming request inside the Apollo context factory, so the
 * loader's in-memory cache never leaks results across requests.
 */
export function createUserLoader(db: UserDataSource): DataLoader<string, UserRecord> {
  return new DataLoader<string, UserRecord>(async (ids: readonly string[]) => {
    // Exactly one multi-key round-trip per batch tick.
    const placeholders = ids.map((_, i) => `$${i + 1}`).join(', ');
    const rows = await db.query<UserRecord>(
      `SELECT * FROM users WHERE id IN (${placeholders})`,
      [...ids],
    );
    const rowById = new Map(rows.map((row) => [row.id, row]));

    // One log line per batch dispatch — this is the fingerprint we check in prod.
    // eslint-disable-next-line no-console
    console.log(`[batch] users -> [${ids.join(',')}]`);

    // DataLoader requires the output array to line up 1:1 with the input ids.
    return ids.map((id) => rowById.get(id) ?? new Error(`User ${id} not found`));
  });
}

export interface GraphQLContext {
  userLoader: DataLoader<string, UserRecord>;
}

@Injectable()
class PostService {
  async findAll(): Promise<PostRecord[]> {
    return [
      { id: 'p1', title: 'Intro to GraphQL', authorId: 'u1' },
      { id: 'p2', title: 'DataLoader deep dive', authorId: 'u2' },
      { id: 'p3', title: 'Schema stitching', authorId: 'u3' },
    ];
  }
}

@Resolver('Query')
export class PostQueryResolver {
  constructor(private readonly postService: PostService) {}

  @Query('postsWithAuthors')
  async postsWithAuthors(
    _parent: unknown,
    _args: unknown,
    context: GraphQLContext,
  ): Promise<Array<PostRecord & { author: UserRecord }>> {
    const posts = await this.postService.findAll();

    const postsWithAuthors: Array<PostRecord & { author: UserRecord }> = [];
    for (const post of posts) {
      // Awaiting the pending load right here, inside the loop, fully settles
      // this iteration before the next one calls `.load()` again — each key
      // lands in its own dispatch window instead of a shared one.
      const author = await context.userLoader.load(post.authorId);
      postsWithAuthors.push({ ...post, author });
    }

    return postsWithAuthors;
  }
}

import { ApolloServer } from "apollo-server-express";
import { InMemoryLRUCache } from "apollo-server-caching";
import express from "express";
import http from "http";
import { typeDefs } from "./schema/typeDefs";
import { resolvers } from "./schema/resolvers";

/**
 * Deployment shape (see k8s/deployment.yaml):
 *   replicas: 4
 *   service:
 *     type: ClusterIP
 *     sessionAffinity: None   // LB round-robins every request across the
 *                             // 4 pods, no client stickiness guaranteed
 *
 * A client's initial "register" call and every later hash-only call can
 * therefore land on ANY of the 4 replicas, independently of each other.
 */

// Automatic Persisted Queries (APQ): a client registers a query once,
// then sends only its 64-character SHA-256 hash on every later call.
// This cache is what remembers the hash -> query string mapping.
const persistedQueryCache = new InMemoryLRUCache();
// ^ Default APQ store: a plain in-process Map wrapped in an LRU cache,
//   instantiated fresh inside THIS Node process at boot. Each of the 4
//   replicas ends up holding its own independent registry with zero
//   state shared between them and zero persistence across restarts.

const app = express();
const httpServer = http.createServer(app);

const server = new ApolloServer({
  typeDefs,
  resolvers,
  persistedQueries: {
    cache: persistedQueryCache,
  },
  // No TTL, no eviction policy tied to any shared/durable store —
  // just an unbounded-until-restart local Map.
});

async function bootstrap(): Promise<void> {
  await server.start();
  server.applyMiddleware({ app });

  httpServer.listen(4000, () => {
    console.log(`GraphQL server ready at :4000${server.graphqlPath}`);
  });
}

bootstrap();

/**
 * Request flow this cache produces at 4-replica / round-robin scale:
 *
 * 1. Client -> replica A: { persistedQuery: { sha256Hash } }, no `query`.
 *    Replica A looks up `sha256Hash` in ITS OWN `persistedQueryCache`.
 *    Miss -> Apollo returns the `PERSISTED_QUERY_NOT_FOUND` error.
 *
 * 2. Client retries with BOTH `query` and `sha256Hash`. Whichever
 *    replica the load balancer routes this retry to (not necessarily A)
 *    validates the hash and runs
 *    `persistedQueryCache.set(sha256Hash, query)` — but only inside
 *    that one replica's local Map.
 *
 * 3. Later hash-only calls for the same query only succeed when
 *    round-robin happens to route back to the replica that learned it —
 *    roughly a 1-in-4 chance across 4 replicas, matching the ~75%
 *    PERSISTED_QUERY_NOT_FOUND rate observed in production.
 *
 * 4. Any restart of that replica (deploy, crash, rolling update) wipes
 *    its `persistedQueryCache` entirely, so every hash it had learned
 *    falls back to step 1 — a fresh miss storm right after every deploy.
 */

import DataLoader from 'dataloader';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { Book } from './book.entity';

@Injectable()
export class AuthorBooksLoaderFactory {
  constructor(
    @InjectRepository(Book)
    private readonly bookRepo: Repository<Book>,
  ) {}

  // Contract callers rely on: the loader matches results back to callers by
  // POSITION in `authorIds`, so the batch fn must return exactly one array
  // per key, in the same order as `authorIds`.
  createLoader(): DataLoader<string, Book[]> {
    return new DataLoader<string, Book[]>((authorIds) =>
      this.batchLoadBooks(authorIds),
    );
  }

  private async batchLoadBooks(
    authorIds: readonly string[],
  ): Promise<Book[][]> {
    // One batched query against the data source instead of N separate ones.
    const rows = await this.bookRepo.find({
      where: { authorId: In([...authorIds]) },
    });

    // Group rows into per-author buckets, keyed by first-seen order in `rows`.
    const grouped: Record<string, Book[]> = {};
    for (const row of rows) {
      if (!grouped[row.authorId]) {
        grouped[row.authorId] = [];
      }
      grouped[row.authorId].push(row);
    }

    // Return the grouped lists in the order they were built above.
    return Object.values(grouped);
  }
}

