import { Module } from '@nestjs/common';
import { PubSub } from 'graphql-subscriptions';

export const PUB_SUB = 'PUB_SUB';

// NOTE: `new PubSub()` from `graphql-subscriptions` keeps its subscribers
// and topics in a plain in-process JavaScript object (an in-memory event
// bus). It only ever sees `publish()`/`asyncIterator()` calls made inside
// THIS Node process.
@Module({
  providers: [
    {
      provide: PUB_SUB,
      useValue: new PubSub(),
    },
  ],
  exports: [PUB_SUB],
})
export class PubSubModule {}

// ---- src/comments/comments.resolver.ts ----
import { Inject } from '@nestjs/common';
import { Args, Mutation, Resolver, Subscription } from '@nestjs/graphql';
import { PubSub } from 'graphql-subscriptions';
import { PUB_SUB } from './pubsub.module';
import { CommentsService } from './comments.service';
import { Comment } from './models/comment.model';
import { AddCommentInput } from './dto/add-comment.input';

const COMMENT_ADDED_TOPIC = 'commentAdded';

@Resolver(() => Comment)
export class CommentsResolver {
  constructor(
    private readonly commentsService: CommentsService,
    @Inject(PUB_SUB) private readonly pubSub: PubSub,
  ) {}

  // PRODUCER: persists the comment, then publishes it to the topic.
  // This mutation is a stateless HTTP request — the load balancer routes
  // it to whichever of the 3 replicas is next in line.
  @Mutation(() => Comment)
  async addComment(@Args('input') input: AddCommentInput): Promise<Comment> {
    const comment = await this.commentsService.create(input);

    await this.pubSub.publish(COMMENT_ADDED_TOPIC, { commentAdded: comment });

    return comment;
  }

  // CONSUMER: the client's subscription WebSocket is a long-lived
  // connection pinned to whichever single replica accepted the upgrade.
  // asyncIterator only yields events published on THIS replica's own
  // in-memory PubSub instance.
  @Subscription(() => Comment, {
    name: 'commentAdded',
  })
  commentAdded() {
    return this.pubSub.asyncIterator(COMMENT_ADDED_TOPIC);
  }
}

