@Injectable()
export class RefreshTokenStrategy extends PassportStrategy(Strategy, 'jwt-refresh') {
  constructor(
    private readonly usersRepository: Repository<User>,
    configService: ConfigService,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromHeader('x-refresh-token'),
      secretOrKey: configService.get<string>('JWT_REFRESH_SECRET'),
    });
  }

  // Already loads the full user row and hands it to req.user.
  async validate(payload: { sub: string }): Promise<User> {
    const user = await this.usersRepository.findOne({ where: { id: payload.sub } });
    if (!user) {
      throw new UnauthorizedException('Invalid refresh token');
    }
    return user;
  }
}

// auth.service.ts
@Injectable()
export class AuthService {
  constructor(
    private readonly usersRepository: Repository<User>,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async rotateRefreshTokens(
    userId: string,
    presentedRefreshToken: string,
  ): Promise<{ accessToken: string; refreshToken: string }> {
    // Duplicate fetch: the guard already loaded this exact user in validate().
    const user = await this.usersRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new UnauthorizedException('Invalid refresh token');
    }

    // Reuse/replay detection — must not regress.
    const isValid = await bcrypt.compare(presentedRefreshToken, user.hashedRefreshToken);
    if (!isValid) {
      throw new UnauthorizedException('Refresh token has already been rotated or is invalid');
    }

    const payload = { sub: user.id, email: user.email, roles: user.roles };

    // Two independent signing calls, awaited sequentially instead of concurrently.
    const accessToken = await this.jwtService.signAsync(payload, {
      expiresIn: '15m',
      secret: this.configService.get<string>('JWT_ACCESS_SECRET'),
    });
    const refreshToken = await this.jwtService.signAsync(payload, {
      expiresIn: '7d',
      secret: this.configService.get<string>('JWT_REFRESH_SECRET'),
    });

    // Work factor cranked from the lesson baseline of 10 up to 14 on every rotation.
    const hashedRefreshToken = await bcrypt.hash(refreshToken, 14);

    // Hash-only storage; rotation overwrites the previous hash.
    user.hashedRefreshToken = hashedRefreshToken;
    await this.usersRepository.save(user);

    return { accessToken, refreshToken };
  }

  async logout(userId: string): Promise<void> {
    await this.usersRepository.update({ id: userId }, { hashedRefreshToken: null });
  }
}

interface OAuthProfile {
  providerId: string
  email: string
  name: string
  picture: string
  locale: string
}

interface UpsertResult {
  user: User
  isNewUser: boolean
}

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private readonly usersRepository: Repository<User>,
  ) {}

  async upsertOAuthUser(profile: OAuthProfile): Promise<UpsertResult> {
    // Read #1: try to find the user by the OAuth provider id.
    let user = await this.usersRepository.findOne({
      where: { providerId: profile.providerId },
    })

    let isNewUser = false

    if (!user) {
      // Read #2: fall back to an email match (sequential, only on miss).
      user = await this.usersRepository.findOne({
        where: { email: profile.email },
      })

      if (!user) {
        user = this.usersRepository.create({
          providerId: profile.providerId,
          email: profile.email,
          name: profile.name,
          picture: profile.picture,
          locale: profile.locale,
        })
        isNewUser = true
      } else {
        user.providerId = profile.providerId
      }
    }

    // Unconditional write: always refresh the profile fields and save,
    // even when nothing about the user actually changed.
    user.name = profile.name
    user.picture = profile.picture
    user.locale = profile.locale
    user = await this.usersRepository.save(user)

    return { user, isNewUser }
  }
}

