import { useState, ChangeEvent } from 'react';
import { socket } from './socket';

interface MessageInputProps {
  roomId: string;
  userId: string;
}

export function MessageInput({ roomId, userId }: MessageInputProps) {
  const [value, setValue] = useState('');

  // Fires on EVERY keystroke — this is the flood source.
  // A user typing at a normal pace easily produces 5+ of these
  // per second, all forwarded to every other room member.
  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setValue(e.target.value);
    socket.emit('typing', { roomId, userId });
  };

  return (
    <input
      value={value}
      onChange={handleChange}
      placeholder="Type a message..."
    />
  );
}

