// CLIENT — TypingIndicator.tsx
// ============================================================
import { useEffect, useRef, useState } from 'react';
import { socket } from './socket';

interface TypingIndicatorProps {
  roomId: string;
}

const FADE_MS = 1500;

export function TypingIndicator({ roomId }: TypingIndicatorProps) {
  const [isTyping, setIsTyping] = useState(false);
  const fadeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const onTyping = (data: { userId: string }) => {
      setIsTyping(true);

      // No-renewal fade window: if no new `typing` event arrives
      // within FADE_MS, the indicator auto-hides. Any emit more
      // frequent than this window is pure waste with zero visible effect.
      if (fadeTimer.current) clearTimeout(fadeTimer.current);
      fadeTimer.current = setTimeout(() => setIsTyping(false), FADE_MS);
    };

    socket.on('typing', onTyping);
    return () => {
      socket.off('typing', onTyping);
      if (fadeTimer.current) clearTimeout(fadeTimer.current);
    };
  }, [roomId]);

  if (!isTyping) return null;
  return <div className="typing-indicator">Someone is typing…</div>;
}

