  // authenticated identity to the socket:
  //   client.data.user = { id: payload.sub, username: payload.username }
  // Every socket reaching the handlers below is already authenticated.

  @SubscribeMessage("room:join")
  handleJoin(
    @ConnectedSocket() client: Socket,
    @MessageBody() body: JoinRoomDto,
  ): void {
    client.join(body.room)
  }

  @SubscribeMessage("chat:message")
  handleMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() body: ChatMessageDto,
  ): void {
    const { username, room, text } = body

    this.server.to(room).emit("chat:message", {
      username,
      text,
    })
  }
