import { Injectable, Logger, OnModuleDestroy } from "@nestjs/common"
import { Processor, WorkerHost, InjectQueue } from "@nestjs/bullmq"
import { Job, Queue } from "bullmq"
import { createTransport, Transporter } from "nodemailer"

interface SendEmailJobData {
    to: string
    subject: string
    html: string
}

// Pooled SMTP transport - the provider connection pool is capped at 10
// sockets, so at most 10 sendMail calls can be "in flight" against the
// wire at any moment; anything beyond that just waits for a free socket.
const emailTransport: Transporter = createTransport({
    host: "smtp.mailprovider.example.com",
    port: 587,
    secure: false,
    auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
    },
    pool: true,
    maxConnections: 10,
    maxMessages: Infinity,
})

@Processor("email", {
    // One job at a time: the worker never has more than a single
    // sendMail() in flight, so it can never benefit from the idle time
    // each job spends waiting on the network round-trip.
    concurrency: 1,
})
@Injectable()
export class EmailWorker extends WorkerHost implements OnModuleDestroy {
    private readonly logger = new Logger(EmailWorker.name)

    constructor(@InjectQueue("email") private readonly emailQueue: Queue) {
        super()
        this.logRemainingBacklog()
    }

    /**
     * Reports backlog size and rough CPU usage on an interval so operators
     * can see the drain rate. This is how the ~50,000-job backlog and the
     * ~5% CPU reading were observed in production.
     */
    private logRemainingBacklog(): void {
        setInterval(async () => {
            const waiting = await this.emailQueue.getWaitingCount()
            const cpuPercent = Math.round(process.cpuUsage().user / 1_000_000)
            this.logger.log(
                `email queue backlog: ${waiting} waiting, cpu ~${cpuPercent}%`,
            )
        }, 60_000)
    }

    /**
     * Processes a single "send email" job. The body does essentially
     * nothing but await the SMTP round-trip - there is no CPU-heavy work
     * here, which is why the process idles at ~5% CPU while jobs drain
     * roughly one per second at concurrency 1.
     */
    async process(job: Job<SendEmailJobData>): Promise<void> {
        const { to, subject, html } = job.data

        await emailTransport.sendMail({
            from: "no-reply@starci-academy.example.com",
            to,
            subject,
            html,
        })
    }

    async onModuleDestroy(): Promise<void> {
        emailTransport.close()
    }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Between, Repository } from 'typeorm';
import { endOfYesterday, startOfYesterday } from 'date-fns';

import { Order } from '../orders/order.entity';
import { DailyStats } from './daily-stats.entity';
import { ExchangeRateService } from '../exchange-rate/exchange-rate.service';

/**
 * In-memory shape of the nightly rollup. The only copy of this ever
 * lives here, in this process's heap, until the final save.
 */
interface DailyAccumulator {
  totalOrders: number;
  totalRevenue: number;
  totalRefunds: number;
  totalItemsSold: number;
}

@Injectable()
export class SchedulerService {
  private readonly logger = new Logger(SchedulerService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepo: Repository<Order>,
    @InjectRepository(DailyStats)
    private readonly statsRepo: Repository<DailyStats>,
    private readonly exchangeRateService: ExchangeRateService,
  ) {}

  /**
   * Lightweight sibling job — expected to fire every 5 minutes.
   * This is the one that users notice firing late every night.
   */
  @Cron('*/5 * * * *')
  async syncExchangeRates(): Promise<void> {
    const rates = await this.exchangeRateService.fetchLatestRates();
    await this.exchangeRateService.persistRates(rates);
    this.logger.log(`Synced ${Object.keys(rates).length} exchange rates`);
  }

  /**
   * Nightly aggregation. Runs entirely inline in the scheduler's own
   * process: decide-when and do-the-work are the same method.
   */
  @Cron('0 2 * * *')
  async aggregateDailyStats(): Promise<void> {
    const date = startOfYesterday();
    const rangeEnd = endOfYesterday();

    this.logger.log(`Starting daily stats aggregation for ${date.toISOString()}`);

    // Pulls the entire day's rows into process memory before doing anything.
    const orders = await this.orderRepo.find({
      where: {
        createdAt: Between(date, rangeEnd),
      },
    });

    // Multi-minute CPU/await span. `accumulator` is the only copy of the
    // partial result and it is never persisted mid-flight.
    const accumulator: DailyAccumulator = orders.reduce(
      (acc, order) => {
        acc.totalOrders += 1;
        acc.totalRevenue += order.totalAmount;
        acc.totalRefunds += order.refundedAmount ?? 0;
        acc.totalItemsSold += order.items.length;
        return acc;
      },
      { totalOrders: 0, totalRevenue: 0, totalRefunds: 0, totalItemsSold: 0 },
    );

    // Single terminal write. A crash any time before this line loses the
    // entire night's aggregation for `date`, and nothing retries it.
    await this.statsRepo.save({
      date,
      ...accumulator,
    });

    this.logger.log(`Finished daily stats aggregation for ${date.toISOString()}`);
  }
}

