// notification.processor.ts
import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Injectable, Logger } from '@nestjs/common';
import { Job } from 'bullmq';
import { MailerService } from '../mailer/mailer.service';

interface NotificationCampaignJobData {
  campaignId: string;
  recipients: readonly string[]; // ~5,000 entries for a full "notify all" blast
}

@Injectable()
@Processor('notifications', {
  // Lock TTL: the per-job liveness signal the worker holds while it runs.
  // If it isn't renewed before this elapses, the queue assumes the worker
  // died and re-delivers the job to another worker.
  lockDuration: 30_000, // 30s
  // stalledInterval (~30s) and maxStalledCount left at BullMQ defaults.
})
export class NotificationProcessor extends WorkerHost {
  private readonly logger = new Logger(NotificationProcessor.name);

  constructor(private readonly mailer: MailerService) {
    super();
  }

  async process(job: Job<NotificationCampaignJobData>): Promise<void> {
    const { campaignId, recipients } = job.data;
    this.logger.log(
      `worker=${process.env.WORKER_ID} jobId=${job.id} active (campaign=${campaignId}, recipients=${recipients.length})`,
    );

    // Sequential send loop over ~5,000 recipients, one external HTTP call
    // each — total wall-clock runtime is several minutes, well past the
    // 30s lockDuration above. There is no job.extendLock() / job.updateProgress()
    // call anywhere in this loop, so the lock is never renewed while the
    // worker is busy sending.
    for (const recipient of recipients) {
      await this.mailer.send(recipient, campaignId);
      // no dedupe/idempotency check here either — every recipient gets
      // contacted again if this jobId is ever processed a second time.
    }

    this.logger.log(`worker=${process.env.WORKER_ID} jobId=${job.id} batch complete`);
  }
}

// main.ts (worker process bootstrap)
import { NestFactory } from '@nestjs/core';
import { WorkerModule } from './worker.module';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.createApplicationContext(WorkerModule);
  await app.init();
  // No process.on('SIGTERM', ...) handler: the worker never stops pulling
  // new jobs or waits for the in-flight job to finish before the process
  // is killed. A normal rolling deploy can kill a mid-send worker at any
  // point in the loop above.
}
bootstrap();

