// capacity-estimate.ts
const PEAK_FACTOR = 5 // x5 peak factor -- never explained where this multiplier came from
const THRESHOLD_QPS = 1000 // the single magic threshold the whole architecture call hinges on
const RETENTION_YEARS = 10

interface TrafficInputs {
  dailyActiveUsers: number
  requestsPerUserPerDay: number
  avgRecordSizeBytes: number
}

interface CapacityEstimate {
  peakQps: number
  recommendation: 'distributed store' | 'single relational node'
  storageBytes: number
}

function estimateCapacity(inputs: TrafficInputs): CapacityEstimate {
  const { dailyActiveUsers, requestsPerUserPerDay, avgRecordSizeBytes } = inputs

  const averageQps = (dailyActiveUsers * requestsPerUserPerDay) / 86400 // seconds/day
  const peakQps = averageQps * PEAK_FACTOR

  // ONE global decision branch -- the core defect: peakQps is only ever
  // compared against the bare constant THRESHOLD_QPS, never against any
  // component's actual measured capacity (a relational node's real ceiling
  // is roughly 1-5K write QPS; a cache node's is far higher).
  const recommendation: CapacityEstimate['recommendation'] =
    peakQps > THRESHOLD_QPS ? 'distributed store' : 'single relational node'

  // Incomplete: no replicationFactor multiplier (e.g. x3) and no
  // indexOverhead factor, so this understates the real 10-year footprint.
  const storageBytes =
    dailyActiveUsers * requestsPerUserPerDay * avgRecordSizeBytes * 365 * RETENTION_YEARS

  return { peakQps, recommendation, storageBytes }
}

// Example run cited in the PR description:
const result = estimateCapacity({
  dailyActiveUsers: 926_640,
  requestsPerUserPerDay: 40,
  avgRecordSizeBytes: 500,
})
// -> peakQps = 2145, recommendation = 'distributed store'
console.log(result)

// WriteService: runs on every replica (stateless), all replicas share one DB.
// A single Redis-backed lock protects every write from lost updates.

const GLOBAL_WRITE_LOCK = "global:write:lock";

interface DistributedLock {
  // Redis SETNX-style / Redlock acquire: blocks (or retries) until the key is held.
  acquire(key: string): Promise<void>;
  // Releases the previously acquired key.
  release(key: string): Promise<void>;
}

interface ResourceRow {
  id: string;
  value: unknown;
}

class WriteService {
  constructor(
    private readonly lock: DistributedLock,
    private readonly db: {
      queryOne(sql: string, params: unknown[]): Promise<ResourceRow | null>;
      execute(sql: string, params: unknown[]): Promise<{ rowsAffected: number }>;
    },
  ) {}

  async updateResource(resourceId: string, newValue: unknown): Promise<void> {
    await this.lock.acquire(GLOBAL_WRITE_LOCK);
    try {
      const row = await this.db.queryOne(
        "SELECT id, value FROM resource WHERE id = $1",
        [resourceId],
      );
      if (!row) {
        throw new Error(`Resource ${resourceId} not found`);
      }

      const computedNewValue = newValue;

      await this.db.execute(
        "UPDATE resource SET value = $1 WHERE id = $2",
        [computedNewValue, resourceId],
      );
    } finally {
      await this.lock.release(GLOBAL_WRITE_LOCK);
    }
  }
}

import express from "express";

const app = express();
const PORT = process.env.PORT || 3000;

// Module-level state — allocated once when THIS process boots.
// Nothing here is shared across replicas; each container gets its own copy.
let requestCount = 0;
const startTime = Date.now();

// Runs on every request that THIS replica happens to receive
// (which, behind the LB, is only ever a slice of total traffic).
app.use((req, res, next) => {
  requestCount++;
  next();
});

app.get("/metrics", (req, res) => {
  res.json({
    requestCount,
    uptime: Date.now() - startTime,
    memory: process.memoryUsage().heapUsed,
  });
});

app.get("/health", (req, res) => {
  res.status(200).send("ok");
});

app.listen(PORT, () => {
  console.log(`Replica ${process.pid} listening on port ${PORT}`);
});

/**
 * Deployment sketch (not code under review, just context for the scenario):
 *
 * services:
 *   app:
 *     image: my-service:latest
 *     deploy:
 *       replicas: 4          # N identical, independently-booted processes
 *   lb:
 *     image: nginx
 *     # round-robins every incoming request (including /metrics polls)
 *     # across the 4 "app" replicas — clients only ever see the LB's
 *     # single public address, never a specific replica.
 *     ports:
 *       - "80:80"
 *
 * The on-call engineer only ever calls http://lb/metrics. Two consecutive
 * calls can land on two different replicas, each reporting its own
 * requestCount/uptime/memory — there is no shared counter, no aggregation
 * step, and no per-node labeling anywhere in this service.
 */

// ---------- nginx.conf ----------
// http {
//   upstream backend {
//     server app1:3000;
//     server app2:3000;
//     server app3:3000;
//     // no load-balancing directive here -> nginx defaults to round-robin
//   }
//
//   server {
//     listen 80;
//
//     location / {
//       proxy_pass http://backend;
//       proxy_set_header Host $host;
//     }
//   }
// }

// ---------- server.ts (deployed identically on app1, app2, app3) ----------
import express, { Request, Response } from "express";
import crypto from "crypto";

const app = express();
app.use(express.json());

// Lightweight read endpoint: near-zero cost per request.
app.get("/status", (_req: Request, res: Response) => {
  res.json({ ok: true, uptimeSeconds: process.uptime() });
});

// CPU-bound endpoint: runs a heavy SYNCHRONOUS computation directly
// on the main thread, blocking the single event loop for its entire duration.
app.post("/compute", (req: Request, res: Response) => {
  const { records } = req.body as { records: number[] };

  // Simulate a heavy aggregation / report-crunching / hashing workload.
  // This loop runs synchronously on the main thread with no yielding,
  // no worker_threads, and no async offload.
  let digest = crypto.createHash("sha256");
  let aggregate = 0;

  for (let i = 0; i < records.length; i++) {
    for (let pass = 0; pass < 50_000; pass++) {
      aggregate = (aggregate + records[i] * pass) % 1_000_000_007;
      digest.update(String(aggregate));
    }
  }

  res.json({
    aggregate,
    hash: digest.digest("hex"),
  });
});

// Single process per replica: one event loop, no cluster module,
// no worker_threads pool to offload CPU-bound work.
app.listen(3000, () => {
  console.log("Service listening on port 3000");
});

// balances table: accountId (PK), amount
// NOTE: no `version`, no `updatedAt`, no vector-clock column — a row carries
// no way to order concurrent writes across regions.

interface BalanceRow {
  accountId: string;
  amount: number;
}

interface BalanceStore {
  getAmount(accountId: string): number;
  setAmount(accountId: string, amount: number): void;
}

interface PeerClient {
  replicate(accountId: string, amount: number): Promise<void>;
}

// Region A: AP chosen "for availability" — the service must never reject a
// transfer just because the peer region is unreachable.
@Injectable()
export class BalanceService {
  private readonly logger = new Logger(BalanceService.name);

  constructor(
    private readonly db: BalanceStore,
    private readonly peerClient: PeerClient,
  ) {}

  applyTransfer(accountId: string, amount: number): { ok: boolean } {
    const current = this.db.getAmount(accountId);
    const newAmount = current + amount;

    // 1. Commit locally first so region A never blocks on the network.
    this.db.setAmount(accountId, newAmount);

    // 2. "Sync" to the peer region — fire-and-forget, best effort only.
    this.peerClient.replicate(accountId, newAmount).catch((err) => {
      this.logger.warn('replication failed', err);
      // no retry, no durable outbox/queue — the failed update is just dropped
    });

    // 3. Return success immediately, before the peer has confirmed anything.
    return { ok: true };
  }
}

// Region B: receives whatever the peer sends and applies it verbatim.
@Injectable()
export class BalanceReplicationReceiver {
  constructor(private readonly db: BalanceStore) {}

  onReplicate(accountId: string, amount: number): void {
    // Last message to ARRIVE wins — no version check, no merge,
    // no conflict-resolution step, and overwrites whatever value is there.
    this.db.setAmount(accountId, amount);
  }
}

// There is no anti-entropy / reconcile job anywhere in this module that
// would re-compare the two regions' balances and re-converge them after a
// network partition heals.

// setup.js — sharding configuration + write paths for the "events" collection
const { MongoClient } = require("mongodb");

/**
 * One-time cluster setup: enable sharding on the database and
 * shard the events collection to spread write load across shards.
 */
async function setupSharding(client) {
  const admin = client.db("admin");

  await admin.command({ enableSharding: "app" });

  // Range shard key on createdAt — chosen so range scans over time stay
  // co-located on a shard.
  await admin.command({
    shardCollection: "app.events",
    key: { createdAt: 1 },
  });
}

/**
 * Write path: every new event is inserted here.
 * userId identifies the actor, status starts as "pending".
 */
async function insertEvent(client, { userId, status }) {
  const events = client.db("app").collection("events");

  return events.insertOne({
    userId,
    status,
    createdAt: new Date(), // always "now" -> strictly increasing per insert
  });
}

/**
 * Nightly maintenance job: archive rows that have been sitting in
 * "pending" status for too long.
 */
async function runMaintenance(client) {
  const events = client.db("app").collection("events");

  const result = await events.updateMany(
    { status: "pending" },
    { $set: { status: "archived", updatedAt: new Date() } }
  );

  console.log(`Archived ${result.modifiedCount} events`);
  return result;
}

module.exports = { setupSharding, insertEvent, runMaintenance };

import { Pool } from 'pg';

// Module-scope pools: all writes go to the primary, all reads go to the read-replica.
const primaryPool = new Pool({
  host: process.env.PG_PRIMARY_HOST,
  database: process.env.PG_DATABASE,
  user: process.env.PG_USER,
  password: process.env.PG_PASSWORD,
});

const replicaPool = new Pool({
  host: process.env.PG_REPLICA_HOST,
  database: process.env.PG_DATABASE,
  user: process.env.PG_USER,
  password: process.env.PG_PASSWORD,
});

interface Profile {
  id: string;
  bio: string;
}

/**
 * Updates the user's bio. Writes always go to the primary.
 * Returns as soon as the primary commits — does not wait for the
 * change to be replayed on the replica.
 */
async function updateBio(userId: string, newBio: string): Promise<void> {
  await primaryPool.query(
    'UPDATE users SET bio = $1 WHERE id = $2',
    [newBio, userId],
  );
  // COMMIT has happened on the primary here. No synchronous_commit,
  // no wait on replica LSN before returning to the caller.
}

/**
 * Reads a user's profile. All reads (including "reload after save")
 * go to the replica to keep load off the primary.
 */
async function getProfile(userId: string): Promise<Profile | null> {
  const result = await replicaPool.query<Profile>(
    'SELECT id, bio FROM users WHERE id = $1',
    [userId],
  );
  return result.rows[0] ?? null;
}

/**
 * Request flow: save the new bio, then immediately reload the profile
 * to send back the "fresh" state to the client.
 */
async function saveBioAndReload(userId: string, newBio: string): Promise<Profile | null> {
  await updateBio(userId, newBio);
  const reloaded = await getProfile(userId);
  return reloaded;
}

/**
 * Diagnostic query run against the primary to inspect streaming
 * replication lag to the read-replica.
 */
async function getReplicationLag(): Promise<{ replication_lag_bytes: number }[]> {
  const result = await primaryPool.query(`
    SELECT
      application_name,
      pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replication_lag_bytes
    FROM pg_stat_replication;
  `);
  return result.rows;
}

export { updateBio, getProfile, saveBioAndReload, getReplicationLag };

