import Redis from "ioredis";

const MAX_FEED_SIZE = 200;

interface ScoredPost {
  score: number;
  member: string;
}

/**
 * Seeds a user's ranked feed sorted set and trims it to the configured max size.
 */
export async function seedFeed(userId: string, posts: ScoredPost[]): Promise<void> {
  const redis = new Redis({
    host: process.env.REDIS_HOST,
    port: Number(process.env.REDIS_PORT ?? 6379),
  });

  const key = `feed:${userId}`;

  for (const post of posts) {
    await redis.zadd(key, post.score, post.member);
  }

  await redis.zremrangebyrank(key, 0, -(MAX_FEED_SIZE + 1));
}

import { Injectable } from "@nestjs/common";
import { Repository } from "typeorm";
import { InjectRepository } from "@nestjs/typeorm";
import Redis from "ioredis";
import { Post } from "./entities/post.entity";
import { KolFollow } from "./entities/kol-follow.entity";

@Injectable()
export class FeedService {
  constructor(
    private readonly redis: Redis,
    @InjectRepository(Post)
    private readonly posts: Repository<Post>,
    @InjectRepository(KolFollow)
    private readonly kolFollows: Repository<KolFollow>,
  ) {}

  // Salted per-KOL key: the salt spreads a hot KOL's cache entry across
  // shards instead of letting one key become a single hot spot.
  private getKolCacheKey(kolId: string): string {
    const salt = kolId.slice(-2);
    return `feed:kol:${kolId}:${salt}`;
  }

  async getFeed(userId: string): Promise<Post[]> {
    // No cap, no ordering: every KOL the user follows is pulled in,
    // unbounded, on every single call.
    const followedKols = await this.kolFollows.find({ where: { userId } });

    const merged: Post[] = [];

    for (const kol of followedKols) {
      const key = this.getKolCacheKey(kol.kolId);

      // Always hits Postgres, once per followed KOL, no matter how
      // recently this same KOL's posts were already fetched.
      const posts = await this.posts.find({
        where: { authorId: kol.kolId },
        order: { scoreMs: "DESC" },
        take: 50,
      });

      // Written after the DB read, but nothing ever reads this key back
      // before the query above runs, so the 60s TTL never gets used.
      await this.redis.set(key, JSON.stringify(posts), "EX", 60);

      merged.push(...posts);
    }

    return merged.sort((a, b) => b.scoreMs - a.scoreMs);
  }
}

import Redis from "ioredis";

const redis = new Redis();
const feedKey = "feed:recent";

interface Post {
  postId: string;
  createdAt: Date;
  score_ms: number; // epoch-millisecond timestamp derived from createdAt
}

/**
 * Seeds the recent-posts feed ZSET from a batch of posts.
 * NOTE: `posts` is intentionally NOT pre-sorted by time — it's iterated
 * in whatever order the source happened to return them.
 */
async function seedFeed(posts: Post[]): Promise<void> {
  let insertOrder = 0;

  for (const post of posts) {
    // Score is meant to make ZREVRANGE return newest-first.
    await redis.zadd(feedKey, insertOrder, post.postId);
    insertOrder++;
  }
}

/**
 * Reads the 20 most recent posts, newest first.
 * Intended behavior: ZREVRANGE returns members ordered by score,
 * highest score first, so this SHOULD be newest-first — assuming
 * the score actually encodes recency.
 */
async function getFeed(): Promise<string[]> {
  const ids = await redis.zrevrange(feedKey, 0, 19);
  return ids;
}

export { seedFeed, getFeed, feedKey };

import { Redis } from "ioredis";

const redis = new Redis();

const SALT_SLOTS = 8;
// Fixed placeholder id used when computing a celebrity's salted cache key.
const CELEBRITY_ID = "celebrity";

interface Post {
  postId: string;
  authorId: string;
  createdAt: number;
  score: number;
}

/** Builds one of the salt-spread cache keys for a celebrity's pulled-posts cache. */
function saltedKey(authorId: string, slot: number): string {
  return `celeb:${authorId}:slot:${slot}`;
}

function rankByScore(posts: Post[]): Post[] {
  return [...posts].sort((a, b) => b.score - a.score);
}

export class FeedService {
  constructor(private readonly redisClient: Redis = redis) {}

  /**
   * Builds a user's home timeline by merging their fan-out-on-write push
   * timeline (regular authors) with fan-out-on-read pulls from followed
   * celebrities, then ranks the combined list.
   */
  async getHomeTimeline(userId: string): Promise<Post[]> {
    const pushTimeline = await this.readPushTimeline(userId);
    const celebIds = await this.getFollowedCelebrities(userId);
    const celebrityPosts = await Promise.all(
      celebIds.map((id) => this.getCelebrityPosts(id)),
    );

    const merged = rankByScore([...pushTimeline, ...celebrityPosts.flat()]);
    return merged;
  }

  /** Reads the precomputed push timeline written by fan-out-on-write. */
  private async readPushTimeline(userId: string): Promise<Post[]> {
    const raw = await this.redisClient.lrange(`push_timeline:${userId}`, 0, -1);
    return raw.map((entry) => JSON.parse(entry) as Post);
  }

  private async getFollowedCelebrities(userId: string): Promise<string[]> {
    return this.redisClient.smembers(`user:${userId}:celebrities`);
  }

  /** Pulls a celebrity's recent posts at read time from the salted cache. */
  private async getCelebrityPosts(celebId: string): Promise<Post[]> {
    const posts: Post[] = [];
    for (let slot = 0; slot < SALT_SLOTS; slot++) {
      const key = saltedKey(CELEBRITY_ID, slot);
      const raw = await this.redisClient.lrange(key, 0, -1);
      posts.push(...raw.map((entry) => JSON.parse(entry) as Post));
    }
    return posts;
  }

  /**
   * Called when an author's follower count crosses the KOL threshold;
   * switches their fan-out strategy from write-time push to read-time pull.
   */
  async onCrossThreshold(authorId: string): Promise<void> {
    await this.redisClient.hset(`author:${authorId}`, "mode", "celebrity");
  }
}

import { Request, Response } from "express";
import { store } from "./object-store";

type AssetType = "playlist" | "segment";

// Long-TTL, immutable directive for versioned, content-addressed assets.
// Safe ONLY because the URL itself changes whenever the bytes change —
// versioned assets never change once published.
const staticCacheControl = "public, s-maxage=31536000, immutable";

function classifyAsset(key: string): AssetType {
  return key.endsWith(".m3u8") ? "playlist" : "segment";
}

export async function serveAsset(req: Request, res: Response): Promise<void> {
  const key = req.params.key;
  const assetType = classifyAsset(key);
  const isPlaylist = assetType === "playlist";

  const object = await store.get(key);

  if (!object) {
    // Unknown or momentarily-missing key: bare hard 404, no Cache-Control
    // of its own. The shared edge falls back to its default caching
    // policy for this response, so a key that is only briefly missing at
    // publish time can get cached as "not found" and stay that way long
    // after the object actually exists.
    res.sendStatus(404);
    return;
  }

  // Refactor merged both asset types into one header assignment: the
  // playlist branch got wired to the same year-long immutable directive
  // that only makes sense for versioned segments, so live viewers are
  // pinned to a stale playlist for up to a year with no natural recovery.
  if (isPlaylist) {
    res.setHeader("Cache-Control", staticCacheControl);
  } else {
    res.setHeader("Cache-Control", staticCacheControl);
  }

  res.setHeader(
    "Content-Type",
    isPlaylist ? "application/vnd.apple.mpegurl" : "video/MP2T",
  );
  res.send(object.body);
}

// Lazy (on-demand) transcoding for a video-delivery pipeline.
// Adaptive-bitrate HLS renditions are produced the first time a video is requested for playback.

interface RenditionManifest {
  videoId: string;
  masterPlaylistKey: string;
  rungs: string[];
}

const RUNGS = ["1080p", "720p", "480p"] as const;

// Minimal storage/transcoder clients used by this handler.
declare const objectStorage: {
  exists(key: string): Promise<boolean>;
  write(key: string, body: Buffer | string): Promise<void>;
};
declare function ffmpegTranscode(videoId: string, rung: string): Promise<Buffer>;

export async function getOrCreateRenditions(videoId: string): Promise<RenditionManifest> {
  const masterKey = `renditions/${videoId}/master.m3u8`;

  // 1. Existence check: has this video already been encoded?
  const alreadyEncoded = await objectStorage.exists(masterKey);
  if (alreadyEncoded) {
    return { videoId, masterPlaylistKey: masterKey, rungs: [...RUNGS] };
  }

  // 2. Cold path: not encoded yet, so run the full three-rung ladder inline,
  //    directly on this request, with no hand-off to a queue.
  for (const rung of RUNGS) {
    const segment = await ffmpegTranscode(videoId, rung);
    await objectStorage.write(`renditions/${videoId}/${rung}.ts`, segment);
  }

  // 3. Write the master manifest and mark the video done. Every request that
  //    fell through step 1 reaches this same block independently, so they all
  //    write to the same videoId-derived keys at roughly the same time.
  await objectStorage.write(masterKey, buildMasterPlaylist(videoId, RUNGS));

  return { videoId, masterPlaylistKey: masterKey, rungs: [...RUNGS] };
}

function buildMasterPlaylist(videoId: string, rungs: readonly string[]): string {
  return rungs.map((rung) => `renditions/${videoId}/${rung}.ts`).join("\n");
}

// Note: there is no upload-time step anywhere in this pipeline that pre-encodes
// a video before it is first played — every video, hot or cold, is transcoded
// strictly on demand at first view.

// ================= nginx.conf (edge) =================
# Shared cache zone for the video-delivery edge
proxy_cache_path /var/cache/nginx/video levels=1:2 keys_zone=video_cache:200m
                  max_size=50g inactive=24h use_temp_path=off;

upstream origin_upstream {
    server origin.internal:8080;
}

server {
    listen 443 ssl;
    server_name edge.starci.video;

    # Manifests, segments, and poster/thumbnail assets all flow through here
    location ~* \.(m3u8|ts|mp4|jpg|jpeg|png|webp)$ {
        proxy_cache video_cache;

        # Cache key: includes the full request URI (path + query string).
        # /playlist.m3u8?utm_source=fb&utm_campaign=launch
        # /playlist.m3u8?utm_source=tw&utm_medium=social
        # /playlist.m3u8   (no params at all)
        # all serve byte-identical content but hash to three DIFFERENT keys.
        proxy_cache_key "$scheme$request_method$host$request_uri";

        proxy_cache_valid 200 302 10m;
        proxy_cache_valid 404 1m;

        # Observability lever: HIT / MISS / EXPIRED / BYPASS per response
        add_header X-Cache-Status $upstream_cache_status;

        proxy_pass http://origin_upstream;
        proxy_set_header Host $host;
        proxy_set_header Accept-Encoding $http_accept_encoding;
    }
}

