// ── NestJS origin service (only delegates eviction) ────────────────────────
import { Injectable, Logger } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';

/**
 * Fires the HTTP PURGE that asks the edge to evict a stale cache entry.
 * WHY: shares the same HttpService/axios instance used for normal content
 * fetches, so it silently inherits that client's default `Accept-Encoding`
 * header on every outbound call, including this one.
 */
@Injectable()
export class EdgeCacheService {
  private readonly logger = new Logger(EdgeCacheService.name);
  private readonly edgeBase = 'http://edge.video.internal';

  constructor(private readonly httpService: HttpService) {}

  /** Fetches manifest/metadata content through the shared client. */
  async fetchManifest(uri: string): Promise<unknown> {
    const res = await firstValueFrom(
      this.httpService.request({ method: 'GET', url: `${this.edgeBase}${uri}` }),
    );
    return res.data;
  }

  /**
   * Purges the edge's cached variant for `uri` after metadata republish.
   * BUG: reuses the shared client, whose axios defaults attach
   * `Accept-Encoding: gzip, deflate` to this PURGE request too. The edge
   * cache is keyed URI-only but stores an encoding-specific variant under
   * `Vary: Accept-Encoding`, so the purge module can't find a match, answers
   * 412, and evicts nothing — yet the success path below never looks at
   * `res.status`, only at whether an exception was thrown.
   */
  async purge(uri: string): Promise<{ purged: boolean }> {
    try {
      await firstValueFrom(
        this.httpService.request({
          method: 'PURGE',
          url: `${this.edgeBase}${uri}`,
        }),
      );
      return { purged: true };
    } catch (err) {
      this.logger.error(`Edge purge failed for ${uri}`, err as Error);
      return { purged: false };
    }
  }
}

import { promises as fs } from "fs";
import path from "path";
