// checkout.controller.ts
import { Request, Response } from "express";
import { redis } from "./redis";
import { db } from "./db";
import { logger } from "./logger";

interface CreateOrderBody {
  userId: string;
  items: { sku: string; qty: number }[];
  amount: number;
}

// orders table: UNIQUE(idempotency_key)
export async function createOrder(req: Request, res: Response): Promise<void> {
  const idempotencyKey = req.headers["idempotency-key"] as string;
  const body = req.body as CreateOrderBody; // never hashed/fingerprinted anywhere
  const cacheKey = "idem:" + idempotencyKey;

  // Fast-path guard: look up a cached result for this key.
  try {
    const cached = await redis.get(cacheKey);
    if (cached) {
      // No fingerprint of the original body is stored or compared here --
      // any request with this key replays whatever was cached, unconditionally.
      res.status(200).json(JSON.parse(cached));
      return;
    }
  } catch (err) {
    // Redis unreachable -- log and fall through as if there were no cached
    // entry, so every request proceeds to the DB path during an outage.
    logger.warn("redis down, continuing without idempotency cache", err);
  }

  // Slow-path: insert the order. A concurrent/retried request with the same
  // key collides on the UNIQUE(idempotency_key) constraint; that violation
  // is not caught here, so it propagates and the framework returns a 500.
  const order = await db.insertOrder({
    idempotencyKey,
    userId: body.userId,
    items: body.items,
    amount: body.amount,
  });

  const response = {
    orderId: order.id,
    status: order.status,
    amount: order.amount,
  };
  // Again: only the response is cached, no body fingerprint alongside it.
  await redis.set(cacheKey, JSON.stringify(response));
  res.status(201).json(order);
}
