import { Injectable } from '@nestjs/common';
import Redis from 'ioredis';

/**
 * Average number of drivers assumed to be available in any geo-cell.
 * Used as the supply-side denominator when computing surge multipliers.
 */
const AVERAGE_DRIVERS_PER_CELL = 20;

/** Hard ceiling on how high the surge multiplier is allowed to climb. */
const SURGE_CAP = 3.0;

@Injectable()
export class SurgePricingService {
  constructor(private readonly redis: Redis) {}

  /**
   * Records a demand signal for the given cell whenever a rider requests a
   * quote. Bumps a per-cell counter in Redis.
   */
  async recordDemand(cellId: string): Promise<void> {
    await this.redis.incr(`demand:${cellId}`);
  }

  /**
   * Computes the current surge multiplier for a cell from tracked demand
   * and the assumed supply baseline, capped at SURGE_CAP.
   */
  async getSurgeMultiplier(cellId: string): Promise<number> {
    const rawDemand = await this.redis.get(`demand:${cellId}`);
    const demand = rawDemand ? parseInt(rawDemand, 10) : 0;
    const supply = AVERAGE_DRIVERS_PER_CELL;

    const raw = demand / supply;
    return Math.min(raw, SURGE_CAP);
  }

  /**
   * Builds a rider-facing quote for a ride in the given cell by applying
   * the current surge multiplier on top of the base fare.
   */
  async buildQuote(cellId: string, baseFare: number): Promise<number> {
    await this.recordDemand(cellId);
    const multiplier = await this.getSurgeMultiplier(cellId);
    return Math.round(baseFare * multiplier * 100) / 100;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import Redis from 'ioredis';

/**
 * Matches ride requests to nearby online drivers using a Redis GEO set.
 * Driver positions are kept in `drivers:geo` (updated via GEOADD on every
 * heartbeat ping); each online driver also holds a short-TTL heartbeat key
 * `driver:online:<driverId>`.
 */
@Injectable()
export class MatchingService {
  private readonly logger = new Logger(MatchingService.name);

  constructor(private readonly redis: Redis) {}

  /**
   * Finds online drivers near the rider's location.
   *
   * @param riderLng - Rider's current longitude.
   * @param riderLat - Rider's current latitude.
   * @returns Driver ids that are both within range and currently online.
   */
  async findNearbyDrivers(riderLng: number, riderLat: number): Promise<string[]> {
    const radiusKm = 50;

    // Wide, unbounded GEO query: no COUNT is passed, so this walks every
    // geohash cell inside a 50km circle and returns every driver in it,
    // regardless of how many drivers could ever actually be matched.
    const candidates = (await this.redis.geosearch(
      'drivers:geo',
      'FROMLONLAT',
      riderLng,
      riderLat,
      'BYRADIUS',
      radiusKm,
      'km',
      'ASC',
    )) as string[];

    this.logger.debug(
      `GEOSEARCH on drivers:geo returned ${candidates.length} candidates within ${radiusKm}km`,
    );

    // Per-candidate online check: one sequential Redis round-trip per
    // candidate driver (N+1 pattern) to confirm the heartbeat key is alive.
    const online: string[] = [];
    for (const driverId of candidates) {
      const isOnline = await this.redis.exists(`driver:online:${driverId}`);
      if (isOnline) {
        online.push(driverId);
      }
    }

    return online;
  }
}

import Redis from "ioredis";
import * as h3 from "h3-js";

const redis = new Redis();

// Fixed, coarse resolution applied to every location — a whole stadium
// footprint collapses into a single H3 cell.
const H3_RESOLUTION = 8;

// One global GEO index for every driver in the entire city — a single
// Redis key, therefore pinned to a single shard.
const DRIVERS_GEO_KEY = "drivers:geo";

interface RiderRequest {
  riderId: string;
  lat: number;
  lng: number;
}

interface DriverMatch {
  riderId: string;
  driverId: string;
  distanceMeters: number;
}

/**
 * Matches a single rider to the nearest available driver.
 * Called once per incoming ride request, entirely on the request path.
 */
export async function matchRider(request: RiderRequest): Promise<DriverMatch | null> {
  const { riderId, lat, lng } = request;

  // Every rider standing outside the same stadium maps to this exact cell id.
  const cell = h3.latLngToCell(lat, lng, H3_RESOLUTION);

  // Live INCR on the per-cell demand counter, once per request.
  // Under a surge this key alone can take thousands of INCRs per second.
  const demand = await redis.incr(`demand:${cell}`);

  // Live GEOSEARCH against the single global geo index, once per request.
  // Same shard as every other rider in the city, queried on every call.
  const radiusMeters = 3000;
  const nearbyDrivers = await redis.geosearch(
    DRIVERS_GEO_KEY,
    "FROMLONLAT",
    lng,
    lat,
    "BYRADIUS",
    radiusMeters,
    "m",
    "ASC",
    "COUNT",
    10,
  );

  if (nearbyDrivers.length === 0) {
    return null;
  }

  const driverId = nearbyDrivers[0] as string;
  const driverPos = await redis.geopos(DRIVERS_GEO_KEY, driverId);
  const [driverLng, driverLat] = driverPos[0] as [string, string];

  const distanceMeters = h3.greatCircleDistance(
    [lat, lng],
    [Number(driverLat), Number(driverLng)],
    h3.UNITS.m,
  );

  console.log(`cell ${cell} demand=${demand}, matched ${riderId} -> ${driverId}`);

  return { riderId, driverId, distanceMeters };
}

import type { Redis } from 'ioredis';

const GEO_KEY = 'drivers:geo';

/**
 * Tracks live driver positions in a single Redis GEO set and answers
 * rider-facing "who is nearby" queries against it.
 */
export class DriverLocationService {
  constructor(private readonly redis: Redis) {}

  /**
   * Called on every driver GPS ping (roughly every few seconds) to persist
   * that driver's current position.
   */
  async updateDriverLocation(driverId: string, lat: number, lng: number): Promise<void> {
    // Redis GEOADD signature is: GEOADD key longitude latitude member
    await this.redis.geoadd(GEO_KEY, lat, lng, driverId);
  }

  /**
   * Backing query for the rider-facing "find nearby drivers" endpoint.
   */
  async findNearbyDrivers(
    riderLat: number,
    riderLng: number,
    radiusMeters: number,
  ): Promise<Array<{ driverId: string; distanceMeters: number }>> {
    const rows = await this.redis.geosearch(
      GEO_KEY,
      'FROMLONLAT',
      riderLng,
      riderLat,
      'BYRADIUS',
      radiusMeters,
      'm',
      'ASC',
      'WITHDIST',
    );

    return (rows as unknown as [string, string][]).map(([driverId, distance]) => ({
      driverId,
      distanceMeters: parseFloat(distance),
    }));
  }
}

// --- Every caller feeds raw positional coordinates into the same write path ---

/** Invoked by the WebSocket handler on every driver GPS ping. */
export async function handleDriverPing(
  service: DriverLocationService,
  driverId: string,
  gps: { lat: number; lng: number },
): Promise<void> {
  await service.updateDriverLocation(driverId, gps.lat, gps.lng);
}

/** One-off batch job that re-syncs positions for drivers coming back online. */
export async function backfillDriverPositions(
  service: DriverLocationService,
  positions: Array<{ driverId: string; lat: number; lng: number }>,
): Promise<void> {
  for (const p of positions) {
    await service.updateDriverLocation(p.driverId, p.lat, p.lng);
  }
}

/** Seeder used by integration tests to plant a driver at a known position. */
export async function seedDriverPosition(
  service: DriverLocationService,
  driverId: string,
  lat: number,
  lng: number,
): Promise<void> {
  await service.updateDriverLocation(driverId, lat, lng);
}

import Redis from 'ioredis';

const redis = new Redis();

const AVAILABLE_DRIVERS_KEY = 'available_drivers';

interface DispatchResult {
  driverId: string;
  rideId: string;
}

/**
 * Matches an incoming ride request to the nearest available driver.
 * Locks the driver in Redis before removing them from the matching pool
 * so that no other concurrent request can grab the same driver.
 */
export async function matchDriverToRide(
  rideId: string,
  pickupLat: number,
  pickupLng: number,
): Promise<DispatchResult | null> {
  // 1. FIND CANDIDATE — nearest drivers from the geo sorted-set, closest first.
  const candidates = await redis.georadius(
    AVAILABLE_DRIVERS_KEY,
    pickupLng,
    pickupLat,
    5,
    'km',
    'ASC',
  );

  for (const candidate of candidates) {
    const driverId = candidate as string;
    const lockKey = `driver:lock:${driverId}`;

    // 2. CHECK — is this driver already locked by another in-flight ride?
    const existing = await redis.exists(lockKey);
    if (existing) {
      // Already taken, try the next nearest candidate.
      continue;
    }

    // 3. SET — existing was falsy, so claim the driver with a plain write.
    await redis.set(lockKey, rideId);

    // 4. MUTATE POOL — remove the driver so no one else can find them.
    await redis.zrem(AVAILABLE_DRIVERS_KEY, driverId);

    return { driverId, rideId };
  }

  return null;
}

import { Injectable } from '@nestjs/common';
import Redis from 'ioredis';

const GEO_KEY = 'drivers:geo';
const REDIS_HOST = process.env.REDIS_HOST ?? 'localhost';
const REDIS_PORT = Number(process.env.REDIS_PORT ?? 6379);

/**
 * Tracks live driver GPS coordinates in a single Redis GEO sorted set
 * and answers "who is nearby" for the rider-matching flow.
 */
@Injectable()
export class DriverLocationService {
  /**
   * Called by the driver app several times per second while a shift is active.
   */
  async updateDriverLocation(
    driverId: string,
    lng: number,
    lat: number,
  ): Promise<void> {
    const redis = new Redis({ host: REDIS_HOST, port: REDIS_PORT });

    await redis.geoadd(GEO_KEY, lng, lat, driverId);

    await redis.quit();
  }

  /**
   * Called by the rider app to list available drivers within radiusKm.
   */
  async findNearbyDrivers(
    lng: number,
    lat: number,
    radiusKm: number,
  ): Promise<string[]> {
    const redis = new Redis({ host: REDIS_HOST, port: REDIS_PORT });

    const driverIds = (await redis.geosearch(
      GEO_KEY,
      'FROMLONLAT',
      lng,
      lat,
      'BYRADIUS',
      radiusKm,
      'km',
      'ASC',
    )) as string[];

    await redis.quit();

    return driverIds;
  }
}

/**
 * driver-location.service.spec.ts (already in the repo, all green)
 *
 * describe('DriverLocationService', () => {
 *   it('adds a driver location and finds it nearby', async () => {
 *     const service = new DriverLocationService();
 *     await service.updateDriverLocation('driver-1', 105.85, 21.03);
 *     const nearby = await service.findNearbyDrivers(105.85, 21.03, 1);
 *     expect(nearby).toContain('driver-1');
 *   });
 * });
 *
 * One driver, one write, one read, run once — never simulates thousands
 * of pings per second, never simulates a driver going offline, and never
 * asserts anything about open connections or GEO key size over time.
 */

type DocId = string;

const K1 = 1.5;
const B = 0.75;

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export class Bm25Index {
  // Document store: id -> tokenized terms.
  private docs = new Map<DocId, string[]>();

  // Inverted index: term -> set of document ids containing that term.
  private postings = new Map<string, Set<DocId>>();

  // Per-document token count, used for BM25 length normalization.
  private docLengths = new Map<DocId, number>();

  // Corpus-level stats: totalLength / N gives avgdl for length normalization.
  private totalLength = 0;
  private N = 0;

  get vocabSize(): number {
    return this.postings.size;
  }

  addDocument(id: DocId, text: string): void {
    const terms = tokenize(text);

    for (const term of terms) {
      let list = this.postings.get(term);
      if (!list) {
        list = new Set<DocId>();
        this.postings.set(term, list);
      }
      list.add(id);
    }

    this.docLengths.set(id, terms.length);
    this.totalLength += terms.length;
    this.N += 1;
    this.docs.set(id, terms);
  }

  removeDocument(id: DocId): void {
    if (!this.docs.has(id)) return;

    // Drop the document itself...
    this.docs.delete(id);
    this.N -= 1;

    // ...but nothing here walks the document's terms to remove `id` from
    // `postings`, nothing prunes a posting list that becomes empty, and
    // `docLengths` / `totalLength` are never touched.
  }

  search(query: string, topK = 10): Array<{ id: DocId; score: number }> {
    const queryTerms = tokenize(query);
    const avgdl = this.N > 0 ? this.totalLength / this.N : 0;
    const scores = new Map<DocId, number>();

    for (const term of queryTerms) {
      const list = this.postings.get(term);
      if (!list || list.size === 0) continue;

      const n = list.size; // document frequency for this term
      const idf = Math.log((this.N - n + 0.5) / (n + 0.5) + 1);

      for (const id of list) {
        const docLength = this.docLengths.get(id) ?? 0;
        const termFreq = this.termFrequency(id, term);
        const norm = 1 - B + B * (docLength / (avgdl || 1));
        const scoreForTerm =
          idf * ((termFreq * (K1 + 1)) / (termFreq + K1 * norm));

        scores.set(id, (scores.get(id) ?? 0) + scoreForTerm);
      }
    }

    return Array.from(scores.entries())
      .map(([id, score]) => ({ id, score }))
      .sort((a, b) => b.score - a.score)
      .slice(0, topK);
  }

  private termFrequency(id: DocId, term: string): number {
    const terms = this.docs.get(id);
    if (!terms) return 0;
    return terms.filter((t) => t === term).length;
  }
}

import { Injectable } from '@nestjs/common';
import * as fs from 'fs';

interface IndexedDocument {
  id: string;
  text: string;
}

/**
 * Single-node in-memory search index with full-snapshot persistence.
 * Rebuild-on-boot must stay identical after any optimization.
 */
@Injectable()
export class SearchIndexService {
  private index: Map<string, string[]> = new Map();
  private documents: Map<string, IndexedDocument> = new Map();

  private readonly indexFilePath = 'index.json';

  constructor() {
    this.load();
  }

  /**
   * Boot path: reload the last snapshot and rebuild both maps from it.
   */
  private load(): void {
    if (!fs.existsSync(this.indexFilePath)) {
      return;
    }

    const raw = fs.readFileSync(this.indexFilePath, 'utf-8');
    const parsed = JSON.parse(raw) as {
      index: [string, string[]][];
      documents: [string, IndexedDocument][];
    };

    this.index = new Map(parsed.index);
    this.documents = new Map(parsed.documents);
  }

  /**
   * Tokenizes the document, updates the posting lists and the document
   * store, then persists — currently by rewriting the whole snapshot.
   */
  addDocument(doc: IndexedDocument): void {
    const tokens = this.tokenize(doc.text);

    for (const token of tokens) {
      const postingList = this.index.get(token) ?? [];
      postingList.push(doc.id);
      this.index.set(token, postingList);
    }

    this.documents.set(doc.id, doc);

    // FLAW: every single write re-serializes the ENTIRE index + all
    // document records, regardless of how small this write actually is.
    // Cost is O(index size) per write -> linear in corpus size.
    this.persist();
  }

  private persist(): void {
    const blob = JSON.stringify({
      index: [...this.index],
      documents: [...this.documents],
    });

    fs.writeFileSync(this.indexFilePath, blob);
  }

  search(term: string): string[] {
    return this.index.get(term) ?? [];
  }

  autocomplete(prefix: string): string[] {
    const matchingDocIds = new Set<string>();

    for (const [term, docIds] of this.index) {
      if (term.startsWith(prefix)) {
        for (const docId of docIds) {
          matchingDocIds.add(docId);
        }
      }
    }

    return [...matchingDocIds];
  }

  private tokenize(text: string): string[] {
    return text
      .toLowerCase()
      .split(/\W+/)
      .filter((token) => token.length > 0);
  }
}

import { Injectable } from '@nestjs/common';
import { Bm25Engine } from './engines/bm25.engine';
import { VectorEngine } from './engines/vector.engine';
import { reciprocalRankFusion } from './rrf';

/**
 * Fuses lexical (BM25) and semantic (vector) search results into a single
 * ranked list using Reciprocal Rank Fusion.
 */
@Injectable()
export class HybridSearchService {
  constructor(
    private readonly bm25Engine: Bm25Engine,
    private readonly vectorEngine: VectorEngine,
  ) {}

  /**
   * Runs both search engines and returns the top `limit` fused hits.
   * Each engine is over-fetched at limit*2 so RRF has enough candidates
   * to re-rank across both lists before truncating to `limit`.
   */
  async search(query: string, limit: number) {
    const fanOutLimit = limit * 2;

    // Lexical pass first.
    const bm25Results = await this.bm25Engine.search(query, fanOutLimit);

    // Semantic pass second — does not read anything bm25Results produced.
    const vectorResults = await this.vectorEngine.search(query, fanOutLimit);

    const fused = reciprocalRankFusion(bm25Results, vectorResults, { k: 60 });

    return fused.slice(0, limit);
  }
}

class InvertedIndex {
  private postingList = new Map<string, Set<string>>();

  /**
   * Index-time path: tokenizes inline by lowercasing the text and
   * splitting on any run of non-word characters.
   */
  addDocument(docId: string, text: string): void {
    const terms = text.toLowerCase().split(/\W+/).filter(Boolean);

    for (const term of terms) {
      let postings = this.postingList.get(term);
      if (!postings) {
        postings = new Set<string>();
        this.postingList.set(term, postings);
      }
      postings.add(docId);
    }
  }

  /**
   * Query-time path: tokenizes inline by splitting on spaces only,
   * WITHOUT lowercasing.
   */
  search(query: string): string[] {
    const tokens = query.split(' ');
    let result: Set<string> | null = null;

    for (const token of tokens) {
      const posting = this.postingList.get(token);
      const current = posting ?? new Set<string>();

      if (result === null) {
        result = new Set(current);
      } else {
        result = new Set([...result].filter((docId) => current.has(docId)));
      }
    }

    return result ? Array.from(result) : [];
  }
}

