import Redis from "ioredis";

const RATE_LIMIT_SCRIPT = `
local key = KEYS[1]
local limit = tonumber(ARGV[1])
local windowMs = tonumber(ARGV[2])
local now = tonumber(ARGV[3])

local current = redis.call("GET", key)
if current and tonumber(current) >= limit then
  return {0, 0}
end

local count = redis.call("INCR", key)
if count == 1 then
  redis.call("PEXPIRE", key, windowMs)
end

local remaining = limit - count
if remaining < 0 then
  remaining = 0
end

return {1, remaining}
`;

export class RedisRateLimiter {
  private readonly redis: Redis;

  constructor(redis: Redis) {
    this.redis = redis;
  }

  /**
   * Runs the atomic check-and-increment on every request.
   * NOTE: ships the full Lua source in RATE_LIMIT_SCRIPT on every call.
   */
  async isAllowed(
    key: string,
    limit: number,
    windowMs: number,
  ): Promise<{ allowed: boolean; remaining: number }> {
    const now = Date.now();

    const result = (await this.redis.eval(
      RATE_LIMIT_SCRIPT,
      1,
      key,
      limit,
      windowMs,
      now,
    )) as [number, number];

    const [allowedFlag, remaining] = result;
    return { allowed: allowedFlag === 1, remaining };
  }
}

import { randomUUID } from "crypto";
import type Redis from "ioredis";

/**
 * Sliding-window-log rate limiter.
 *
 * For each client, `ratelimit:{clientId}` is a Redis SORTED SET (ZSET):
 * one member per in-window request, scored by the request's millisecond
 * timestamp. This makes the limiter exact, but memory and per-check CPU
 * both scale with the number of requests currently inside the window --
 * the hottest clients pay (and cost) the most.
 */
export class SlidingWindowLogLimiter {
  constructor(private readonly redis: Redis) {}

  /**
   * Returns true if `clientId` may make another request right now,
   * given `limit` requests per `windowMs` milliseconds.
   */
  async isAllowed(
    clientId: string,
    limit: number,
    windowMs: number,
  ): Promise<boolean> {
    const key = `ratelimit:${clientId}`;
    const now = Date.now();
    const windowStart = now - windowMs;

    // 1. Evict everything that fell out of the window.
    //    O(log N + M) where N = set size, M = evicted count.
    await this.redis.zremrangebyscore(key, 0, windowStart);

    // 2. Count what's left in the window. O(log N).
    const count = await this.redis.zcard(key);

    if (count >= limit) {
      return false;
    }

    // 3. Record this request as its own sorted-set entry.
    //    One ZADD member per request => O(N) memory per client.
    const requestId = randomUUID();
    await this.redis.zadd(key, now, requestId);
    await this.redis.pexpire(key, windowMs);

    return true;
  }
}

import Redis from "ioredis";

const redis = new Redis();

const limit = 100; // max requests allowed per window
const windowMs = 60_000; // 60 second sliding window

/**
 * Sliding-window-log rate limiter backed by a Redis ZSET.
 * One ZSET per user; each granted request is an entry scored by timestamp.
 */
export async function allowRequest(userId: string): Promise<boolean> {
  const key = `ratelimit:${userId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  const pipeline = redis.multi();

  // Evict entries whose score (timestamp) fell out of the window.
  pipeline.zremrangebyscore(key, 0, windowStart);

  // Record this request. Score = now keeps ordering/eviction correct.
  pipeline.zadd(key, now, now);

  // Count how many entries are currently inside the window.
  pipeline.zcard(key);

  // Let idle keys self-clean once the window has fully elapsed.
  pipeline.expire(key, Math.ceil(windowMs / 1000));

  const results = await pipeline.exec();
  if (!results) {
    throw new Error(`Rate limiter pipeline returned no results for user ${userId}`);
  }

  const [, , zcardResult] = results;
  const [zcardErr, count] = zcardResult;
  if (zcardErr) {
    throw zcardErr;
  }

  return (count as number) <= limit;
}

import Redis, { Cluster } from 'ioredis';

/**
 * Atomically checks and increments three nested rate-limit counters
 * (per-user, per-tenant, and a global safety cap) in a single Lua
 * script so the check-and-increment cannot race across counters.
 */
export class RateLimiter {
  private readonly redis: Cluster | Redis;

  // KEYS[1]=userKey, KEYS[2]=tenantKey, KEYS[3]=globalKey
  // ARGV[1]=userLimit, ARGV[2]=tenantLimit, ARGV[3]=globalLimit, ARGV[4]=windowSeconds
  private readonly checkAndIncrScript = `
    local userCount = tonumber(redis.call('GET', KEYS[1])) or 0
    local tenantCount = tonumber(redis.call('GET', KEYS[2])) or 0
    local globalCount = tonumber(redis.call('GET', KEYS[3])) or 0

    local userLimit = tonumber(ARGV[1])
    local tenantLimit = tonumber(ARGV[2])
    local globalLimit = tonumber(ARGV[3])
    local window = tonumber(ARGV[4])

    if userCount + 1 > userLimit or tenantCount + 1 > tenantLimit or globalCount + 1 > globalLimit then
      return 0 -- denied, nothing incremented
    end

    redis.call('INCR', KEYS[1])
    redis.call('EXPIRE', KEYS[1], window)
    redis.call('INCR', KEYS[2])
    redis.call('EXPIRE', KEYS[2], window)
    redis.call('INCR', KEYS[3])
    redis.call('EXPIRE', KEYS[3], window)

    return 1 -- allowed
  `;

  constructor(redis: Cluster | Redis) {
    this.redis = redis;
  }

  // BUG: three independently-named keys with nothing forcing them onto
  // the same hash slot. On a standalone node this is harmless; on
  // Redis Cluster each is routed by CRC16(key) mod 16384 independently.
  private buildKeys(userId: string, tenantId: string) {
    const userKey = `quota:u:${userId}`;
    const tenantKey = `quota:t:${tenantId}`;
    const globalKey = `quota:g`;
    return { userKey, tenantKey, globalKey };
  }

  async consume(
    userId: string,
    tenantId: string,
    userLimit: number,
    tenantLimit: number,
    globalLimit: number,
    windowSeconds = 60,
  ): Promise<boolean> {
    const { userKey, tenantKey, globalKey } = this.buildKeys(userId, tenantId);

    const result = await this.redis.eval(
      this.checkAndIncrScript,
      3,
      userKey,
      tenantKey,
      globalKey,
      userLimit,
      tenantLimit,
      globalLimit,
      windowSeconds,
    );

    return result === 1;
  }
}

