//
// ReplyError: CROSSSLOT Keys in request don't hash to the same slot
//     at RateLimiter.consume (rate-limiter.ts:63)
//     at async requestHandler (gateway.ts:41)
//
// Staging (standalone Redis): every request passes.
// Production (Redis Cluster, 16384 hash slots): every request throws
// CROSSSLOT and no request is ever admitted.

import { Redis } from "ioredis";

const redis = new Redis();

/**
 * Sliding-window-log rate limiter backed by a Redis ZSET.
 * Each request is stored as a member scored by its timestamp; membership
 * still inside the current window determines whether the client is under
 * the configured limit.
 */
export async function allowRequest(
  clientId: string,
  limit: number,
  windowMs: number,
): Promise<boolean> {
  const key = `rl:${clientId}`;
  const now = Date.now();
  const windowStart = now - windowMs;

  // Drop members that have aged out of the current window.
  await redis.zremrangebyscore(key, 0, windowStart);

  // How many requests currently sit inside the window.
  const count = await redis.zcard(key);

  // Record this attempt in the log.
  const member = `${now}-${Math.random().toString(36).slice(2)}`;
  await redis.zadd(key, now, member);

  // Decide the verdict only after the attempt has already been recorded.
  return count < limit;
}

