        listen 443 ssl;
        server_name app.example.com;

        ssl_certificate     /etc/nginx/ssl/app.example.com.crt;
        ssl_certificate_key /etc/nginx/ssl/app.example.com.key;

        # Single catch-all location fronts BOTH public static assets
        # (e.g. /assets/*.js, /images/*.png) and personalized,
        # authenticated pages (e.g. /dashboard, /account) through the
        # same shared cache zone.
        location / {
            proxy_pass http://origin_app;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header Cookie $http_cookie;
            proxy_set_header Authorization $http_authorization;

            proxy_cache edge_cache;

            # Cache key built ONLY from the request URI -- no auth
            # state, cookie, or session token is folded in, so an
            # anonymous request and a logged-in request to the same
            # path collide on one cache entry.
            proxy_cache_key $request_uri;

            # No proxy_no_cache / proxy_cache_bypass on Set-Cookie or
            # Authorization here -- authenticated responses (including
            # ones carrying Set-Cookie) get stored and later replayed
            # to any other caller who hits the same URI.

            # One blanket validity line for "any" status class pins
            # 4xx/5xx (including a transient origin 500) for a full
            # hour, well past when the origin actually recovers.
            proxy_cache_valid any 1h;

            proxy_cache_use_stale error timeout updating;

            add_header X-Cache-Status $upstream_cache_status;

            # No proxy_cache_lock directive -- defaults to off, so
            # concurrent misses on the same hot key all stampede
            # every upstream origin server at once.
        }
    }
}

import { Controller, Patch, Param, Body, Headers, ConflictException, Injectable } from '@nestjs/common';
import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { ObjectStorageClient } from '../storage/object-storage.client';

/**
 * Row shape of the `upload_sessions` table:
 *   session_id        varchar   primary key
 *   committed_offset  bigint    -- durable bytes committed so far
 *   total_size        bigint
 */
interface UploadSessionRow {
  session_id: string;
  committed_offset: string; // bigint comes back as string from pg driver
  total_size: string;
}

@Injectable()
export class UploadService {
  constructor(
    @InjectDataSource() private readonly dataSource: DataSource,
    private readonly objectStorage: ObjectStorageClient,
  ) {}

  /**
   * Handles a single resumable-upload chunk (tus-style PATCH).
   * Runs on every chunk of every in-flight upload, so this is the hottest
   * path in the whole file-storage service.
   */
  async handleChunk(sessionId: string, uploadOffset: number, chunkBuffer: Buffer): Promise<{ offset: number }> {
    // 1) Synchronous round-trip #1: read the durably committed offset just
    //    to validate that this chunk is the next one in order.
    const [session] = await this.dataSource.query<UploadSessionRow[]>(
      'SELECT session_id, committed_offset, total_size FROM upload_sessions WHERE session_id = $1',
      [sessionId],
    );

    const committedOffset = Number(session.committed_offset);

    // 2) Reject out-of-order / duplicate chunks.
    if (uploadOffset !== committedOffset) {
      throw new ConflictException(
        `Upload-Offset mismatch: expected ${committedOffset}, got ${uploadOffset}`,
      );
    }

    // 3) Persist the chunk bytes to object storage.
    await this.objectStorage.writeChunk(sessionId, uploadOffset, chunkBuffer);

    const newOffset = committedOffset + chunkBuffer.length;

    // 4) Synchronous round-trip #2: durably persist the advanced offset,
    //    inline in request latency, on every single chunk.
    await this.dataSource.query(
      'UPDATE upload_sessions SET committed_offset = committed_offset + $1 WHERE session_id = $2',
      [chunkBuffer.length, sessionId],
    );

    return { offset: newOffset };
  }
}

@Controller('uploads')
export class UploadController {
  constructor(private readonly uploadService: UploadService) {}

  @Patch(':sessionId')
  async patchChunk(
    @Param('sessionId') sessionId: string,
    @Headers('upload-offset') uploadOffsetHeader: string,
    @Body() chunkBuffer: Buffer,
  ): Promise<{ offset: number }> {
    const uploadOffset = Number(uploadOffsetHeader);
    return this.uploadService.handleChunk(sessionId, uploadOffset, chunkBuffer);
  }
}

interface CacheEntry {
  body: string;
  expiresAt: number;
}

interface OriginStore {
  fetch(key: string): Promise<string>;
}

declare const origin: OriginStore;

const ttl = 30_000; // fixed TTL in ms
const cache = new Map<string, CacheEntry>();

async function getFromEdge(key: string): Promise<string> {
  const entry = cache.get(key);

  // Fresh HIT: return immediately.
  if (entry && entry.expiresAt > Date.now()) {
    return entry.body;
  }

  // MISS: every concurrent caller reaches this line independently
  // and calls the origin on its own — no coalescing, no serve-stale.
  const body = await origin.fetch(key);

  cache.set(key, { body, expiresAt: Date.now() + ttl });

  return body;
}

