package chunker

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
)

// chunkSize is the fixed window length every chunk is read into.
const chunkSize = 4 * 1024 * 1024 // 4 MiB

// Chunk is one content-addressed piece of a source payload.
type Chunk struct {
	Index int    // position of this chunk within the file
	Hash  string // hex-encoded SHA-256 digest of the chunk's bytes
	Size  int    // number of bytes this chunk represents
}

// Store is a content-addressed blob store keyed by hex-encoded digest.
type Store struct {
	blobs map[string][]byte
}

func NewStore() *Store {
	return &Store{blobs: make(map[string][]byte)}
}

// Put writes data under hash if it isn't already present, and reports
// whether this was a new blob (dedup miss) or an existing one (dedup hit).
func (s *Store) Put(hash string, data []byte) (isNew bool) {
	if _, ok := s.blobs[hash]; ok {
		return false
	}
	s.blobs[hash] = append([]byte(nil), data...)
	return true
}

// Split reads r in fixed-size windows, content-addresses each window by its
// SHA-256 hash, stores it, and returns the recorded chunk metadata in order.
func Split(r io.Reader, store *Store) ([]Chunk, error) {
	// A single reusable buffer for the fixed-size read window.
	buf := make([]byte, chunkSize)

	var chunks []Chunk
	index := 0

	for {
		n, err := r.Read(buf)
		if n > 0 {
			// Hash the chunk and record it in the store.
			sum := sha256.Sum256(buf)
			hash := hex.EncodeToString(sum[:])

			store.Put(hash, buf)

			chunks = append(chunks, Chunk{
				Index: index,
				Hash:  hash,
				Size:  chunkSize,
			})
			index++
		}

		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
	}

	return chunks, nil
}

import { Injectable } from '@nestjs/common';
import { Pool } from 'pg';

/**
 * Persists the link-graph edges produced by the crawler's parsing stage.
 * `link_graph` rows are edges: from_url -> to_url (an outlink discovered on fromUrl's page).
 * PageRank later scans this table and uses each URL's inbound edge count as its in-degree signal.
 */
@Injectable()
export class LinkGraphRepository {
  constructor(private readonly pool: Pool) {}

  /**
   * Called by the crawler every time it (re-)parses a page: saveOutlinks(pageUrl, extractedLinks).
   * A page gets re-parsed on every re-crawl, and its extracted outlinks may shrink, grow,
   * or change entirely between parses.
   */
  async saveOutlinks(fromUrl: string, outlinks: string[]): Promise<void> {
    for (const toUrl of outlinks) {
      await this.pool.query(
        `INSERT INTO link_graph (from_url, to_url)
         VALUES ($1, $2)
         ON CONFLICT (from_url, to_url) DO NOTHING`,
        [fromUrl, toUrl],
      );
    }
  }
}

package frontier

import (
	"context"

	"github.com/redis/go-redis/v9"
)

// Frontier manages the shared "URL frontier" for a distributed web crawler.
// Newly discovered URLs are deduped against a RedisBloom filter before being
// pushed onto the pending-URL queue that downstream workers pull from.
type Frontier struct {
	client           *redis.Client
	seenFilterKey    string // RedisBloom filter of already-seen URLs
	frontierQueueKey string // list of URLs pending crawl
}

func NewFrontier(client *redis.Client, seenFilterKey, frontierQueueKey string) *Frontier {
	return &Frontier{
		client:           client,
		seenFilterKey:    seenFilterKey,
		frontierQueueKey: frontierQueueKey,
	}
}

// EnqueueURL dedups a newly discovered URL against the bloom filter and,
// if it hasn't been seen before, pushes it onto the frontier queue.
func (f *Frontier) EnqueueURL(ctx context.Context, url string) error {
	// Round-trip #1: membership check against the bloom filter.
	exists, err := f.client.Do(ctx, "BF.EXISTS", f.seenFilterKey, url).Bool()
	if err != nil {
		return err
	}
	if exists {
		// Already seen by some other worker -> nothing to do.
		return nil
	}

	// Round-trip #2: mark the URL as seen in the bloom filter.
	if err := f.client.Do(ctx, "BF.ADD", f.seenFilterKey, url).Err(); err != nil {
		return err
	}

	// Round-trip #3: push the URL onto the frontier queue for workers to pick up.
	return f.client.RPush(ctx, f.frontierQueueKey, url).Err()
}

interface RobotsCacheEntry {
  value: string;
  expiresAt: number;
}

/**
 * In-memory TTL cache mapping host -> raw robots.txt body.
 * A stored value of "" is a legitimate cached result (empty robots.txt = allow all),
 * distinct from "no entry at all" (a genuine cache miss).
 */
class TtlCache<T> {
  private readonly store = new Map<string, RobotsCacheEntry>();

  async get(host: string): Promise<T | null> {
    const entry = this.store.get(host);
    if (!entry) {
      return null;
    }
    if (Date.now() > entry.expiresAt) {
      this.store.delete(host);
      return null;
    }
    return entry.value as unknown as T;
  }

  async set(host: string, value: T, ttlSeconds: number): Promise<void> {
    this.store.set(host, {
      value: value as unknown as string,
      expiresAt: Date.now() + ttlSeconds * 1000,
    });
  }
}

export const robotsCache = new TtlCache<string>();
export const TTL_SECONDS = 3600;

interface RobotsRules {
  disallow: string[];
  allow: string[];
}

export function parseRobots(body: string): RobotsRules {
  const disallow: string[] = [];
  const allow: string[] = [];

  for (const rawLine of body.split("\n")) {
    const line = rawLine.trim();
    if (line.toLowerCase().startsWith("disallow:")) {
      disallow.push(line.slice("disallow:".length).trim());
    } else if (line.toLowerCase().startsWith("allow:")) {
      allow.push(line.slice("allow:".length).trim());
    }
  }

  return { disallow, allow };
}

async function fetchRobotsBody(host: string): Promise<string> {
  const res = await fetch(`http://${host}/robots.txt`);
  // res.text can legitimately be "" for hosts that ship an empty robots.txt.
  return res.text();
}

/**
 * Used by every crawl worker before touching a URL on `host`.
 * Should hit the TTL cache on every call within the TTL window,
 * only re-fetching robots.txt once the cached entry expires.
 */
export async function getRobotsRules(host: string): Promise<RobotsRules> {
  const cached = await robotsCache.get(host);

  if (cached) {
    // Cache hit: parse the cached body without re-fetching.
    return parseRobots(cached);
  }

  // Cache miss: fetch fresh, cache it, then parse.
  const body = await fetchRobotsBody(host);
  await robotsCache.set(host, body, TTL_SECONDS);
  return parseRobots(body);
}

import Redis from "ioredis";

// Bloom filter key for the crawler's global "seen URLs" set.
const SEEN_URLS_KEY = "crawler:seen:urls";

// Sizing knobs for the filter. NOTE: kept for reference below.
const ERROR_RATE = 0.01;
const EXPECTED_UNIQUE_URLS = 5_000_000;

/**
 * Deduplicates crawl-frontier URLs using a RedisBloom filter so the
 * crawler never re-fetches a page it has already queued or visited.
 */
export class UrlDedupService {
  private readonly frontier: string[] = [];

  constructor(private readonly redis: Redis) {}

  /**
   * Tests-and-inserts `url` into the bloom filter in one round trip.
   * If the filter reports the url as new, it is pushed onto the crawl
   * frontier; if the filter reports it as already present, it is
   * treated as a duplicate and silently dropped.
   */
  async enqueue(url: string): Promise<boolean> {
    // BF.ADD both inserts the item and returns whether it was new.
    const reply = (await this.redis.call(
      "BF.ADD",
      SEEN_URLS_KEY,
      url,
    )) as number;

    if (reply === 1) {
      // Newly added -> genuinely new URL, safe to crawl.
      this.frontier.push(url);
      return true;
    }

    // reply === 0 -> filter says it has seen this url before.
    return false;
  }

  getFrontierSize(): number {
    return this.frontier.length;
  }
}

def pagerank(graph, damping=0.85, num_iterations=100):
    """
    Compute PageRank scores via power iteration.

    graph: dict mapping each page node -> list of its outlink target nodes.
    damping: probability a "random surfer" follows an outlink (vs. teleporting).
    num_iterations: number of power-iteration rounds to run.
    """
    N = len(graph)
    ranks = {node: 1 / N for node in graph}

    for _ in range(num_iterations):
        # Seed this round with only the teleport/base term.
        new_ranks = {node: (1 - damping) / N for node in graph}

        # Distribute each node's current rank across its outlinks.
        for u in graph:
            out = graph[u]
            if len(out) == 0:
                # Dangling node (no outlinks) — nothing to distribute.
                continue
            share = damping * ranks[u] / len(out)
            for v in out:
                new_ranks[v] += share

        ranks = new_ranks

    return ranks

package billing

import (
	"log"
	"time"
)

// Deliberate tuning smell: renewInterval is set equal to leaseTTL instead of
// a fraction of it, leaving almost no margin before the lease can expire
// out from under a live leader.
const (
	leaseTTL      = 15 * time.Second
	renewInterval = 15 * time.Second
)

// LockStore models a Redis/etcd-style distributed lock with lease semantics.
// TryAcquire returns both whether leadership was won and a monotonically
// increasing fencing term for the winning attempt.
type LockStore interface {
	TryAcquire(lockKey string, ttl time.Duration) (acquired bool, term int64, err error)
	Renew(lockKey string, ttl time.Duration) error
}

// PendingOrder is a single billing-sweep line item awaiting a charge.
type PendingOrder struct {
	OrderID string
	Amount  float64
}

// NightlyBillingSweeper elects a single leader to run the nightly billing job.
type NightlyBillingSweeper struct {
	store    LockStore
	lockKey  string
	isLeader bool
	term     int64 // captured at acquire time, then never referenced again
}

func NewNightlyBillingSweeper(store LockStore) *NightlyBillingSweeper {
	return &NightlyBillingSweeper{store: store, lockKey: "billing-sweep-leader"}
}

// Start acquires leadership, spins the renew loop, then runs the sweep.
func (s *NightlyBillingSweeper) Start(orders []PendingOrder) {
	acquired, term, err := s.store.TryAcquire(s.lockKey, leaseTTL)
	if err != nil {
		log.Printf("acquire failed: %v", err)
		return
	}
	if !acquired {
		log.Println("another node is leader, exiting")
		return
	}

	// term is stored on the struct but is dropped here — it never travels
	// downstream with the side effect it is supposed to fence.
	s.isLeader = true
	s.term = term

	go s.renewLoop()

	s.runSweep(orders)
}

// renewLoop keeps the lease alive on a fixed tick. On a renew failure it
// only logs — there is no fast re-check of leadership on the hot path, and
// no signal is sent to stop an in-flight sweep.
func (s *NightlyBillingSweeper) renewLoop() {
	ticker := time.NewTicker(renewInterval)
	defer ticker.Stop()

	for range ticker.C {
		if err := s.store.Renew(s.lockKey, leaseTTL); err != nil {
			log.Printf("renew failed, lease may be lost: %v", err)
		}
	}
}

// runSweep walks pending orders and charges each one while this node
// believes it is leader. isLeader is a plain local bool set once at
// acquire time — it is never re-read from the lock store at the moment
// of the charge, so a goroutine that stalls (e.g. a long GC pause) past
// leaseTTL will resume and keep charging as if nothing happened.
func (s *NightlyBillingSweeper) runSweep(orders []PendingOrder) {
	for _, order := range orders {
		if s.isLeader {
			if err := chargeCustomer(order.OrderID, order.Amount); err != nil {
				log.Printf("charge failed for order %s: %v", order.OrderID, err)
			}
		}
	}
}

// chargeCustomer is the non-idempotent downstream side effect. Its signature
// takes only an order id and amount — there is no fencing term parameter and
// no idempotency key, so the billing tier cannot tell a legitimate charge
// apart from a stale replay fired by an expired leader.
func chargeCustomer(orderID string, amount float64) error {
	return paymentGatewayClient.Charge(orderID, amount)
}

var paymentGatewayClient interface {
	Charge(orderID string, amount float64) error
}

package coordination

import (
	"errors"
	"sync"

	"github.com/hashicorp/raft"
)

// Server is a single Raft node providing distributed locks and leader
// election for the rest of the platform.
type Server struct {
	raft  *raft.Raft
	store *KVStore // local state-machine replica kept in sync via raft.Apply
}

// KVStore is the local, replicated key-value copy that backs the state
// machine. Reading it never touches the network.
type KVStore struct {
	mu   sync.RWMutex
	data map[string]string
}

func (s *KVStore) get(key string) (string, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// readIndex confirms this node is still the Raft leader before a read is
// allowed to proceed: it sends a heartbeat to a majority of followers and
// blocks until a majority has responded, WITHOUT appending anything to the
// log. This is the classic ReadIndex technique — pay one round-trip to
// prove leadership, then it is safe to read the local state machine.
func (s *Server) readIndex() error {
	future := s.raft.VerifyLeader()
	if err := future.Error(); err != nil {
		return err // lost leadership mid-flight; caller must retry/redirect
	}
	return nil
}

// Read serves every read through the strongly-consistent path: it always
// pays the majority round-trip before touching the local store, whether
// the caller is deciding something or just displaying a number.
func (s *Server) Read(key string) (string, error) {
	if err := s.readIndex(); err != nil {
		return "", err
	}
	v, ok := s.store.get(key)
	if !ok {
		return "", errors.New("key not found")
	}
	return v, nil
}

// AcquireLock decides whether the caller now holds a distributed lock. A
// stale answer here is a correctness bug: two callers could both believe
// they hold the lock.
func (s *Server) AcquireLock(lockKey, holder string) (bool, error) {
	owner, err := s.Read(lockKey)
	if err != nil {
		return false, err
	}
	return owner == holder, nil
}

// IsLeader answers a leadership-claim check used to decide whether this
// node may act as coordinator for a given partition.
func (s *Server) IsLeader(partitionKey string) (bool, error) {
	leaderID, err := s.Read(partitionKey + "/leader")
	if err != nil {
		return false, err
	}
	return leaderID == s.raft.String(), nil
}

// GetMetrics powers dashboard and stats endpoints: aggregate counters that
// are read far more often than locks are acquired, and where staleness of
// a few tens of milliseconds is completely harmless.
func (s *Server) GetMetrics(metricKey string) (string, error) {
	return s.Read(metricKey)
}

