import { randomUUID } from "crypto";
import type { Redis } from "ioredis";

/**
 * Runs a leader-only background job across several identical replicas,
 * using a Redis TTL lease for leader election.
 */
export class LeaderElector {
  private readonly redis: Redis;
  private readonly key: string;
  private readonly myId: string;
  private readonly leaseTtlMs: number;
  private readonly renewIntervalMs: number;

  private isLeader = false;
  private timer: NodeJS.Timeout | null = null;

  constructor(
    redis: Redis,
    key: string = "leader:job",
    leaseTtlMs: number = 10_000,
    renewIntervalMs: number = 3_000,
  ) {
    this.redis = redis;
    this.key = key;
    // Unique per-process id: survives restarts differently than the old leader's id.
    this.myId = `${process.pid}-${randomUUID()}`;
    this.leaseTtlMs = leaseTtlMs;
    this.renewIntervalMs = renewIntervalMs;
  }

  start(): void {
    this.timer = setInterval(() => {
      void this.tick();
    }, this.renewIntervalMs);
  }

  stop(): void {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  private async tick(): Promise<void> {
    if (!this.isLeader) {
      // Follower path: only writes if the key is absent, so ownership is
      // never stolen from a live leader.
      const reply = await this.redis.set(
        this.key,
        this.myId,
        "PX",
        this.leaseTtlMs,
        "NX",
      );
      if (reply === "OK") {
        this.isLeader = true;
      }
      return;
    }

    // Leader path: renew the lease so we don't lose it while doing work.
    await this.redis.pexpire(this.key, this.leaseTtlMs);

    if (this.isLeader) {
      await this.runLeaderWork();
    }
  }

  private async runLeaderWork(): Promise<void> {
    // The actual leader-only reconciliation logic (e.g. reconcile job state).
    // Omitted: assume it's idempotent-looking but not safe to run twice.
  }
}

import { randomUUID } from "crypto";
import type { Redis } from "ioredis";

/**
 * Result returned by acquire(): either a granted lock with its
 * ownership token and remaining validity window, or a refusal.
 */
interface LockResult {
  acquired: boolean;
  value?: string;
  validityMs?: number;
}

/**
 * Redlock-style distributed lock manager. Requires a quorum of the
 * configured Redis nodes to accept the same fencing value before the
 * caller is allowed to treat the resource as locked.
 */
export class RedlockManager {
  constructor(private readonly nodes: Redis[]) {}

  /**
   * Attempts to acquire `resource` for `ttl` milliseconds across all
   * configured nodes, granting the lock once a quorum reports success.
   */
  async acquire(resource: string, ttl: number): Promise<LockResult> {
    const value = randomUUID();
    const quorum = Math.floor(this.nodes.length / 2) + 1;

    const start = Date.now();

    // Fire the SET NX PX against every node at once. No per-node
    // timeout wraps these calls, so a single slow/paused node blocks
    // this Promise.all for as long as it takes to respond.
    const results = await Promise.all(
      this.nodes.map((node) => node.set(resource, value, "NX", "PX", ttl)),
    );

    const acquiredOn = results.filter((ok) => ok === "OK").length;

    const elapsed = Date.now() - start;
    // Allowance for clock drift between nodes, per the Redlock paper.
    // NOTE: currently computed but never subtracted below.
    const drift = ttl * 0.01;

    if (acquiredOn >= quorum) {
      // BUG: reports the full original ttl as the usable window,
      // ignoring both `elapsed` (time the acquisition itself burned)
      // and `drift` (clock skew across nodes). If one node was slow,
      // the caller is handed a "fresh" ttl that is already mostly gone.
      return { acquired: true, value, validityMs: ttl };
    }

    await this.releaseAll(resource, value);
    return { acquired: false };
  }

  /**
   * Releases `resource` on every node, but only where the fencing
   * value still matches this caller's token.
   */
  private async releaseAll(resource: string, value: string): Promise<void> {
    const releaseScript = `
      if redis.call("get", KEYS[1]) == ARGV[1] then
        return redis.call("del", KEYS[1])
      else
        return 0
      end
    `;
    await Promise.all(
      this.nodes.map((node) => node.eval(releaseScript, 1, resource, value)),
    );
  }
}

