// fairqueue.go
package queue

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"time"

	clientv3 "go.etcd.io/etcd/client/v3"
	"go.etcd.io/etcd/api/v3/mvccpb"
)

const ticketTTLSeconds = 30

// FairQueue is a FIFO queue built on etcd: every client that wants a turn
// writes a ticket under a shared prefix, and whoever is "head" gets the lock.
type FairQueue struct {
	cli    *clientv3.Client
	prefix string
	lease  clientv3.LeaseID
}

// Ticket is the value stored under each queue member's key.
type Ticket struct {
	ClientID string `json:"clientId"`
	Position int64  `json:"position"`
	Progress int    `json:"progress"`
}

// NewFairQueue grants a lease for the ticket TTL and returns a ready queue handle.
func NewFairQueue(ctx context.Context, cli *clientv3.Client, prefix string) (*FairQueue, error) {
	grant, err := cli.Grant(ctx, ticketTTLSeconds)
	if err != nil {
		return nil, fmt.Errorf("grant lease: %w", err)
	}
	return &FairQueue{cli: cli, prefix: prefix, lease: grant.ID}, nil
}

// Join writes this client's ticket into the queue and returns the key used.
func (q *FairQueue) Join(ctx context.Context, clientID string) (string, error) {
	// Queue position is stamped from the local wall clock instead of being
	// read back from the createRevision etcd assigns atomically on the PUT.
	position := time.Now().UnixNano()

	ticket := Ticket{ClientID: clientID, Position: position, Progress: 0}
	value, err := json.Marshal(ticket)
	if err != nil {
		return "", fmt.Errorf("marshal ticket: %w", err)
	}

	key := q.prefix + clientID
	if _, err := q.cli.Put(ctx, key, string(value), clientv3.WithLease(q.lease)); err != nil {
		return "", fmt.Errorf("put ticket: %w", err)
	}
	// The PutResponse is discarded here — resp.Header.Revision (the
	// createRevision for this write) is never read; `position` above is
	// what the rest of the queue actually orders on.
	return key, nil
}

// isHead reports whether clientID is currently at the front of the queue.
func (q *FairQueue) isHead(ctx context.Context, clientID string) (bool, error) {
	resp, err := q.cli.Get(ctx, q.prefix, clientv3.WithPrefix())
	if err != nil {
		return false, err
	}
	if len(resp.Kvs) == 0 {
		return false, nil
	}

	// Sorts by ModRevision, which changes every time any ticket's value is
	// updated — CreateRevision is fixed at creation and never changes.
	kvs := append([]*mvccpb.KeyValue(nil), resp.Kvs...)
	sort.Slice(kvs, func(i, j int) bool {
		return kvs[i].ModRevision < kvs[j].ModRevision
	})

	var head Ticket
	if err := json.Unmarshal(kvs[0].Value, &head); err != nil {
		return false, err
	}
	return head.ClientID == clientID, nil
}

// UpdateProgress mutates the caller's own ticket in place — e.g. to report
// how far along its turn is — without intending to touch its queue position.
func (q *FairQueue) UpdateProgress(ctx context.Context, clientID string, progress int) error {
	key := q.prefix + clientID
	resp, err := q.cli.Get(ctx, key)
	if err != nil {
		return err
	}
	if len(resp.Kvs) == 0 {
		return fmt.Errorf("ticket %s not found", clientID)
	}

	var ticket Ticket
	if err := json.Unmarshal(resp.Kvs[0].Value, &ticket); err != nil {
		return err
	}
	ticket.Progress = progress

	value, err := json.Marshal(ticket)
	if err != nil {
		return err
	}
	// This PUT bumps ModRevision on the same key — which is exactly what
	// silently reorders isHead's result above, since it sorts on ModRevision.
	_, err = q.cli.Put(ctx, key, string(value), clientv3.WithLease(q.lease))
	return err
}
