// transfer.service.ts
import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { LedgerEntry, LedgerDirection } from './ledger.entity';
import { Account } from './account.entity';

@Injectable()
export class TransferService {
  constructor(private readonly dataSource: DataSource) {}

  async transfer(fromAccountId: string, toAccountId: string, amount: string): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      const fromAccount = await manager.findOneByOrFail(Account, { id: fromAccountId });
      const toAccount = await manager.findOneByOrFail(Account, { id: toAccountId });

      // Append-only, immutable double-entry ledger rows for this one transfer.
      const debitEntry = manager.create(LedgerEntry, {
        accountId: fromAccountId,
        direction: LedgerDirection.DEBIT,
        amount,
      });
      const creditEntry = manager.create(LedgerEntry, {
        accountId: toAccountId,
        direction: LedgerDirection.CREDIT,
        amount,
      });
      await manager.save([debitEntry, creditEntry]);

      // account.balance is updated inline, in the same transaction — an
      // incrementally maintained write-through cache, NOT re-derived from the ledger.
      fromAccount.balance = (BigInt(fromAccount.balance) - BigInt(amount)).toString();
      toAccount.balance = (BigInt(toAccount.balance) + BigInt(amount)).toString();
      await manager.save([fromAccount, toAccount]);
    });
  }
}

