import { Injectable, Logger } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { InjectQueue, Processor, Process } from '@nestjs/bull';
import { Queue, Job } from 'bull';
import { Account } from './entities/account.entity';
import { LedgerEntry } from './entities/ledger-entry.entity';

interface ReconcileJobData {
  accountId: string;
  balance: number;
  cutOff: string;
}

@Injectable()
export class ReconciliationService {
  private readonly logger = new Logger(ReconciliationService.name);

  constructor(
    @InjectRepository(Account)
    private readonly accountRepo: Repository<Account>,
    @InjectQueue('reconciliation-queue')
    private readonly reconciliationQueue: Queue<ReconcileJobData>,
  ) {}

  @Cron('0 2 * * *')
  async runReconciliation(): Promise<void> {
    // Bound every SUM by this single timestamp so ledger rows written
    // after the run starts (in-flight transactions) are never counted
    // as drift.
    const cutOff = new Date();

    // FULL SCAN: loads every account with no activity filter — there is
    // no WHERE narrowing this to accounts that changed since the last run.
    const accounts = await this.accountRepo.find();

    this.logger.log(
      `Enqueuing ${accounts.length} accounts for reconciliation as of ${cutOff.toISOString()}`,
    );

    for (const account of accounts) {
      await this.reconciliationQueue.add('reconcile-account', {
        accountId: account.id,
        balance: account.balance,
        cutOff: cutOff.toISOString(),
      });
    }
  }
}

@Processor('reconciliation-queue')
export class ReconciliationProcessor {
  private readonly logger = new Logger(ReconciliationProcessor.name);

  constructor(
    @InjectRepository(LedgerEntry)
    private readonly ledgerRepo: Repository<LedgerEntry>,
  ) {}

  // SINGLE WORKER: concurrency=1 so two workers can never pick up the
  // same account and race each other into a double-fix.
  @Process({ name: 'reconcile-account', concurrency: 1 })
  async handleReconcile(job: Job<ReconcileJobData>): Promise<void> {
    const { accountId, balance, cutOff } = job.data;

    // PER-ACCOUNT RECOMPUTE: sum every ledger row for this account up to
    // the cut-off.
    const result = await this.ledgerRepo.query(
      `SELECT COALESCE(SUM(amount), 0) AS total
       FROM ledger
       WHERE account_id = $1 AND created_at <= $2`,
      [accountId, cutOff],
    );
    const computedBalance = Number(result[0].total);

    // DRIFT CHECK + COMPENSATION
    const drift = computedBalance - balance;

    if (drift !== 0) {
      await this.ledgerRepo.insert({
        accountId,
        amount: -drift,
        type: 'RECONCILE_ADJUSTMENT',
        createdAt: new Date(),
      });

      this.logger.warn(
        `Account ${accountId} drifted by ${drift}; inserted compensating entry`,
      );
    }
  }
}

import { Pool, PoolClient } from 'pg';

interface TransferResult {
  fromAccountId: string;
  toAccountId: string;
  amount: number;
  newFromBalance: number;
  newToBalance: number;
}

export class WalletService {
  constructor(private readonly pool: Pool) {}

  /**
   * Transfers `amount` from `fromAccountId` to `toAccountId` atomically.
   * Locks both account rows with SELECT ... FOR UPDATE before mutating
   * balances, so concurrent transfers touching the same account serialize
   * instead of racing on a stale balance read.
   */
  async transfer(
    fromAccountId: string,
    toAccountId: string,
    amount: number,
  ): Promise<TransferResult> {
    const client: PoolClient = await this.pool.connect();

    try {
      await client.query('BEGIN');

      // Lock the source row first, in the order the ids were passed in.
      const sourceResult = await client.query(
        'SELECT id, balance FROM accounts WHERE id = $1 FOR UPDATE',
        [fromAccountId],
      );
      if (sourceResult.rowCount === 0) {
        throw new Error(`Account ${fromAccountId} not found`);
      }
      const sourceBalance = Number(sourceResult.rows[0].balance);

      // Then lock the destination row.
      const destResult = await client.query(
        'SELECT id, balance FROM accounts WHERE id = $1 FOR UPDATE',
        [toAccountId],
      );
      if (destResult.rowCount === 0) {
        throw new Error(`Account ${toAccountId} not found`);
      }
      const destBalance = Number(destResult.rows[0].balance);

      if (sourceBalance < amount) {
        throw new Error(
          `Insufficient balance on account ${fromAccountId}: has ${sourceBalance}, needs ${amount}`,
        );
      }

      await client.query(
        'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
        [amount, fromAccountId],
      );
      await client.query(
        'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
        [amount, toAccountId],
      );

      await client.query(
        `INSERT INTO ledger_entries (account_id, entry_type, amount, related_account_id)
         VALUES ($1, 'DEBIT', $2, $3)`,
        [fromAccountId, amount, toAccountId],
      );
      await client.query(
        `INSERT INTO ledger_entries (account_id, entry_type, amount, related_account_id)
         VALUES ($1, 'CREDIT', $2, $3)`,
        [toAccountId, amount, fromAccountId],
      );

      await client.query('COMMIT');

      return {
        fromAccountId,
        toAccountId,
        amount,
        newFromBalance: sourceBalance - amount,
        newToBalance: destBalance + amount,
      };
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }
}

interface SagaStepPayload {
  amount: number
  fromAccountId?: string
  toAccountId?: string
}

interface SagaStepRow {
  id: string
  sagaId: string
  step: string
  idempotencyKey: string // `${sagaId}:${step}`
  status: "ok" | "failed"
  createdAt: Date
}

interface ActiveSaga {
  sagaId: string
  plannedSteps: string[]
  payloadFor(step: string): SagaStepPayload
}

@Injectable()
export class WalletSagaOrchestrator {
  constructor(
    private readonly walletService: WalletServiceClient, // HTTP client to the separate wallet-service
    private readonly sagaStepRepository: Repository<SagaStepRow>,
  ) {}

  /**
   * Executes a single saga step (e.g. "debit-sender", "credit-receiver")
   * by calling wallet-service, then records the outcome for audit/recovery.
   */
  async executeStep(sagaId: string, step: string, payload: SagaStepPayload): Promise<void> {
    const idempotencyKey = `${sagaId}:${step}`

    try {
      // The money-moving side effect. This is what actually changes wallet balances.
      await this.walletService.applyStep(idempotencyKey, payload)

      // Audit write happens only AFTER the HTTP call has already returned.
      // If the process dies between the line above and this insert, the
      // side effect landed but there is zero durable evidence it ran.
      await this.sagaStepRepository.insert({
        sagaId,
        step,
        idempotencyKey,
        status: "ok",
        createdAt: new Date(),
      })
    } catch (error) {
      await this.sagaStepRepository.insert({
        sagaId,
        step,
        idempotencyKey,
        status: "failed",
        createdAt: new Date(),
      })
      throw error
    }
  }

  /**
   * Runs on orchestrator restart to find work that was interrupted by a crash.
   */
  async recoveryScan(): Promise<void> {
    const recordedSteps = await this.sagaStepRepository.find()
    const recordedKeys = new Set(recordedSteps.map((row) => row.idempotencyKey))

    for (const saga of await this.loadActiveSagas()) {
      for (const step of saga.plannedSteps) {
        const idempotencyKey = `${saga.sagaId}:${step}`

        // Only "ok" and "failed" rows are ever written, so a step that
        // crashed between the wallet-service call and the audit insert
        // has no row at all. This branch cannot tell "never attempted"
        // apart from "attempted, side effect landed, crashed before logging" -
        // it just silently re-runs the step as if it never happened.
        if (!recordedKeys.has(idempotencyKey)) {
          await this.executeStep(saga.sagaId, step, saga.payloadFor(step))
        }
      }
    }
  }

  private async loadActiveSagas(): Promise<ActiveSaga[]> {
    // Loads sagas that haven't reached a terminal (all-steps-ok or compensated) state.
    return []
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { WalletEntity } from './entities/wallet.entity';
import { LedgerEntryEntity } from './entities/ledger-entry.entity';

/**
 * Result of reconciling a single wallet against its ledger.
 * All money fields are expressed in minor units (cents).
 */
export interface WalletReconciliationResult {
  walletId: string;
  expectedBalance: number;
  actualBalance: number;
  drift: number;
  compensatingAmount: number;
}

@Injectable()
export class WalletReconciliationService {
  constructor(
    @InjectRepository(WalletEntity)
    private readonly walletRepository: Repository<WalletEntity>,
    @InjectRepository(LedgerEntryEntity)
    private readonly ledgerRepository: Repository<LedgerEntryEntity>,
  ) {}

  /**
   * Recomputes the wallet's expected balance from its ledger entries,
   * compares it against the persisted actual balance, and derives the
   * compensating amount that would bring the wallet back into balance.
   * The result is returned as a plain object that gets serialized straight
   * to JSON for downstream consumers (saga orchestrator, audit service, etc).
   */
  async reconcile(walletId: string): Promise<WalletReconciliationResult> {
    const wallet = await this.walletRepository.findOneByOrFail({
      id: walletId,
    });

    const entries = await this.ledgerRepository.find({
      where: { walletId },
    });

    // Sum every ledger entry (minor units, e.g. cents) into the expected balance.
    const expectedBalance: number = entries.reduce(
      (sum, entry) => sum + entry.amountMinorUnits,
      0,
    );

    // The balance currently persisted on the wallet row, also in minor units.
    const actualBalance: number = wallet.balanceMinorUnits;

    // Ordinary JS subtraction: both operands are plain numbers (IEEE-754 doubles).
    const drift = expectedBalance - actualBalance;

    // The amount that must be posted as a compensating transaction to bring
    // actualBalance back in line with expectedBalance.
    const compensatingAmount = -drift;

    return {
      walletId,
      expectedBalance,
      actualBalance,
      drift,
      compensatingAmount,
    };
  }
}

import { setTimeout as sleep } from "node:timers/promises";

interface CircuitEntry {
  state: "closed" | "open" | "half-open";
  failures: number;
  openedAt: number;
}

interface HttpClient {
  post(url: string, payload: unknown): Promise<void>;
}

interface WebhookJob {
  host: string;
  endpoint: string;
  payload: unknown;
}

const FAILURE_THRESHOLD = 5;
const COOLDOWN_MS = 30_000;

/**
 * Delivers webhook jobs to destination endpoints, protecting each
 * destination host with an independent circuit breaker.
 */
export class WebhookDeliveryWorker {
  // Per-host circuit state, keyed by destination host.
  private circuits = new Map<string, CircuitEntry>();

  constructor(private readonly httpClient: HttpClient) {}

  /**
   * Returns whether a request to `host` is currently allowed through
   * the circuit breaker.
   */
  canSend(host: string): boolean {
    const entry = this.circuits.get(host);
    if (!entry || entry.state === "closed") {
      return true;
    }

    if (entry.state === "open") {
      const elapsed = Date.now() - entry.openedAt;
      if (elapsed < COOLDOWN_MS) {
        return false;
      }
      // Cool-down elapsed: allow a single probe through.
      entry.state = "half-open";
      return true;
    }

    // half-open: a probe is already in flight, but nothing here stops
    // a second caller from also treating this as the probe.
    return true;
  }

  /** Records a successful delivery to `host`, closing the circuit. */
  recordSuccess(host: string): void {
    this.circuits.set(host, {
      state: "closed",
      failures: 0,
      openedAt: 0,
    });
  }

  /** Records a failed delivery to `host`, tripping the breaker if needed. */
  recordFailure(host: string): void {
    const entry = this.circuits.get(host) ?? {
      state: "closed" as const,
      failures: 0,
      openedAt: 0,
    };

    entry.failures += 1;
    if (entry.failures >= FAILURE_THRESHOLD) {
      entry.state = "open";
      entry.openedAt = Date.now();
    }
    this.circuits.set(host, entry);
  }

  /** Main delivery loop: pulls jobs and sends them through the breaker. */
  async run(jobs: AsyncIterable<WebhookJob>): Promise<void> {
    for await (const job of jobs) {
      if (!this.canSend(job.host)) {
        continue;
      }

      try {
        await this.httpClient.post(job.endpoint, job.payload);
        this.recordSuccess(job.host);
      } catch {
        this.recordFailure(job.host);
        // Small backoff so a hot-looping failure doesn't spin the process.
        await sleep(50);
      }
    }
  }
}

import { Pool, PoolClient } from "pg";

const BATCH_LIMIT = 50;
const POLL_INTERVAL_MS = 1000;

interface WebhookDelivery {
  id: string;
  url: string;
  payload: unknown;
  status: "pending" | "in_flight" | "sent";
  createdAt: Date;
}

export class WebhookPoller {
  constructor(private readonly pool: Pool) {}

  /**
   * Claims the oldest pending rows and dispatches them within one transaction.
   * Runs identically on every poller replica.
   */
  async claimBatch(limit: number): Promise<WebhookDelivery[]> {
    const client: PoolClient = await this.pool.connect();
    try {
      await client.query("BEGIN");

      // Grab the oldest pending rows and lock them for this transaction.
      const { rows } = await client.query<WebhookDelivery>(
        `SELECT id, url, payload, status, created_at AS "createdAt"
         FROM webhook_deliveries
         WHERE status = 'pending'
         ORDER BY created_at
         LIMIT $1
         FOR UPDATE`,
        [limit],
      );

      for (const row of rows) {
        await this.dispatch(row);
        await client.query(
          `UPDATE webhook_deliveries SET status = 'sent' WHERE id = $1`,
          [row.id],
        );
      }

      await client.query("COMMIT");
      return rows;
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  }

  private async dispatch(row: WebhookDelivery): Promise<void> {
    await fetch(row.url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(row.payload),
    });
  }

  async runTick(): Promise<void> {
    const claimed = await this.claimBatch(BATCH_LIMIT);
    console.log(`Claimed and dispatched ${claimed.length} webhook(s)`);
  }

  start(): void {
    setInterval(() => {
      this.runTick().catch((err) => console.error("Poller tick failed", err));
    }, POLL_INTERVAL_MS);
  }
}

