import { createHmac, timingSafeEqual } from "crypto";

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET as string;
const MAX_SKEW_SECONDS = 300;

interface IncomingWebhookRequest {
  headers: {
    "x-signature"?: string;
    "x-timestamp"?: string;
  };
  rawBody: Buffer;
}

export class InvalidSignatureError extends Error {}
export class StaleTimestampError extends Error {}

/**
 * Verifies an inbound webhook delivery: recomputes the HMAC-SHA256 over the
 * raw request body and checks that the sender's timestamp is still within
 * the freshness window, so captured requests cannot be replayed later.
 */
export function verifyWebhook(req: IncomingWebhookRequest): boolean {
  const signatureHeader = req.headers["x-signature"];
  const timestampHeader = req.headers["x-timestamp"];
  const rawBody = req.rawBody;

  if (!signatureHeader || !timestampHeader) {
    throw new InvalidSignatureError("Missing signature or timestamp header");
  }

  const requestTs = Number(timestampHeader);
  if (!Number.isFinite(requestTs)) {
    throw new StaleTimestampError("Malformed timestamp header");
  }

  // Step 1: recompute the HMAC over the raw body and compare in constant time.
  const expectedSignature = createHmac("sha256", WEBHOOK_SECRET)
    .update(rawBody)
    .digest();
  const providedSignature = Buffer.from(signatureHeader, "hex");

  const isSignatureValid =
    providedSignature.length === expectedSignature.length &&
    timingSafeEqual(providedSignature, expectedSignature);

  if (!isSignatureValid) {
    throw new InvalidSignatureError("HMAC signature mismatch");
  }

  // Step 2: reject requests whose timestamp falls outside the freshness window.
  const skew = Math.abs(Date.now() / 1000 - requestTs);
  if (skew > MAX_SKEW_SECONDS) {
    throw new StaleTimestampError("Timestamp outside freshness window");
  }

  return true;
}

import express, { Request, Response, NextFunction } from "express";
import axios from "axios";
import * as crypto from "crypto";

const SECRET = "wh_shared_secret_9f21a";

// ===================== SENDER =====================

interface WebhookPayload {
  id: string;
  event: string;
  data: Record<string, unknown>;
}

/**
 * Signs `payload` and delivers it to `url`.
 */
export async function sendWebhook(url: string, payload: WebhookPayload): Promise<void> {
  // Stringify once, purely to compute the signature.
  const signature = crypto
    .createHmac("sha256", SECRET)
    .update(JSON.stringify(payload))
    .digest("hex");

  // The OBJECT (not the string we just signed) is handed to axios.
  // axios serializes `payload` a second, independent time to build the
  // actual bytes that go out on the wire.
  await axios.post(url, payload, {
    headers: {
      "Content-Type": "application/json",
      "X-Signature": signature,
    },
  });
}

// ===================== RECEIVER =====================

const app = express();

// Parses the incoming JSON into req.body and discards the original bytes.
app.use(express.json());

function verifySignature(req: Request, res: Response, next: NextFunction): void {
  const received = req.header("X-Signature");

  if (!received) {
    res.status(401).send("Missing signature");
    return;
  }

  // Recomputes the HMAC over a RE-serialization of the already-parsed body.
  const expected = crypto
    .createHmac("sha256", SECRET)
    .update(JSON.stringify(req.body))
    .digest("hex");

  if (received !== expected) {
    console.error("Signature mismatch", { received, expected });
    res.status(401).send("Signature mismatch");
    return;
  }

  next();
}

app.post("/webhooks/incoming", verifySignature, (req: Request, res: Response) => {
  console.log("Received event:", req.body.event, req.body.data);
  res.status(200).send("OK");
});

app.listen(3000, () => {
  console.log("Webhook receiver listening on port 3000");
});

// ─────────────────────────────────────────────────────────────
// webhook-worker.ts — BullMQ worker (primary path, the buggy one)
// ─────────────────────────────────────────────────────────────
import { Worker, Queue, Job } from 'bullmq';
import { Pool } from 'pg';

interface WebhookJobData {
  url: string;
  payload: Record<string, unknown>;
  host: string;
}

const MAX_ATTEMPTS = 8;
const COOLDOWN_MS = 30_000;

export const webhookQueue = new Queue<WebhookJobData>('webhook', {
  connection: { host: 'localhost', port: 6379 },
  defaultJobOptions: {
    attempts: MAX_ATTEMPTS,
    backoff: { type: 'exponential', delay: 2_000 },
  },
});

type BreakerState = 'closed' | 'open' | 'half-open';

class CircuitBreaker {
  private state: BreakerState = 'closed';
  private openedAt = 0;
  private halfOpenProbeInFlight = false;

  constructor(private readonly host: string) {}

  canRequest(): boolean {
    if (this.state === 'closed') return true;
    if (this.state === 'open') {
      if (Date.now() - this.openedAt < COOLDOWN_MS) return false;
      this.state = 'half-open';
      this.halfOpenProbeInFlight = true;
      return true;
    }
    // half-open: only the single probe already in flight may pass
    return false;
  }

  onSuccess(): void {
    this.state = 'closed';
    this.halfOpenProbeInFlight = false;
  }

  onFailure(): void {
    this.state = 'open';
    this.openedAt = Date.now();
    this.halfOpenProbeInFlight = false;
  }
}

const breakers = new Map<string, CircuitBreaker>();
function breakerFor(host: string): CircuitBreaker {
  let b = breakers.get(host);
  if (!b) {
    b = new CircuitBreaker(host);
    breakers.set(host, b);
  }
  return b;
}

async function httpPost(url: string, payload: unknown): Promise<void> {
  const res = await fetch(url, {
    method: 'POST',
    body: JSON.stringify(payload),
    headers: { 'content-type': 'application/json' },
  });
  if (!res.ok) {
    // genuine receiver rejection (4xx/5xx) — this attempt SHOULD count
    throw new Error(`receiver rejected delivery: ${res.status}`);
  }
}

export const webhookWorker = new Worker<WebhookJobData>(
  'webhook',
  async (job: Job<WebhookJobData>) => {
    const { url, payload, host } = job.data;
    const breaker = breakerFor(host);

    if (!breaker.canRequest()) {
      // BUG: this reschedules the job for later, but signals the skip with
      // an ordinary throw. BullMQ can't tell "circuit blocked me" apart from
      // a real send failure — it bumps job.attemptsMade either way, so every
      // cool-down cycle during an outage silently burns one attempt even
      // though httpPost() was never called.
      await webhookQueue.add('webhook', job.data, { delay: COOLDOWN_MS });
      throw new Error('circuit open, retry later');
    }

    try {
      await httpPost(url, payload);
      breaker.onSuccess();
    } catch (err) {
      breaker.onFailure();
      throw err;
    }
  },
  { connection: { host: 'localhost', port: 6379 } },
);

webhookWorker.on('failed', async (job) => {
  if (!job) return;
  if (job.attemptsMade >= MAX_ATTEMPTS) {
    await insertIntoDeadLetter(job.id!, job.data);
  }
});

const pgPool = new Pool();

async function insertIntoDeadLetter(jobId: string, data: WebhookJobData): Promise<void> {
  await pgPool.query(
    `INSERT INTO dead_letter (job_id, host, url, payload, created_at) VALUES ($1, $2, $3, $4, now())`,
    [jobId, data.host, data.url, JSON.stringify(data.payload)],
  );
}

// ─────────────────────────────────────────────────────────────────────
// webhook-poller.ts — SQL-backed manual-counter poller (no queue library;
// same bug, different shape)
// ─────────────────────────────────────────────────────────────────────
interface DeliveryRow {
  id: string;
  host: string;
  url: string;
  payload: Record<string, unknown>;
  attempts: number;
}

async function pollOnce(): Promise<void> {
  const { rows } = await pgPool.query<DeliveryRow>(
    `SELECT id, host, url, payload, attempts FROM deliveries
     WHERE status = 'pending' AND next_run <= now()
     FOR UPDATE SKIP LOCKED LIMIT 50`,
  );

  for (const row of rows) {
    const breaker = breakerFor(row.host);

    if (!breaker.canRequest()) {
      // BUG (same defect, manual-counter shape): reschedules next_run but
      // also bumps the attempts column, so circuit-open cool-downs alone
      // exhaust the budget and this loop below pushes the row to dead_letter.
      const nextAttempts = row.attempts + 1;
      await pgPool.query(
        `UPDATE deliveries SET attempts = $1, next_run = now() + ($2 || ' milliseconds')::interval WHERE id = $3`,
        [nextAttempts, COOLDOWN_MS, row.id],
      );
      if (nextAttempts >= MAX_ATTEMPTS) {
        await pgPool.query(
          `INSERT INTO dead_letter (job_id, host, url, payload, created_at) VALUES ($1, $2, $3, $4, now())`,
          [row.id, row.host, row.url, JSON.stringify(row.payload)],
        );
        await pgPool.query(`UPDATE deliveries SET status = 'dead' WHERE id = $1`, [row.id]);
      }
      continue;
    }

    try {
      await httpPost(row.url, row.payload);
      await pgPool.query(`UPDATE deliveries SET status = 'sent' WHERE id = $1`, [row.id]);
      breaker.onSuccess();
    } catch {
      breaker.onFailure();
      const attempts = row.attempts + 1;
      if (attempts >= MAX_ATTEMPTS) {
        await pgPool.query(
          `INSERT INTO dead_letter (job_id, host, url, payload, created_at) VALUES ($1, $2, $3, $4, now())`,
          [row.id, row.host, row.url, JSON.stringify(row.payload)],
        );
        await pgPool.query(`UPDATE deliveries SET status = 'dead', attempts = $1 WHERE id = $2`, [attempts, row.id]);
      } else {
        await pgPool.query(
          `UPDATE deliveries SET attempts = $1, next_run = now() + ($2 || ' milliseconds')::interval WHERE id = $3`,
          [attempts, COOLDOWN_MS, row.id],
        );
      }
    }
  }
}

