const pool = new Pool({
  host: process.env.PGHOST,
  database: process.env.PGDATABASE,
  max: 20,
});

interface OrderPaidPayload {
  orderId: string;
  amount: number;
  currency: string;
  paidAt: string;
}

/**
 * Handles the order.paid domain event: marks the order as paid and
 * notifies the merchant's registered webhook subscriber.
 */
export async function handleOrderPaid(
  orderId: string,
  payload: OrderPaidPayload,
): Promise<void> {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // 1. Business write — takes a row lock on this order until COMMIT.
    await client.query(
      `UPDATE orders SET status = $1, paid_at = $2 WHERE id = $3`,
      ['paid', payload.paidAt, orderId],
    );

    // 2. Outbox write — the durable record the delivery is supposed to
    // be replayed from if the send below never happens.
    const outboxResult = await client.query(
      `INSERT INTO webhook_outbox (event_type, payload, delivered)
       VALUES ($1, $2, false)
       RETURNING id`,
      ['order.paid', JSON.stringify(payload)],
    );
    const outboxId = outboxResult.rows[0].id;

    // 3. Fetch the subscriber URL for this merchant's order.
    const subscriberResult = await client.query(
      `SELECT webhook_url FROM webhook_subscribers WHERE order_id = $1`,
      [orderId],
    );
    const subscriberUrl = subscriberResult.rows[0].webhook_url;

    // 4. Send the webhook — still inside the open transaction.
    await httpClient.post(subscriberUrl, payload);

    // 5. Only mark the outbox row delivered once the POST above resolves.
    await client.query(
      `UPDATE webhook_outbox SET delivered = true WHERE id = $1`,
      [outboxId],
    );

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

import Redis from "ioredis";
import type { Socket } from "./socket";

/**
 * ChatNode owns one Redis subscriber connection and the set of sockets
 * that are locally connected to each room ON THIS NODE.
 */
export class ChatNode {
  private readonly redisSub: Redis;

  // Sockets connected to THIS node, keyed by roomId.
  private readonly localMembers = new Map<string, Set<Socket>>();

  constructor(redisSub: Redis) {
    this.redisSub = redisSub;
    this.redisSub.on("message", (channel, payload) => this.onMessage(channel, payload));
  }

  private channelFor(roomId: string): string {
    return `room:${roomId}`;
  }

  /**
   * Called when a socket joins a room on this node.
   */
  async joinRoom(socket: Socket, roomId: string): Promise<void> {
    let members = this.localMembers.get(roomId);
    if (!members) {
      members = new Set<Socket>();
      this.localMembers.set(roomId, members);
    }
    members.add(socket);

    // Subscribe every time a member joins, regardless of whether this node
    // is already subscribed to the room's channel.
    await this.redisSub.subscribe(this.channelFor(roomId));
  }

  /**
   * Called when a socket leaves a room (explicit leave or disconnect).
   */
  async leaveRoom(socket: Socket, roomId: string): Promise<void> {
    const members = this.localMembers.get(roomId);
    if (!members) return;

    members.delete(socket);

    if (members.size === 0) {
      this.localMembers.delete(roomId);
      // NOTE: the channel subscription is never torn down here.
    }
  }

  /**
   * Redis pub/sub delivery handler: fan out an incoming room message to
   * whichever local sockets are currently in that room.
   */
  private onMessage(channel: string, payload: string): void {
    const roomId = channel.replace(/^room:/, "");
    const message = JSON.parse(payload);

    const members = this.localMembers.get(roomId);
    if (!members || members.size === 0) {
      // No local recipients for this room -- message is discarded after
      // being parsed. If this node no longer serves the room at all, this
      // work happened for nothing.
      return;
    }

    for (const socket of members) {
      socket.send(JSON.stringify(message));
    }
  }
}

import Redis from 'ioredis';

const ONLINE_KEY = 'online:users';

export class PresenceService {
  private readonly redis: Redis;

  constructor(redis: Redis) {
    this.redis = redis;
  }

  // Called from the WebSocket gateway's connection handler.
  // userId is a 64-bit snowflake id, passed straight in as the bitmap OFFSET.
  async markOnline(userId: number): Promise<void> {
    await this.redis.setbit(ONLINE_KEY, userId, 1);
  }

  // Called from the WebSocket gateway's disconnect handler.
  async markOffline(userId: number): Promise<void> {
    await this.redis.setbit(ONLINE_KEY, userId, 0);
  }

  // Live headcount of online users.
  async getOnlineCount(): Promise<number> {
    return this.redis.bitcount(ONLINE_KEY);
  }
}

import type Redis from "ioredis";
import {
  WebSocketGateway,
  OnGatewayConnection,
  OnGatewayDisconnect,
} from "@nestjs/websockets";
import type { Socket } from "socket.io";

// Bitmap key: 1 bit per userId, offset = numeric userId.
const ONLINE_KEY = "presence:online";

/**
 * Runs identically on every node in the cluster; all nodes share
 * the same Redis instance for presence state.
 */
@WebSocketGateway()
export class PresenceGateway implements OnGatewayConnection, OnGatewayDisconnect {
  constructor(private readonly redis: Redis) {}

  private extractUserId(socket: Socket): number {
    // Set by the auth middleware after verifying the connection's JWT.
    return socket.data.userId as number;
  }

  async handleConnection(socket: Socket): Promise<void> {
    const userId = this.extractUserId(socket);

    await this.redis.setbit(ONLINE_KEY, userId, 1);
    socket.broadcast.emit("user-online", { userId });
  }

  async handleDisconnect(socket: Socket): Promise<void> {
    const userId = this.extractUserId(socket);

    // Every socket disconnect is treated as "this user is entirely gone."
    await this.redis.setbit(ONLINE_KEY, userId, 0);
    socket.broadcast.emit("user-offline", { userId });
  }

  /** Consumed by the friends-list query to render the online/offline dot. */
  async isOnline(userId: number): Promise<boolean> {
    const bit = await this.redis.getbit(ONLINE_KEY, userId);
    return bit === 1;
  }
}

import { Injectable } from '@nestjs/common';
import Redis from 'ioredis';

interface StoredMessage {
  messageId: string;
  seq: number;
  text: string;
}

const DEDUP_TTL_SECONDS = 300;

@Injectable()
export class ChatService {
  constructor(private readonly redis: Redis) {}

  /**
   * Accepts a client-submitted chat message for a room.
   * Must be idempotent: retrying with the same messageId should
   * return the original accepted message without side effects.
   */
  async accept(roomId: string, messageId: string, text: string): Promise<StoredMessage> {
    const seqKey = `seq:${roomId}`;
    const dedupKey = `msg:${messageId}`;
    const logKey = `log:${roomId}`;

    // Claim the next ordering position for this room.
    const seq = await this.redis.incr(seqKey);

    const message: StoredMessage = { messageId, seq, text };

    // Try to record this messageId as seen; NX means "only if not already set".
    const firstWriter = await this.redis.set(
      dedupKey,
      JSON.stringify(message),
      'EX',
      DEDUP_TTL_SECONDS,
      'NX',
    );

    // firstWriter is null when the key already existed (a retry), but the
    // result isn't checked here, so the write below always happens.
    void firstWriter;

    await this.redis.zadd(logKey, seq, JSON.stringify(message));

    return message;
  }
}

interface ChatEnvelope {
  messageId: string;
  roomId: string;
  senderId: string;
  text: string;
  sentAt: number;
}

interface ClientSocket {
  readonly socketId: string;
  emit(event: string, payload: ChatEnvelope): void;
}

interface PubSubClient {
  subscribe(channel: string, handler: (envelope: ChatEnvelope) => void): void;
  publish(channel: string, envelope: ChatEnvelope): Promise<void>;
}

/**
 * One stateless gateway node in the cluster. Multiple instances of this
 * class run behind a load balancer; `pubsub` is how they stay in sync.
 */
export class ChatGateway {
  private readonly nodeId: string;
  private readonly pubsub: PubSubClient;
  // Sockets currently attached to THIS node, keyed by roomId.
  private readonly localSockets: Map<string, Set<ClientSocket>> = new Map();

  constructor(nodeId: string, pubsub: PubSubClient) {
    this.nodeId = nodeId;
    this.pubsub = pubsub;
  }

  /** Called the first time this node has a local subscriber for a room. */
  private ensureSubscribed(roomId: string): void {
    if (this.localSockets.has(roomId)) return;
    this.localSockets.set(roomId, new Set());
    // On startup (per-room, lazily) the node registers a subscription handler:
    // every node, including the one that originated the message, receives
    // the envelope from the channel and hands it to its local clients.
    this.pubsub.subscribe(this.channelFor(roomId), (envelope) =>
      this.onBackplaneMessage(envelope),
    );
  }

  registerSocket(roomId: string, socket: ClientSocket): void {
    this.ensureSubscribed(roomId);
    this.localSockets.get(roomId)!.add(socket);
  }

  unregisterSocket(roomId: string, socket: ClientSocket): void {
    this.localSockets.get(roomId)?.delete(socket);
  }

  /**
   * Handles an outbound chat message from a client attached to this node.
   */
  async handleSend(roomId: string, senderId: string, text: string): Promise<void> {
    const envelope: ChatEnvelope = {
      messageId: `${this.nodeId}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      roomId,
      senderId,
      text,
      sentAt: Date.now(),
    };

    // Optimistic local emit so nearby clients see it instantly, without
    // waiting on a round-trip through the backplane.
    this.deliverLocal(envelope);

    // Fan the message out to every other node (and, incidentally, back to
    // this one) via the shared pub/sub channel for the room.
    await this.pubsub.publish(this.channelFor(roomId), envelope);
  }

  /**
   * Subscription callback for this node's channel. This is meant to be the
   * single place messages get handed to local sockets.
   */
  private onBackplaneMessage(envelope: ChatEnvelope): void {
    this.deliverLocal(envelope);
  }

  private deliverLocal(envelope: ChatEnvelope): void {
    const sockets = this.localSockets.get(envelope.roomId);
    if (!sockets || sockets.size === 0) return;
    for (const socket of sockets) {
      socket.emit('message', envelope);
    }
  }

  private channelFor(roomId: string): string {
    return `chat:room:${roomId}`;
  }
}

