/**
 * Consumes one message off the notification queue.
 * Must guarantee at-most-once delivery per `messageId`, even though
 * the upstream broker delivers at-least-once and the same `messageId`
 * can be picked up by two workers at roughly the same time.
 */
export function createNotificationProcessor({ db, redis }: NotificationWorkerDeps) {
  return async function processNotification(message: NotificationMessage): Promise<void> {
    const { messageId } = message;

    // Round-trip 1: check whether this messageId has already been recorded.
    const existing = await db.query(
      'SELECT id FROM sent_messages WHERE message_id = $1',
      [messageId],
    );

    if (existing.rows.length > 0) {
      // Already sent, skip.
      return;
    }

    // Round-trip 2: record the messageId, then send.
    await db.query(
      'INSERT INTO sent_messages (message_id) VALUES ($1)',
      [messageId],
    );

    await sendNotification(message);
  };
}

