  to: string;
  templateId: string;
  params: Record<string, string | number>;
}

@Processor('notifications')
export class NotificationProcessor extends WorkerHost {
  private readonly logger = new Logger(NotificationProcessor.name);

  constructor(
    private readonly primaryProvider: PrimaryEmailProvider,
    // Injected per the "we fail over to the backup provider" PR description,
    // but process() below never actually calls it.
    private readonly fallbackProvider: FallbackEmailProvider,
  ) {
    super();
  }

  async process(job: Job<NotificationJobPayload>): Promise<void> {
    const { channel, to, templateId, params } = job.data;

    try {
      await this.primaryProvider.send(channel, to, templateId, params);
    } catch (err) {
      this.logger.error(err);
      // "Failover" per the PR: just rethrow and let BullMQ's attempts +
      // exponential backoff (see notification-queue.module.ts) retry the job.
      // On the next attempt this.primaryProvider is called again — the
      // fallbackProvider above is never invoked anywhere in this class.
      throw err;
    }
  }
}

