}

function emitFraudAlert(ip: string, totalClicks: number): void {
  console.warn(`[fraud] alert ip=${ip} totalClicks=${totalClicks}`);
}

/**
 * Stream/queue consumer callback invoked for every incoming click event.
 */
export function processClick(event: ClickEvent): void {
  const ip = event.ip;

  clickCounts.set(ip, (clickCounts.get(ip) ?? 0) + 1);

  const total = clickCounts.get(ip) ?? 0;
  if (total > FRAUD_THRESHOLD) {
    blockIp(ip);
    emitFraudAlert(ip, total);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EventPattern, Payload } from '@nestjs/microservices';

interface ClickEvent {
  clickId: string;
  adId: string;
  timestamp: number;
}

@Injectable()
export class ClickAggregatorConsumer {
  private readonly logger = new Logger(ClickAggregatorConsumer.name);

  // Tracks every clickId we've ever processed, so a Kafka retry/redelivery
  // of the same message doesn't get folded into the window counts twice.
  private readonly seenClickIds = new Set<string>();

  // In-memory tumbling-window aggregate, later batch-flushed to ClickHouse
  // by a separate scheduled job (not shown).
  private readonly windowCounts = new WindowAggregate();

  @EventPattern('ad.clicks')
  handleClick(@Payload() message: Record<string, unknown>): void {
    const event = this.parseEvent(message);
    const windowStart = this.deriveWindowStart(event.timestamp);

    if (this.seenClickIds.has(event.clickId)) {
      // already counted, skip
      return;
    }

    this.seenClickIds.add(event.clickId);
    this.windowCounts.increment(event.adId, windowStart);
  }

  private parseEvent(message: Record<string, unknown>): ClickEvent {
    return {
      clickId: String(message.clickId),
      adId: String(message.adId),
      timestamp: Number(message.timestamp),
    };
  }

  private deriveWindowStart(timestamp: number): number {
    const ONE_MINUTE_MS = 60_000;
    return Math.floor(timestamp / ONE_MINUTE_MS) * ONE_MINUTE_MS;
  }
}

/**
 * Per-minute tumbling-window counter, keyed by adId + windowStart.
 * Lives only in process heap until the next flush cycle.
 */
class WindowAggregate {
  private readonly counts = new Map<string, number>();

  increment(adId: string, windowStart: number): void {
    const key = `${adId}:${windowStart}`;
    this.counts.set(key, (this.counts.get(key) ?? 0) + 1);
  }

  snapshot(): ReadonlyMap<string, number> {
    return new Map(this.counts);
  }
}

import { Injectable } from '@nestjs/common';
import { ClickHouseClient, createClient } from '@clickhouse/client';

// Table (created via migration, shown here for reference):
//
// CREATE TABLE ad_click_counts
// (
//   adId        String,
//   windowStart DateTime,
//   count       UInt64,
//   version     UInt64
// )
// ENGINE = ReplacingMergeTree(version)
// ORDER BY (adId, windowStart);

@Injectable()
export class AdClickAggregatorService {
  private readonly client: ClickHouseClient;

  constructor() {
    this.client = createClient({ url: process.env.CLICKHOUSE_URL });
  }

  /**
   * Records a single ad click. Invoked once per incoming click event from
   * the ingestion pipeline — for a viral ad this can be thousands per second.
   */
  async recordClick(adId: string): Promise<void> {
    const windowStart = this.floorToMinute(new Date());
    const version = Date.now();

    // One row in, one INSERT out — on every single click, no accumulation.
    await this.client.insert({
      table: 'ad_click_counts',
      values: [
        {
          adId,
          windowStart: this.formatDateTime(windowStart),
          count: 1,
          version,
        },
      ],
      format: 'JSONEachRow',
    });
  }

  /**
   * Read path hit directly by the live advertiser dashboard on every refresh.
   */
  async getCount(adId: string, windowStart: Date): Promise<number> {
    const result = await this.client.query({
      query: `
        SELECT sum(count) AS total
        FROM ad_click_counts FINAL
        WHERE adId = {adId: String}
          AND windowStart = {windowStart: DateTime}
      `,
      query_params: {
        adId,
        windowStart: this.formatDateTime(windowStart),
      },
      format: 'JSONEachRow',
    });

    const rows = await result.json<{ total: string }>();
    return rows.length > 0 ? Number(rows[0].total) : 0;
  }

  private floorToMinute(date: Date): Date {
    const ms = date.getTime();
    return new Date(ms - (ms % 60_000));
  }

  private formatDateTime(date: Date): string {
    return date.toISOString().slice(0, 19).replace('T', ' ');
  }
}

