@Injectable()
export class ProductSearchIndexRebuildService {
  constructor(
    private readonly eventStore: EventStoreService,
    private readonly esClient: Client,
  ) {}

  /**
   * Rebuilds the "products" search index from scratch by replaying the
   * entire event-sourced write-model history and re-deriving the
   * read-model projection for every product.
   */
  async rebuildProductSearchIndex(): Promise<void> {
    // Replay the full write-model history into in-memory projections.
    const events = await this.eventStore.readAll('product');
    const projections = project(events); // Map<productId, ProductProjection>

    for (const [productId, projection] of projections) {
      // One document at a time, straight into the LIVE index that
      // GET /products/search is still reading from — no bulk API.
      await this.esClient.index({
        index: 'products',
        id: productId,
        document: projection,
        refresh: true, // forces a costly segment flush on every single document
      });
    }
  }
}

function project(events: ProductEvent[]): Map<string, ProductProjection> {
  const byId = new Map<string, ProductProjection>();
  for (const event of events) {
    const current = byId.get(event.productId);
    byId.set(event.productId, applyEvent(current, event));
  }
  return byId;
}
