import { EachMessagePayload } from "kafkajs";

// Minimal shape of the redis client used for the dedup set.
interface DedupStore {
  has(key: string): Promise<boolean>;
  add(key: string): Promise<void>;
}

// Minimal shape of a DB transaction handle.
interface DbTransaction {
  query(sql: string, params: unknown[]): Promise<void>;
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

interface Db {
  beginTransaction(): Promise<DbTransaction>;
}

interface WalletCreditEvent {
  eventId: string;
  walletId: string;
  amountCents: number;
}

const PROCESSED_EVENTS_KEY = "processed_events";

export class WalletCreditConsumer {
  constructor(
    private readonly dedupStore: DedupStore,
    private readonly db: Db,
  ) {}

  /**
   * eachMessage handler for the wallet-credit topic. Kafka redelivers on
   * consumer restart / rebalance / ack timeout, so this must be safe to
   * run twice for the same message without double-crediting the wallet.
   */
  async handleMessage({ message }: EachMessagePayload): Promise<void> {
    if (!message.value) {
      return;
    }

    const event: WalletCreditEvent = JSON.parse(message.value.toString());
    const dedupKey = event.eventId;

    // Skip if we've already handled this event.
    const alreadyProcessed = await this.dedupStore.has(dedupKey);
    if (alreadyProcessed) {
      return;
    }

    // Claim the dedup key up front, before the effect is durable.
    await this.dedupStore.add(dedupKey);

    // Persist the actual effect afterwards, in a separate transaction.
    // If the process dies between the add() above and the commit()
    // below, dedupKey is already set but the credit was never applied.
    const tx = await this.db.beginTransaction();
    try {
      await this.persistWalletCredit(tx, event);
      await tx.commit();
    } catch (err) {
      await tx.rollback();
      throw err;
    }
  }

  private async persistWalletCredit(
    tx: DbTransaction,
    event: WalletCreditEvent,
  ): Promise<void> {
    await tx.query(
      "UPDATE wallets SET balance_cents = balance_cents + $1 WHERE id = $2",
      [event.amountCents, event.walletId],
    );
    await tx.query(
      "INSERT INTO wallet_ledger (event_id, wallet_id, amount_cents) VALUES ($1, $2, $3)",
      [event.eventId, event.walletId, event.amountCents],
    );
  }
}

import { Kafka, Producer } from 'kafkajs';

const kafka = new Kafka({
  clientId: 'event-ingestion-service',
  brokers: ['broker-1:9092', 'broker-2:9092', 'broker-3:9092'],
});

const producer: Producer = kafka.producer();

// Topic 'account-events' is provisioned with 12 partitions, consumed by
// a matching 12-consumer group (see consumer-group.ts).
const TOPIC = 'account-events';

// Only ~5 distinct country codes exist across our account base, and traffic
// is heavily skewed: the vast majority of accounts are 'US'.
type CountryCode = 'US' | 'GB' | 'DE' | 'IN' | 'BR';

interface AccountEvent {
  accountId: string; // UUID, high cardinality
  countryCode: CountryCode; // low cardinality, skewed toward 'US'
  eventType: 'login' | 'purchase' | 'profile_update' | 'logout';
  payload: Record<string, unknown>;
}

async function connect(): Promise<void> {
  await producer.connect();
}

/**
 * Publishes an account event to the account-events topic.
 *
 * The message key is set to countryCode to keep events ordered --
 * Kafka guarantees ordering only for messages sharing the same key,
 * so every event for a given key lands on the same partition in the
 * order it was produced.
 */
async function publishEvent(event: AccountEvent): Promise<void> {
  await producer.send({
    topic: TOPIC,
    messages: [
      {
        key: event.countryCode,
        value: JSON.stringify(event),
      },
    ],
  });
}

function randomAccountId(): string {
  return `acct-${Math.random().toString(36).slice(2, 10)}`;
}

// Skewed distribution: 'US' dominates, matching real production traffic.
function pickCountryCode(): CountryCode {
  const roll = Math.random();
  if (roll < 0.9) return 'US';
  if (roll < 0.93) return 'GB';
  if (roll < 0.96) return 'DE';
  if (roll < 0.98) return 'IN';
  return 'BR';
}

const EVENT_TYPES: AccountEvent['eventType'][] = [
  'login',
  'purchase',
  'profile_update',
  'logout',
];

async function runLoad(totalEvents: number): Promise<void> {
  await connect();

  for (let i = 0; i < totalEvents; i++) {
    const event: AccountEvent = {
      accountId: randomAccountId(),
      countryCode: pickCountryCode(),
      eventType: EVENT_TYPES[Math.floor(Math.random() * EVENT_TYPES.length)],
      payload: { seq: i, ts: Date.now() },
    };

    await publishEvent(event);
  }

  await producer.disconnect();
}

runLoad(200_000).catch((err) => {
  console.error('event-ingestion producer failed', err);
  process.exit(1);
});

