class DuplicateError extends Error {
  constructor(dedupKey: string) {
    super(`Message already processed: ${dedupKey}`);
    this.name = 'DuplicateError';
  }
}

interface OrderEventPayload {
  orderId: string;
  status: string;
  simulateFailure?: boolean;
}

async function handleOrderEvent(payload: OrderEventPayload): Promise<void> {
  await db.transaction(async (trx) => {
    if (payload.simulateFailure) {
      // Deterministic poison message used to exercise the error path.
      throw new Error(`Simulated failure for order ${payload.orderId}`);
    }

    await trx('order_events').insert({
      order_id: payload.orderId,
      status: payload.status,
      processed_at: new Date(),
    });
  });
}

export async function eachMessage({ topic, partition, message }: EachMessagePayload): Promise<void> {
  const dedupKey = `dedup:${topic}:${partition}:${message.key?.toString() ?? message.offset}`;

  // Fast idempotency check: NX only succeeds if the key didn't already exist.
  const isNew = await redis.set(dedupKey, '1', 'EX', DEDUP_TTL_SECONDS, 'NX');
  if (!isNew) {
    // A duplicate delivery is treated as an error instead of a no-op success.
    throw new DuplicateError(dedupKey);
  }

  const payload = JSON.parse(message.value?.toString() ?? '{}') as OrderEventPayload;

  try {
    await handleOrderEvent(payload);
  } catch (err) {
    // dlqProducer/DLQ_TOPIC are provisioned but never referenced here —
    // the genuine failure is just rethrown, never routed to the DLQ.
    throw err;
  }
}

export async function run(): Promise<void> {
  await consumer.connect();
  await dlqProducer.connect();
  await consumer.subscribe({ topic: 'orders.events', fromBeginning: false });
  await consumer.run({ eachMessage });
}

import { Kafka, Consumer, EachMessagePayload } from "kafkajs";
import { randomUUID } from "node:crypto";
import { emailService } from "./email.service";

const kafka = new Kafka({
  clientId: "notification-service",
  brokers: (process.env.KAFKA_BROKERS ?? "localhost:9092").split(","),
});

// Generated fresh every time the process boots, so it's different
// after every restart/redeploy (a per-pod hostname would have the
// same problem in k8s).
const instanceId = randomUUID();

export class NotificationConsumer {
  private consumer: Consumer;

  constructor() {
    this.consumer = kafka.consumer({
      // "Unique per instance so consumers never clash."
      groupId: `notification-consumer-${instanceId}`,
    });
  }

  async start(): Promise<void> {
    await this.consumer.connect();

    await this.consumer.subscribe({
      topic: "user-events",
      // "Make sure we never miss events."
      fromBeginning: true,
    });

    await this.consumer.run({
      eachMessage: async ({ message }: EachMessagePayload) => {
        const event = JSON.parse(message.value?.toString() ?? "{}");

        if (event.type === "USER_REGISTERED") {
          await emailService.send({
            to: event.email,
            template: "welcome",
            data: { name: event.name },
          });
        }
      },
    });
  }

  async stop(): Promise<void> {
    await this.consumer.disconnect();
  }
}

const amqplib = require('amqplib');

/**
 * Publishes a batch of messages to a RabbitMQ exchange with publisher-confirm
 * durability: the broker must acknowledge each message before we're sure
 * it was durably stored.
 *
 * @param {import('amqplib').Connection} connection - an open AMQP connection, one network hop from this worker
 * @param {string} exchange - the exchange to publish to
 * @param {string} routingKey - the routing key for each message
 * @param {string[]} messages - the batch of N message payloads to publish
 * @returns {Promise<void>} resolves once every message in the batch has been confirmed
 */
async function publishBatch(connection, exchange, routingKey, messages) {
  // Confirm channel: enables publisher confirms so the broker acks/nacks each publish.
  const channel = await connection.createConfirmChannel();

  for (const message of messages) {
    channel.publish(exchange, routingKey, Buffer.from(message));
    // Wait for THIS message's confirm before the loop moves on to the next publish.
    await channel.waitForConfirms();
  }

  await channel.close();
}

module.exports = { publishBatch };

import Redis from "ioredis";

interface BucketState {
  tokens: number;
  lastRefill: number;
}

interface RateLimiterConfig {
  capacity: number; // max tokens in the bucket
  refillRate: number; // tokens added per second
}

export class RateLimiter {
  private readonly redis: Redis;
  private readonly capacity: number;
  private readonly refillRate: number;

  constructor(redis: Redis, config: RateLimiterConfig) {
    this.redis = redis;
    this.capacity = config.capacity;
    this.refillRate = config.refillRate;
  }

  async allow(clientId: string): Promise<boolean> {
    const key = `rl:${clientId}`;
    const now = Date.now();

    const raw = await this.redis.hgetall(key);
    let tokens: number;
    let lastRefill: number;

    if (raw && raw.tokens !== undefined && raw.lastRefill !== undefined) {
      tokens = parseFloat(raw.tokens);
      lastRefill = parseFloat(raw.lastRefill);
    } else {
      tokens = this.capacity;
      lastRefill = now;
    }

    // Refill based on elapsed time since the last write.
    const elapsedSeconds = (now - lastRefill) / 1000;
    tokens = Math.min(this.capacity, tokens + elapsedSeconds * this.refillRate);
    lastRefill = now;

    let allowed: boolean;
    if (tokens >= 1) {
      tokens -= 1;
      allowed = true;
    } else {
      allowed = false;
    }

    // Persist the updated bucket state on every request (hot path).
    await this.redis.hset(key, {
      tokens: tokens.toString(),
      lastRefill: lastRefill.toString(),
    });

    return allowed;
  }
}

async function runOrderWorker(channel: amqp.Channel): Promise<void> {
  await channel.assertExchange(EXCHANGES.DIRECT, ExchangeKind.Direct, { durable: true })
  await channel.assertQueue(QUEUES.ORDERS_PROCESS, { durable: true })
  await channel.bindQueue(QUEUES.ORDERS_PROCESS, EXCHANGES.DIRECT, ORDERS_ROUTING_KEY)
  await channel.prefetch(1)
  await channel.consume(QUEUES.ORDERS_PROCESS, async (msg) => {
    if (!msg) return
    // Ack right away — the broker now considers this message DONE.
    channel.ack(msg)
    const order = JSON.parse(msg.content.toString())
    await fulfillmentService.fulfill(order) // throws, or the process can crash, mid-flight
  })
}

import { Queue, Worker, Job } from 'bullmq';

interface JobPayload {
  userId: string;
  amount: number;
}

const connection = { host: '127.0.0.1', port: 6379 };

// Main work queue: self-schedules retries with exponential backoff.
export const workQueue = new Queue<JobPayload>('billing-jobs', {
  connection,
  defaultJobOptions: {
    attempts: 5,
    backoff: {
      type: 'exponential',
      delay: 1000,
    },
  },
});

// Separate queue that parks permanently-broken ("poison") jobs.
export const deadLetterQueue = new Queue('billing-jobs-dlq', { connection });

/**
 * Side effect attached to the job: charges the user and sends an alert.
 * NOT idempotent yet — calling it twice for the same job double-charges/
 * double-alerts.
 */
async function chargeAndAlert(payload: JobPayload): Promise<void> {
  await chargeUser(payload.userId, payload.amount);
  await sendAlert(payload.userId, `Charge of ${payload.amount} processed`);
}

const worker = new Worker<JobPayload>(
  'billing-jobs',
  async (job: Job<JobPayload>) => {
    // Real work — throws on failure so BullMQ marks this attempt failed
    // and (if attempts remain) automatically re-schedules a retry with backoff.
    await chargeAndAlert(job.data);
  },
  { connection },
);

// THE BUG: this fires on EVERY failed attempt, not only once retries
// are exhausted. It never reads job.attemptsMade and never compares it
// against job.opts.attempts, so a transient failure (fails twice, then
// succeeds) still gets dead-lettered on attempt #1 and #2 — and the
// side effect ends up re-firing every time this handler runs.
worker.on('failed', async (job, err) => {
  if (!job) return;

  await deadLetterQueue.add('dead', {
    jobId: job.id,
    data: job.data,
    reason: err.message,
  });
});

