import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL);

const CAPACITY = 100; // max tokens per client
const REFILL_RATE = 10; // tokens per second

interface BucketState {
  tokens: number;
  lastRefill: number; // epoch ms
}

/**
 * Token-bucket rate limiter for job-submission requests, backed by Redis
 * so every service instance shares the same limit per client.
 */
export class RateLimiter {
  constructor(private readonly redis: Redis) {}

  async allow(clientId: string): Promise<boolean> {
    const key = `rate_limit:${clientId}`;

    // 1) READ current state
    const raw = await this.redis.get(key);
    const now = Date.now();
    const state: BucketState = raw
      ? JSON.parse(raw)
      : { tokens: CAPACITY, lastRefill: now };

    // 2) REFILL based on elapsed time
    const elapsedSeconds = (now - state.lastRefill) / 1000;
    const refilled = Math.min(
      CAPACITY,
      state.tokens + elapsedSeconds * REFILL_RATE,
    );

    // 3) COMPARE
    if (refilled < 1) {
      await this.redis.set(
        key,
        JSON.stringify({ tokens: refilled, lastRefill: now }),
      );
      return false;
    }

    // 4) DECREMENT + WRITE BACK
    const newState: BucketState = { tokens: refilled - 1, lastRefill: now };
    await this.redis.set(key, JSON.stringify(newState));
    return true;
  }
}

/**
 * Alternative limiter that keeps counters in process memory instead of Redis.
 * Simpler and avoids a Redis round-trip, but only correct on a single instance.
 */
const buckets = new Map<string, BucketState>();

export class InMemoryRateLimiter {
  async allow(clientId: string): Promise<boolean> {
    const now = Date.now();
    const state = buckets.get(clientId) ?? { tokens: CAPACITY, lastRefill: now };

    const elapsedSeconds = (now - state.lastRefill) / 1000;
    const refilled = Math.min(CAPACITY, state.tokens + elapsedSeconds * REFILL_RATE);

    if (refilled < 1) {
      buckets.set(clientId, { tokens: refilled, lastRefill: now });
      return false;
    }

    buckets.set(clientId, { tokens: refilled - 1, lastRefill: now });
    return true;
  }
}

// --- existing test (passing) ---
describe("RateLimiter", () => {
  it("rejects requests once the bucket is empty", async () => {
    const limiter = new RateLimiter(redis);
    const clientId = "client-1";

    let allowedCount = 0;
    for (let i = 0; i < CAPACITY + 5; i++) {
      // eslint-disable-next-line no-await-in-loop
      const allowed = await limiter.allow(clientId);
      if (allowed) allowedCount++;
    }

    expect(allowedCount).toBe(CAPACITY);
  });
});

import { Request, Response } from "express";
import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL);

// Single global key holding every place in the entire dataset, regardless of city/region.
const LOCATIONS_KEY = "locations";

/**
 * Called whenever a place is created/updated anywhere in the system.
 * Every point, no matter which city it belongs to, lands in the same GEO key.
 */
export async function indexPlace(placeId: string, lng: number, lat: number): Promise<void> {
  await redis.geoadd(LOCATIONS_KEY, lng, lat, placeId);
}

function haversineKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

interface NearbyPlace {
  placeId: string;
  distanceKm: number;
}

/**
 * GET /places/nearby?lat=..&lng=..&radiusKm=..
 */
export async function findNearby(req: Request, res: Response): Promise<void> {
  const lat = Number(req.query.lat);
  const lng = Number(req.query.lng);
  const radiusKm = Number(req.query.radiusKm);

  // Pull every member of the global key back to the app first.
  const allPlaceIds = await redis.zrange(LOCATIONS_KEY, 0, -1);

  if (allPlaceIds.length === 0) {
    res.json({ results: [] });
    return;
  }

  // Then fetch coordinates for every single one of them.
  const positions = await redis.geopos(LOCATIONS_KEY, ...allPlaceIds);

  const candidates: NearbyPlace[] = [];
  for (let i = 0; i < allPlaceIds.length; i++) {
    const pos = positions[i];
    if (!pos) continue;

    const placeLng = Number(pos[0]);
    const placeLat = Number(pos[1]);

    // Distance math done in the application, point by point.
    const distanceKm = haversineKm(lat, lng, placeLat, placeLng);
    if (distanceKm <= radiusKm) {
      candidates.push({ placeId: allPlaceIds[i], distanceKm });
    }
  }

  // Sort survivors by distance in JS after the fact.
  candidates.sort((a, b) => a.distanceKm - b.distanceKm);

  res.json({ results: candidates });
}

import Redis from "ioredis";

/**
 * Stores a per-user "recent activity" feed (notifications / recent events) in Redis.
 * One Redis list per user, newest event at the head.
 */
export class RecentFeedService {
  constructor(private readonly redis: Redis) {}

  private feedKey(userId: string): string {
    return `feed:${userId}`;
  }

  /**
   * Records a new event for the user's feed.
   */
  async addEvent(userId: string, entry: string): Promise<void> {
    // Newest entry goes to the head of the list.
    await this.redis.lpush(this.feedKey(userId), entry);
  }

  /**
   * Returns the user's feed, newest first.
   */
  async getFeed(userId: string): Promise<string[]> {
    // Reads the entire collection, no matter how large it has grown.
    return this.redis.lrange(this.feedKey(userId), 0, -1);
  }
}

import { Cluster } from 'ioredis';

// Cluster seed nodes point at the masters; each master has 1 replica for failover.
const cluster = new Cluster(
  [
    { host: 'redis-master-1.internal', port: 6379 },
    { host: 'redis-master-2.internal', port: 6379 },
    { host: 'redis-master-3.internal', port: 6379 },
  ],
  {
    // scaleReads defaults to 'master' — every command, reads included,
    // is routed to the master that owns the key's hash slot.
    scaleReads: 'master',
    redisOptions: {
      password: process.env.REDIS_PASSWORD,
    },
  },
);

export class ProfileCacheService {
  /**
   * Cached, staleness-tolerant read (profile/catalog data).
   * Currently always hits the master owning this key's slot,
   * even though the value would be fine served a few hundred ms stale.
   */
  async getCachedProfile(userId: string): Promise<string | null> {
    const key = `profile:${userId}`;
    return cluster.get(key);
  }

  /**
   * Write path — must land on the master, this part is correct.
   */
  async setCachedProfile(userId: string, payload: string, ttlSeconds: number): Promise<void> {
    const key = `profile:${userId}`;
    await cluster.set(key, payload, 'EX', ttlSeconds);
  }
}

