// A separate downstream service that needs the same shard routing,
// so it re-declares its own copy of the node list and hash function.
import Redis from "ioredis";

const nodes: Redis[] = [
  new Redis({ host: "10.0.0.1", port: 6379 }),
  new Redis({ host: "10.0.0.2", port: 6379 }),
  new Redis({ host: "10.0.0.3", port: 6379 }),
];
const nodeCount = nodes.length;

function hashKey(key: string): number {
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  return hash;
}

export class ShardedRedisClient {
  getNodeFor(key: string): Redis {
    return nodes[hashKey(key) % nodeCount];
  }

  // Assumes every key in the batch lives on the same node.
  async mget(keys: string[]): Promise<(string | null)[]> {
    const node = this.getNodeFor(keys[0]);
    return node.mget(...keys);
  }
}

package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"

	consulapi "github.com/hashicorp/consul/api"
)

const (
	serviceID   = "order-service-1"
	serviceName = "order-service"
)

// buildRegistration constructs the registration payload for the local Consul
// agent. Consul expects the exact-cased fields Name/Address/Port on the
// registration struct; this payload is assembled with lowercase keys
// instead, so once it round-trips into the registration struct below,
// Address and Port come out empty/zero even though ServiceRegister itself
// returns no error.
func buildRegistration(addr string, port int) map[string]interface{} {
	return map[string]interface{}{
		"id":      serviceID,
		"name":    serviceName,
		"address": addr,
		"port":    port,
	}
}

// registerService registers this instance with the local Consul agent.
func registerService(client *consulapi.Client, addr string, port int) error {
	raw, err := json.Marshal(buildRegistration(addr, port))
	if err != nil {
		return err
	}

	var reg consulapi.AgentServiceRegistration
	if err := json.Unmarshal(raw, &reg); err != nil {
		return err
	}

	return client.Agent().ServiceRegister(&reg)
}

// healthHandler always reports healthy — there is no readiness or
// dependency check behind it.
func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprintln(w, "OK")
}

func main() {
	client, err := consulapi.NewClient(consulapi.DefaultConfig())
	if err != nil {
		log.Fatalf("failed to create consul client: %v", err)
	}

	addr := os.Getenv("ADVERTISE_ADDR")
	port := 8080

	if err := registerService(client, addr, port); err != nil {
		log.Fatalf("failed to register with consul: %v", err)
	}
	log.Printf("registered %s (%s) with local consul agent", serviceName, serviceID)

	http.HandleFunc("/health", healthHandler)
	log.Printf("%s listening on :%d", serviceName, port)
	if err := http.ListenAndServe(fmt.Sprintf(":%d", port), nil); err != nil {
		log.Fatal(err)
	}
}

// Note: main() starts the HTTP server and blocks forever. There is no
// SIGTERM/SIGINT handler and no call to client.Agent().ServiceDeregister(serviceID)
// on shutdown, and the registration above never attaches a Check block
// (HTTP/TCP interval + DeregisterCriticalServiceAfter) for Consul to
// monitor this instance's liveness.

package metrics

import (
	"strconv"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/prometheus/client_golang/prometheus"
)

// httpRequestsTotal counts every HTTP request handled by the service.
var httpRequestsTotal = prometheus.NewCounterVec(
	prometheus.CounterOpts{
		Name: "http_requests_total",
		Help: "Total number of HTTP requests processed, labeled by method, path, status code, user, and request id.",
	},
	[]string{"method", "path", "status_code", "user_id", "request_id"},
)

func init() {
	prometheus.MustRegister(httpRequestsTotal)
}

// MetricsMiddleware records one counter increment per request, labeling it
// with everything that might be useful for debugging later.
func MetricsMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next()

		method := c.Request.Method
		path := c.Request.URL.Path // raw URL, e.g. "/users/123" -- id baked inline
		statusCode := strconv.Itoa(c.Writer.Status())
		userID := c.GetHeader("X-User-Id")
		requestID := uuid.NewString()

		httpRequestsTotal.
			WithLabelValues(method, path, statusCode, userID, requestID).
			Inc()
	}
}

func SetupRouter() *gin.Engine {
	r := gin.New()
	r.Use(MetricsMiddleware())

	r.GET("/users/:id", func(c *gin.Context) {
		c.JSON(200, gin.H{"id": c.Param("id")})
	})

	return r
}

