import express from 'express';
import { context, trace } from '@opentelemetry/api';
import { rawHttpPost } from './rawHttpClient';

const app = express();
app.use(express.json());

// Auto-instrumentation wraps this inbound request in an active span, so
// context.active() here genuinely holds A's real span/traceId.
app.post('/checkout', async (req, res) => {
  const inboundSpan = trace.getSpan(context.active());
  console.log('[service-a] active traceId:', inboundSpan?.spanContext().traceId);

  // A must now call B to charge the order — but it goes through the
  // hand-rolled client above instead of an instrumented http/axios call.
  const result = await rawHttpPost('service-b', 4000, '/charge', {
    orderId: req.body.orderId,
  });
  res.send(result);
});

app.listen(3000, () => console.log('service-a listening on 3000'));

