import http from 'http';
import { propagation, ROOT_CONTEXT, trace, context } from '@opentelemetry/api';

// B's inbound HTTP instrumentation is supposed to extract context from
// every incoming request via the W3C TraceContext propagator.
const server = http.createServer((req, res) => {
  const extractedContext = propagation.extract(ROOT_CONTEXT, req.headers);

  context.with(extractedContext, () => {
    const activeSpan = trace.getSpan(context.active());
    // Because req.headers never carried a `traceparent` (A's hand-rolled
    // client never wrote one onto the wire), extract() returns an empty/
    // root context, so instrumentation here mints a brand-new root span
    // with a freshly generated traceId — the orphan trace in Jaeger.
    console.log('[service-b] active traceId:', activeSpan?.spanContext().traceId);

    let body = '';
    req.on('data', (chunk) => (body += chunk));
    req.on('end', () => {
      res.end(JSON.stringify({ charged: true }));
    });
  });
});

server.listen(4000, () => console.log('service-b listening on 4000'));

import express, { NextFunction, Request, Response } from "express";
import client from "prom-client";

const register = new client.Registry();
client.collectDefaultMetrics({ register });

const httpRequestsTotal = new client.Counter({
  name: "http_requests_total",
  help: "Total number of HTTP requests",
  labelNames: ["method", "route", "status_code"] as const,
  registers: [register],
});

const httpRequestDuration = new client.Histogram({
  name: "http_request_duration_seconds",
  help: "HTTP request duration in seconds (feeds the p95 Grafana panel)",
  labelNames: ["method", "route", "status_code"] as const,
  buckets: [0.01, 0.05, 0.1, 0.3, 0.5, 1, 2, 5],
  registers: [register],
});

/**
 * Wired BEFORE the route handler and validation middleware.
 */
function metricsMiddleware(req: Request, res: Response, next: NextFunction): void {
  const start = Date.now();

  // Reads and records immediately, at entry -- before next() runs
  // the handler and validation.
  const statusCode = res.statusCode; // still the default 200 here
  const durationSeconds = (Date.now() - start) / 1000; // ~0, no handler work has run yet

  httpRequestsTotal.inc({
    method: req.method,
    route: req.path,
    status_code: statusCode,
  });
  httpRequestDuration.observe(
    { method: req.method, route: req.path, status_code: statusCode },
    durationSeconds,
  );

  next();
}

function validateCreateOrder(req: Request, res: Response, next: NextFunction): void {
  const { amount } = req.body as { amount?: unknown };
  if (typeof amount !== "number" || amount <= 0) {
    res.status(400).json({ error: "amount must be a positive number" });
    return; // a real 400, produced after metricsMiddleware already ran
  }
  next();
}

const app = express();
app.use(express.json());
app.use(metricsMiddleware);

app.post("/orders", validateCreateOrder, (req: Request, res: Response) => {
  // Simulate real handler processing time (DB write, etc.).
  const start = Date.now();
  while (Date.now() - start < 40) {
    // busy-wait to stand in for real work
  }
  const orderId = Math.random().toString(36).slice(2);
  res.status(201).json({ orderId });
});

app.get("/metrics", async (_req: Request, res: Response) => {
  res.set("Content-Type", register.contentType);
  res.end(await register.metrics());
});

app.listen(3000);

import { Injectable, Logger } from '@nestjs/common';

interface Order {
  id: string;
  sku: string;
  quantity: number;
}

interface InventoryClient {
  reserve(order: Order): Promise<void>;
}

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(private readonly inventory: InventoryClient) {}

  /**
   * Places an order by reserving inventory for it.
   */
  async placeOrder(order: Order): Promise<{ status: string }> {
    try {
      await this.inventory.reserve(order);
    } catch (err) {
      // PR author's comment:
      // "No need to rethrow here — we log at ERROR level, so this failure
      // is tracked. Falling through keeps the checkout flow from crashing
      // over a downstream hiccup."
      this.logger.error('failed to reserve inventory', err);
      return { status: 'ok' };
    }

    return { status: 'ok' };
  }
}

import express, { Request, Response, NextFunction } from 'express'

declare const db: {
  query: (sql: string, callback: (err: Error | null) => void) => void
}

// Negative-security blocklist: regex signatures for known SQLi/XSS payloads.
const rules: RegExp[] = [
  /(\%27)|(\')|(\-\-)|(\%23)|(#)/i, // SQLi: quote / comment markers
  /((\%3D)|(=))[^\n]*((\%27)|(\')|(\-\-)|(\%3B)|(;))/i, // SQLi: assignment + statement terminator
  /\w*((\%27)|('))((\%6F)|o|(\%4F))((\%72)|r|(\%52))/i, // SQLi: ' or
  /((\%3C)|<)((\%2F)|\/)*[a-z0-9\%]+((\%3E)|>)/i, // XSS: generic <tag>
  /((\%3C)|<)((\%69)|i|(\%49))((\%6D)|m|(\%4D))((\%67)|g|(\%47))/i, // XSS: <img
  /((\%3C)|<)[^\n]+((\%3E)|>)/i // XSS: any bracketed tag
]

/**
 * Home-grown WAF: blocks a request whose body matches a known SQLi/XSS signature.
 */
function wafMiddleware(req: Request, res: Response, next: NextFunction): void {
  const payload = JSON.stringify(req.body)

  for (const rule of rules) {
    if (rule.test(payload)) {
      res.status(403).json({ status: 'blocked', input: payload })
      return
    }
  }

  next()
}

const app = express()
app.use(express.json())

// Mounted on the main API route group only.
app.use('/api', wafMiddleware)

app.post('/api/comments', (req: Request, res: Response) => {
  const { author, text } = req.body

  // The WAF above is the only guard here - no parameterization or output encoding.
  const query = `INSERT INTO comments (author, text) VALUES ('${author}', '${text}')`

  db.query(query, (err: Error | null) => {
    if (err) {
      res.status(500).json({ status: 'error' })
      return
    }
    res.status(201).json({ status: 'created' })
  })
})

export { app, wafMiddleware, rules }

package pii

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
)

// Record is a row holding a locally-encrypted PII field alongside the
// per-record DEK that protected it, itself wrapped by Vault Transit under
// a master key. One DEK per record bounds the blast radius if a single
// DEK is ever compromised, and destroying the master key crypto-shreds
// every record at once.
type Record struct {
	ID         string
	Ciphertext []byte // AES-GCM ciphertext, encrypted locally with the record's DEK
	WrappedDEK []byte // the record's DEK, wrapped (encrypted) by Vault Transit
	Nonce      []byte // AES-GCM nonce used for Ciphertext
}

// VaultClient talks to a single Vault Transit instance. There is no
// secondary address or load-balanced endpoint here, so this node is a
// single point of failure for every decrypt on the hot read path.
type VaultClient struct {
	Address   string // e.g. "https://vault.internal:8200" - single node
	Token     string
	TransitKey string // name of the Transit key used to wrap/unwrap DEKs
	HTTP      *http.Client
}

type transitDecryptRequest struct {
	Ciphertext string `json:"ciphertext"`
}

type transitDecryptResponse struct {
	Data struct {
		Plaintext string `json:"plaintext"`
	} `json:"data"`
}

// unwrapDEK sends the wrapped DEK to Vault Transit's decrypt endpoint and
// returns the plaintext DEK. There is no cache here: every single call to
// unwrapDEK fires a fresh HTTP round-trip to Vault, which is the cost that
// dominates the read path profile - re-reading the same record seconds
// later re-unwraps its DEK from scratch.
func (vc *VaultClient) unwrapDEK(wrappedDEK []byte) ([]byte, error) {
	reqBody := transitDecryptRequest{
		Ciphertext: string(wrappedDEK),
	}
	buf, err := json.Marshal(reqBody)
	if err != nil {
		return nil, fmt.Errorf("marshal transit decrypt request: %w", err)
	}

	url := fmt.Sprintf("%s/v1/transit/decrypt/%s", vc.Address, vc.TransitKey)
	req, err := http.NewRequest(http.MethodPost, url, bytes.NewReader(buf))
	if err != nil {
		return nil, fmt.Errorf("build transit decrypt request: %w", err)
	}
	req.Header.Set("X-Vault-Token", vc.Token)
	req.Header.Set("Content-Type", "application/json")

	resp, err := vc.HTTP.Do(req)
	if err != nil {
		// Vault is directly on the hot read path with no failover target:
		// if this single node is down or slow, every decrypt below fails.
		return nil, fmt.Errorf("vault transit decrypt call: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("vault transit decrypt failed: status %d", resp.StatusCode)
	}

	var out transitDecryptResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, fmt.Errorf("decode transit decrypt response: %w", err)
	}

	dek, err := base64.StdEncoding.DecodeString(out.Data.Plaintext)
	if err != nil {
		return nil, fmt.Errorf("decode plaintext DEK: %w", err)
	}
	return dek, nil
}

// decryptField unwraps the record's DEK via Vault, then AES-GCM-decrypts
// the local ciphertext with it. A single field read costs one Vault
// round-trip.
func (vc *VaultClient) decryptField(record Record) ([]byte, error) {
	dek, err := vc.unwrapDEK(record.WrappedDEK)
	if err != nil {
		return nil, fmt.Errorf("unwrap DEK for record %s: %w", record.ID, err)
	}

	block, err := aes.NewCipher(dek)
	if err != nil {
		return nil, fmt.Errorf("init aes cipher: %w", err)
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("init gcm: %w", err)
	}

	plaintext, err := gcm.Open(nil, record.Nonce, record.Ciphertext, nil)
	if err != nil {
		return nil, fmt.Errorf("aes decrypt record %s: %w", record.ID, err)
	}
	return plaintext, nil
}

// decryptBatch decrypts every record in a listing/batch read. It loops
// over the records and calls unwrapDEK once per record inside the loop -
// that's one Vault HTTP call per record, i.e. an N+1 against the KMS for
// a batch of N records. Nothing here uses Vault Transit's batch_input to
// collapse this into a single round-trip.
func (vc *VaultClient) decryptBatch(records []Record) ([][]byte, error) {
	results := make([][]byte, 0, len(records))
	for _, record := range records {
		plaintext, err := vc.decryptField(record) // <- N Vault round-trips for N records
		if err != nil {
			return nil, err
		}
		results = append(results, plaintext)
	}
	return results, nil
}

// ---- Data model ----------------------------------------------------------

interface AuditRecord {
  index: number;       // monotonic position, genesis = 0
  payload: string;     // the security event, serialized
  prevHash: string;    // entryHash of the previous record (GENESIS for index 0)
  entryHash: string;   // computeHash(index, payload, prevHash)
}

const GENESIS = "0".repeat(64); // fixed zero hash, prevHash of the genesis row

function computeHash(index: number, payload: string, prevHash: string): string {
  return sha256(`${index}:${payload}:${prevHash}`);
}

// Minimal repo interface backing the append-only `auditLog` table/collection.
interface AuditLogRepo {
  findLast(): Promise<AuditRecord | null>;
  findAll(options: { orderBy: "index"; direction: "ASC" }): Promise<AuditRecord[]>;
  insert(record: AuditRecord): Promise<void>;
}

class AuditLog {
  constructor(private readonly repo: AuditLogRepo) {}

  // ---- Append path (correct — not the thing to optimize) ----------------

  async append(payload: string): Promise<AuditRecord> {
    const last = await this.repo.findLast();
    const index = last ? last.index + 1 : 0;
    const prevHash = last ? last.entryHash : GENESIS;
    const entryHash = computeHash(index, payload, prevHash);

    const record: AuditRecord = { index, payload, prevHash, entryHash };
    await this.repo.insert(record);
    return record;
  }

  // ---- Hot path: verify() -------------------------------------------------
  // Called on essentially every request via the integrity probe below.
  // Re-reads and re-hashes the ENTIRE chain from genesis every single call.

  async verify(): Promise<boolean> {
    // Full-table scan, no bound — materializes millions of rows in memory.
    const rows = await this.repo.findAll({ orderBy: "index", direction: "ASC" });

    let prevHash = GENESIS;
    for (const row of rows) {
      const expected = computeHash(row.index, row.payload, prevHash);
      if (expected !== row.entryHash) {
        return false;
      }
      prevHash = row.entryHash;
    }
    return true;
  }
}

// ---- Integrity probe: hits verify() on essentially every request ---------

class IntegrityController {
  constructor(private readonly auditLog: AuditLog) {}

  // @Get('/integrity')
  async checkIntegrity(): Promise<{ ok: boolean }> {
    const ok = await this.auditLog.verify();
    return { ok };
  }
}

