import { Client } from '@elastic/elasticsearch';
import { Kafka } from 'kafkajs';

const es = new Client({ node: process.env.ES_NODE ?? 'http://localhost:9200' });
const INDEX = 'products';

interface DebeziumEnvelope {
  op: 'c' | 'u' | 'r' | 'd';
  before: Record<string, unknown> | null;
  after: Record<string, unknown> | null;
}

/**
 * Applies a single Debezium change event to the Elasticsearch index.
 */
async function handleMessage(rawValue: string): Promise<void> {
  const { op, after, before } = JSON.parse(rawValue) as DebeziumEnvelope;
  const id = String((after ?? before)!.id);

  switch (op) {
    case 'c':
    case 'u':
    case 'r':
      // Mirror the row image into ES.
      await es.create({ index: INDEX, id, document: after });
      break;
    case 'd':
      // Remove the row from ES.
      await es.delete({ index: INDEX, id });
      break;
    default:
      // Unknown op, nothing to do.
      break;
  }
}

const kafka = new Kafka({ clientId: 'es-mirror', brokers: [process.env.KAFKA_BROKER ?? 'localhost:9092'] });
const consumer = kafka.consumer({ groupId: 'es-mirror-group' });

async function run(): Promise<void> {
  await consumer.connect();
  await consumer.subscribe({ topic: 'products', fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ message }) => {
      // Offset is only committed by the consumer group after this resolves,
      // so an uncaught throw here blocks the commit and the message gets redelivered.
      await handleMessage(message.value!.toString());
    },
  });
}

run().catch((err) => {
  console.error('consumer crashed', err);
  process.exit(1);
});

